INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f2b88c2-40e1-4095-b449-107411eaa74b', '送僧', '送僧', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["梵王生別思，之子事遐征。","煙水浮杯渡，雲山隻履行。","三生塵夢醒，一錫衲衣輕。","此去家林近，飄飄物外情。"]', '["梵王生別思，之子事遐征。","煙水浮杯渡，云山隻履行。","三生塵梦醒，一錫衲衣轻。","此去家林近，飄飄物外情。"]', '诗', 'shi', '', NULL, '送僧 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a902c04-8ad9-4f73-9fd8-9e4340dee965', '送友人', '送友人', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["有客櫂扁舟，相逢不暫留。","衣冠重文物，詩酒足風流。","官路生歸興，家林想舊遊。","臨岐分手後，乘月過蘇州。"]', '["有客櫂扁舟，相逢不暫留。","衣冠重文物，诗酒足风流。","官路生归兴，家林想旧游。","臨岐分手後，乘月過蘇州。"]', '诗', 'shi', '', NULL, '送友人 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b95f1d2a-0b4f-45df-8eb2-aae906c694a6', '題朱慶餘閑居四首 一', '題朱慶餘闲居四首 一', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["瀟灑藏脩處，琴書與畫圖。","白丁門外遠，俗子眼前無。","楚楚臨軒竹，青青映水蒲。","道人能愛靜，諸事近清枯。"]', '["瀟灑藏脩处，琴书與畫圖。","白丁门外远，俗子眼前無。","楚楚臨軒竹，青青映水蒲。","道人能愛静，諸事近清枯。"]', '诗', 'shi', '', NULL, '題朱慶餘閑居四首 一 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f32064-b036-48ed-942a-b4e62130bf12', '題朱慶餘閑居四首 二', '題朱慶餘闲居四首 二', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["盡日衡門閉，蒼苔一徑新。","客心非厭靜，悟道不憂貧。","白屋懸塵榻，清樽憶故人。","近來疎懶甚，詩債後吟身。"]', '["尽日衡门閉，蒼苔一徑新。","客心非厭静，悟道不憂貧。","白屋懸塵榻，清樽憶故人。","近来疎懶甚，诗債後吟身。"]', '诗', 'shi', '', NULL, '題朱慶餘閑居四首 二 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf84325-f427-4c29-a7ea-1b260fc51f82', '題朱慶餘閑居四首 三', '題朱慶餘闲居四首 三', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["閑客幽棲處，瀟然一草廬。","路通元亮宅，門對子雲居。","按劒心猶壯，琴書樂有餘。","黃金都散盡，收得鄴侯書。"]', '["闲客幽棲处，瀟然一草廬。","路通元亮宅，门对子云居。","按劒心猶壯，琴书乐有餘。","黄金都散尽，收得鄴侯书。"]', '诗', 'shi', '', NULL, '題朱慶餘閑居四首 三 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d9840a-ce29-4a20-ad28-e1b6b7988399', '題朱慶餘閑居四首 四', '題朱慶餘闲居四首 四', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["寂寥荒館下，投老欲何爲。","草色凝陳榻，書聲出董帷。","閑雲長作伴，歸鶴獨相隨。","才薄知無用，安貧不自危。"]', '["寂寥荒館下，投老欲何爲。","草色凝陳榻，书声出董帷。","闲云长作伴，归鹤独相隨。","才薄知無用，安貧不自危。"]', '诗', 'shi', '', NULL, '題朱慶餘閑居四首 四 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d31c3d7-cf58-4292-8c48-3849855a7dfe', '寄張源', '寄張源', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["咫尺西江路，悲歡暫莫聞。","青年俱未達，白社獨離羣。","曲徑荒秋草，衡茅掩夕曛。","相思不相見，愁絕賦停雲。"]', '["咫尺西江路，悲歡暫莫闻。","青年俱未達，白社独離羣。","曲徑荒秋草，衡茅掩夕曛。","相思不相见，愁絕賦停云。"]', '诗', 'shi', '', NULL, '寄張源 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941c12ec-7d72-4d86-b9f1-9c5057fae10c', '題竹', '題竹', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["瀟灑碧玉枝，清風追晉賢。","數點渭川雨，一縷湘江煙。","不見鳳皇尾，誰識珊瑚鞭。","柯亭丁相遇，驚聽奏鈞天。"]', '["瀟灑碧玉枝，清风追晉賢。","數点渭川雨，一縷湘江煙。","不见鳳皇尾，誰識珊瑚鞭。","柯亭丁相遇，驚听奏鈞天。"]', '诗', 'shi', '', NULL, '題竹 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95329e84-1101-42c8-a307-221afe9adedf', '有感', '有感', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["盛世嗟沈伏，中情怏未舒。","途窮悲阮籍，病久憶相如。","無客空塵榻，閑門閉草廬。","不勝岑絕處，高臥半牀書。"]', '["盛世嗟沈伏，中情怏未舒。","途窮悲阮籍，病久憶相如。","無客空塵榻，闲门閉草廬。","不勝岑絕处，高臥半牀书。"]', '诗', 'shi', '', NULL, '有感 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5af83c-c12a-4be9-9cd9-527685541f38', '題山房壁', '題山房壁', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["珠林春寂寂，寶地夜沈沈。","玄奧凝神久，禪機入妙深。","參同大塊理，窺測至人心。","定處波羅蜜，須從物外尋。"]', '["珠林春寂寂，寶地夜沈沈。","玄奧凝神久，禪機入妙深。","參同大塊理，窺測至人心。","定处波羅蜜，須從物外尋。"]', '诗', 'shi', '', NULL, '題山房壁 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092cd738-8136-43ef-9316-8ad09aa8b6be', '訪請上人', '訪請上人', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["曲徑遶叢林，鐘聲雜梵音。","松風吹定衲，蘿月照禪心。","撫景吟行遠，談玄入悟深。","不能塵鞅脫，聊復一登臨。"]', '["曲徑遶叢林，鐘声杂梵音。","松风吹定衲，蘿月照禪心。","撫景吟行远，談玄入悟深。","不能塵鞅脫，聊复一登臨。"]', '诗', 'shi', '', NULL, '訪請上人 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e265dd-c04b-4ce7-b253-9c1bd436bcc6', '送范啓東', '送范啓东', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["楊柳春江上，東風一櫂輕。","行囊歸客興，尊酒故人情。","畫史名當代，聲華重兩京。","臨岐分手處，無奈別離生。"]', '["楊柳春江上，东风一櫂轻。","行囊归客兴，尊酒故人情。","畫史名當代，声华重兩京。","臨岐分手处，無奈別離生。"]', '诗', 'shi', '', NULL, '送范啓東 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151c740c-79b9-41e6-8e76-a087145df87a', '客中作', '客中作', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["十年江漢客，幾度帝京遊。","跡比風前葉，身如水上鷗。","醉吟愁裏月，羞對鏡中秋。","悵望頻回首，西風憶故丘。"]', '["十年江漢客，幾度帝京游。","跡比风前葉，身如水上鷗。","醉吟愁裏月，羞对镜中秋。","悵望頻回首，西风憶故丘。"]', '诗', 'shi', '', NULL, '客中作 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44570ebc-6f0d-4230-8b79-50c392b095ac', '贈韓翃', '贈韓翃', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["京國久知名，江河近識荆。","不辭今日醉，便有故人情。","細雨孤鴻遠，西風一櫂輕。","暫時分手去，應不負詩盟。"]', '["京国久知名，江河近識荆。","不辞今日醉，便有故人情。","細雨孤鴻远，西风一櫂轻。","暫时分手去，應不負诗盟。"]', '诗', 'shi', '', NULL, '贈韓翃 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a7c5b6b-7d8b-40fd-a4f1-1ab8962a0826', '禁煙作', '禁煙作', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["柳拖金縷拂朱欄，花撲香塵滿繡鞍。","尊酒臨風酬令節，越羅衣薄覺春寒。"]', '["柳拖金縷拂朱欄，花撲香塵满繡鞍。","尊酒臨风酬令節，越羅衣薄覺春寒。"]', '诗', 'shi', '', NULL, '禁煙作 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854a5f66-f4b6-49dd-b2d5-f8e873246c66', '閩中回', '閩中回', '7ed4d16b-371b-444d-a64b-593186f8eb91', '唐', '["帆影隨風過富陽，櫓聲搖月下錢塘。","千山積雪凝寒碧，夢入楓宸遶御牀。"]', '["帆影隨风過富陽，櫓声搖月下錢塘。","千山積雪凝寒碧，梦入楓宸遶御牀。"]', '诗', 'shi', '', NULL, '閩中回 牟融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e7a0f84-0c9b-4318-b378-8691bb22a63a', '苦婦詞', '苦婦词', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["地遠易驕崇，用刑匪精研。","哀哉苦婦身，夫死百殃纏。","草草催出門，衣墮髮披肩。","獨隨軍吏行，當夕余欲遷。","來時已厭生，到此自不全。","臨江臥黃砂，二子死在邊。","氣噦不發聲，背頭血涓涓。","有時強爲言，祗是尤青天。","藳蓐無一枝，冷氣兩懸懸。","窮荒夷教卑，骨肉病棄捐。","況非本族音，肌露誰爲憐。","事痛感行賓，住得貪程船。","必當負嚴法，豈有胎孕篇。","遊畋復釋麛，羔兔尚免鸇。","何處擯逐深，一罪三見顛。","校尉勳望重，幕府才且賢。","蘭裙間珠履，食玉處花筵。","但勿輕所暗，莫慮無人焉。"]', '["地远易驕崇，用刑匪精研。","哀哉苦婦身，夫死百殃纏。","草草催出门，衣墮髮披肩。","独隨軍吏行，當夕余欲遷。","来时已厭生，到此自不全。","臨江臥黄砂，二子死在邊。","氣噦不發声，背头血涓涓。","有时強爲言，祗是尤青天。","藳蓐無一枝，冷氣兩懸懸。","窮荒夷教卑，骨肉病棄捐。","況非本族音，肌露誰爲怜。","事痛感行賓，住得貪程船。","必當負嚴法，豈有胎孕篇。","游畋复釋麛，羔兔尚免鸇。","何处擯逐深，一罪三见顛。","校尉勳望重，幕府才且賢。","蘭裙间珠履，食玉处花筵。","但勿轻所暗，莫慮無人焉。"]', '诗', 'shi', '', NULL, '苦婦詞 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f085ee-d6b5-4461-9197-8ada7ead97fe', '與孟郊洛北野泉上煎茶', '與孟郊洛北野泉上煎茶', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["粉細越笋芽，野煎寒溪濱。","恐乖靈草性，觸事皆手親。","敲石取鮮火，撇泉避腥鱗。","熒熒爨風鐺，拾得墜巢薪。","潔色既爽別，浮氳亦慇懃。","以茲委曲靜，求得正味真。","宛如摘山時，自歠指下春。","湘瓷泛輕花，滌盡昏渴神。","此遊愜醒趣，可以話高人。"]', '["粉細越笋芽，野煎寒溪濱。","恐乖靈草性，觸事皆手親。","敲石取鲜火，撇泉避腥鱗。","熒熒爨风鐺，拾得墜巢薪。","潔色既爽別，浮氳亦慇懃。","以茲委曲静，求得正味真。","宛如摘山时，自歠指下春。","湘瓷泛轻花，滌尽昏渴神。","此游愜醒趣，可以話高人。"]', '诗', 'shi', '', NULL, '與孟郊洛北野泉上煎茶 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf438e2b-71eb-4b9a-bafc-171e9c1b3a60', '七夕歌', '七夕歌', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["星寥寥兮月細輪，佳期可想兮不可親。","雲衣香薄粧態新，彩軿悠悠度天津。","玉幌相逢夜將極，妖紅慘黛生愁色。","寂寞低容入舊機，歇著金梭思往夕。","人間不見因誰知，萬家閨豔求此時。","碧空露重彩盤濕，花上乞得蜘蛛絲。"]', '["星寥寥兮月細輪，佳期可想兮不可親。","云衣香薄粧態新，彩軿悠悠度天津。","玉幌相逢夜將極，妖紅慘黛生愁色。","寂寞低容入旧機，歇著金梭思往夕。","人间不见因誰知，万家閨豔求此时。","碧空露重彩盤濕，花上乞得蜘蛛絲。"]', '诗', 'shi', '', NULL, '七夕歌 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308cd53c-fc61-4dde-899e-a4db10cb3302', '立秋日', '立秋日', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["商風動葉初，蕭索一貧居。","老性容茶少，羸肌與簟疎。","舊醅難重漉，新菜未勝鉏。","才薄無潘興，便便畫偃廬。"]', '["商风动葉初，蕭索一貧居。","老性容茶少，羸肌與簟疎。","旧醅难重漉，新菜未勝鉏。","才薄無潘兴，便便畫偃廬。"]', '诗', 'shi', '', NULL, '立秋日 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83155f4e-a52e-4787-8b9f-5f160fb8f59c', '題茅山仙臺藥院', '題茅山仙台藥院', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["擾擾浮生外，華陽一洞春。","道書金字小，仙圃玉苗新。","芝草迎飛燕，桃花笑俗人。","樓臺爭聳漢，雞犬亦嫌秦。","願得青芽散，長年駐此身。"]', '["擾擾浮生外，华陽一洞春。","道书金字小，仙圃玉苗新。","芝草迎飞燕，桃花笑俗人。","楼台爭聳漢，雞犬亦嫌秦。","願得青芽散，长年駐此身。"]', '诗', 'shi', '', NULL, '題茅山仙臺藥院 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('debf0e3c-9f40-43cf-8102-ce0c7852f93c', '送婆羅門歸本國', '送婆羅门归本国', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["剎利王孫字迦攝，竹錐橫寫叱蘿葉。","遙知漢地未有經，手牽白馬遶天行。","龜茲磧西胡雪黑，大師凍死來不得。","地盡年深始到船，海裏更行三十國。","行多耳斷金環落，冉冉悠悠不停脚。","馬死經留却去時，往來應盡一生期。","出漠獨行人絕處，磧西天漏雨絲絲。"]', '["剎利王孫字迦攝，竹錐橫寫叱蘿葉。","遙知漢地未有經，手牽白马遶天行。","龟茲磧西胡雪黑，大師凍死来不得。","地尽年深始到船，海裏更行三十国。","行多耳斷金环落，冉冉悠悠不停脚。","马死經留却去时，往来應尽一生期。","出漠独行人絕处，磧西天漏雨絲絲。"]', '诗', 'shi', '', NULL, '送婆羅門歸本國 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f8b1f28-3851-4b7f-bd62-2b63eb67793d', '瀟湘遊', '瀟湘游', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["夷女采山蕉，緝紗浸江水。","野花滿髻妝色新，閑歌[欸]乃深峽裏。","[欸]乃知從何處生，當時泣舜腸斷聲。","翠華寂寞嬋娟沒，野篠空餘紅淚情。","青煙冥冥覆杉桂，崖壁凌天風雨細。","昔人幽恨此地遺，綠芳紅豔含怨姿。","清猨未盡鼯鼠切，淚水流到湘妃祠。","北人莫作瀟湘遊，九疑雲入蒼梧愁。"]', '["夷女采山蕉，緝紗浸江水。","野花满髻妝色新，闲歌[欸]乃深峽裏。","[欸]乃知從何处生，當时泣舜腸斷声。","翠华寂寞嬋娟沒，野篠空餘紅泪情。","青煙冥冥覆杉桂，崖壁凌天风雨細。","昔人幽恨此地遺，綠芳紅豔含怨姿。","清猨未尽鼯鼠切，泪水流到湘妃祠。","北人莫作瀟湘游，九疑云入蒼梧愁。"]', '诗', 'shi', '', NULL, '瀟湘遊 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97bdc1a3-da7a-46b1-a6f3-effdb768335c', '放螢怨', '放螢怨', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["放螢去，不須留，聚時年少今白頭。","架中科斗萬餘卷，一字千回重照見。","青雲杳渺不可親，開囊欲放增餘怨。","且逍遙，還酩酊，仲舒漫不窺園井。","那將寂寞老病身，更就微蟲借光影。","欲放時，淚沾裳，衝籬落，千點光。"]', '["放螢去，不須留，聚时年少今白头。","架中科斗万餘卷，一字千回重照见。","青云杳渺不可親，开囊欲放增餘怨。","且逍遙，還酩酊，仲舒漫不窺园井。","那將寂寞老病身，更就微蟲借光影。","欲放时，泪沾裳，衝籬落，千点光。"]', '诗', 'shi', '', NULL, '放螢怨 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f45d47f8-14cf-4462-b963-db53411723ec', '觀繩伎', '观繩伎', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["泰陵遺樂何最珍，綵繩冉冉天仙人。","廣場寒食風日好，百夫伐鼓錦臂新。","銀畫青綃抹雲髮，高處綺羅香更切。","重肩接立三四層，著屐背行仍應節。","兩邊丸劒漸相迎，側身交步何輕盈。","閃然欲落却收得，萬人肉上寒毛生。","危機險勢無不有，倒挂纖腰學垂柳。","下來一一芙蓉姿，粉薄鈿稀態轉奇。","坐中還有沾巾者，曾見先皇初教時。"]', '["泰陵遺乐何最珍，綵繩冉冉天仙人。","廣場寒食风日好，百夫伐鼓錦臂新。","銀畫青綃抹云髮，高处綺羅香更切。","重肩接立三四層，著屐背行仍應節。","兩邊丸劒漸相迎，側身交步何轻盈。","閃然欲落却收得，万人肉上寒毛生。","危機險勢無不有，倒挂纖腰学垂柳。","下来一一芙蓉姿，粉薄鈿稀態轉奇。","坐中還有沾巾者，曾见先皇初教时。"]', '诗', 'shi', '', NULL, '觀繩伎 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5942196-b9e8-4ee2-a96a-2130cde47cbb', '買花謠', '買花謠', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["杜陵村人不田穡，入谷經谿復緣壁。","每至南山草木春，即向侯家取金碧。","幽豔凝華春景曙，林夫移得將何處。","蝶惜芳叢送下山，尋斷孤香始回去。","豪少居連鳷鵲東，千金使買一株紅。","院多花少栽未得，零落綠娥纖指中。","咸陽親戚長安里，無限將金買花子。","澆紅溼綠千萬家，青絲玉轤聲啞啞。"]', '["杜陵村人不田穡，入谷經谿复緣壁。","每至南山草木春，即向侯家取金碧。","幽豔凝华春景曙，林夫移得將何处。","蝶惜芳叢送下山，尋斷孤香始回去。","豪少居連鳷鵲东，千金使買一株紅。","院多花少栽未得，零落綠娥纖指中。","咸陽親戚长安里，無限將金買花子。","澆紅溼綠千万家，青絲玉轤声啞啞。"]', '诗', 'shi', '', NULL, '買花謠 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a22c9e9b-2ac1-4bc1-a2ff-0d4e853748e0', '王中丞宅夜觀舞胡騰', '王中丞宅夜观舞胡腾', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["石國胡兒人見少，蹲舞尊前急如鳥。","織成蕃帽虛頂尖，細氎胡衫雙袖小。","手中拋下蒲萄盞，西顧忽思鄉路遠。","跳身轉轂寶帶鳴，弄脚繽紛錦靴軟。","四座無言皆瞪目，橫笛琵琶徧頭促。","亂騰新毯雪朱毛，傍拂輕花下紅燭。","酒闌舞罷絲管絕，木槿花西見殘月。"]', '["石国胡兒人见少，蹲舞尊前急如鸟。","织成蕃帽虛頂尖，細氎胡衫雙袖小。","手中拋下蒲萄盞，西顧忽思乡路远。","跳身轉轂寶带鳴，弄脚繽紛錦靴軟。","四座無言皆瞪目，橫笛琵琶徧头促。","亂腾新毯雪朱毛，傍拂轻花下紅燭。","酒闌舞罷絲管絕，木槿花西见殘月。"]', '诗', 'shi', '', NULL, '王中丞宅夜觀舞胡騰 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9debbe96-77b3-4b24-ab2d-7c3afc4a9245', '竹裏梅', '竹裏梅', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["竹裏梅花相竝枝，梅花正發竹枝垂。","風吹總向竹枝上，直似王家雪下時。"]', '["竹裏梅花相竝枝，梅花正發竹枝垂。","风吹總向竹枝上，直似王家雪下时。"]', '诗', 'shi', '', NULL, '竹裏梅 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d6dc622-41f0-47a1-956b-e2e37a6d9d97', '春過趙墟', '春過趙墟', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["下馬邯鄲陌頭歇，寂寥崩隧臨車轍。","古柏重生枝亦乾，餘燎見風幽燄滅。","白蒿微發紫槿新，行人感此復悲春。"]', '["下马邯鄲陌头歇，寂寥崩隧臨车轍。","古柏重生枝亦乾，餘燎见风幽燄滅。","白蒿微發紫槿新，行人感此复悲春。"]', '诗', 'shi', '', NULL, '春過趙墟 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7909697a-00a4-4e4e-b709-f2868012c347', '初下東周贈孟郊', '初下东周贈孟郊', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["鶴老身更卬，龜死殼亦靈。","正信非外沿，終始全本情。","童子不戲塵，積書就巖扃。","身著木葉衣，養鹿兼牸耕。","偶隨下山雲，荏苒失故程。","漸入機險中，危思難太行。","十髮九縷絲，悠然東周城。","言詞野麋態，出口多累形。","因依漢元寮，未思羇細輕。","[冷]竈助新熱，靜砧與寒聲。","斷蓬在門欄，豈當桃李榮。","寄食若蠹蟲，侵損利微生。","固非拙爲強，懦劣外療幷。","素堅冰蘖心，潔持保堅貞。","修文返正風，刊字齊古經。","慙將衰末分，高棲喧世名。"]', '["鹤老身更卬，龟死殼亦靈。","正信非外沿，終始全本情。","童子不戲塵，積书就巖扃。","身著木葉衣，養鹿兼牸耕。","偶隨下山云，荏苒失故程。","漸入機險中，危思难太行。","十髮九縷絲，悠然东周城。","言词野麋態，出口多累形。","因依漢元寮，未思羇細轻。","[冷]竈助新熱，静砧與寒声。","斷蓬在门欄，豈當桃李榮。","寄食若蠹蟲，侵損利微生。","固非拙爲強，懦劣外療幷。","素堅冰蘖心，潔持保堅貞。","修文返正风，刊字齊古經。","慙將衰末分，高棲喧世名。"]', '诗', 'shi', '', NULL, '初下東周贈孟郊 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60e1af46-66be-43d8-a2ad-94a12302cab2', '過春秋峽', '過春秋峽', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["峭壁蒼蒼苔色新，無風晴景自勝春。","不知何樹幽崖裏，臘月開花似北人。"]', '["峭壁蒼蒼苔色新，無风晴景自勝春。","不知何樹幽崖裏，臘月开花似北人。"]', '诗', 'shi', '', NULL, '過春秋峽 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c63bd0-63fa-4596-b2f0-5e12338b05b7', '長門怨', '长门怨', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["獨坐爐邊結夜愁，暫時思去亦難留。","手持金筯垂紅淚，亂撥寒灰不舉頭。"]', '["独坐爐邊結夜愁，暫时思去亦难留。","手持金筯垂紅泪，亂撥寒灰不舉头。"]', '诗', 'shi', '', NULL, '長門怨 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f133634b-1548-4a95-86ca-f80023f85859', '春遊曲 一', '春游曲 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["花頷紅騣一何偏，綠槐香陌欲朝天。","仍嫌衆裏嬌行疾，傍𩍐深藏白玉鞭。"]', '["花頷紅騣一何偏，綠槐香陌欲朝天。","仍嫌衆裏嬌行疾，傍𩍐深藏白玉鞭。"]', '诗', 'shi', '', NULL, '春遊曲 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f48ef3-a731-43b3-9464-67870b443044', '春遊曲 二', '春游曲 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["噴沫團香小桂條，玉鞭兼賜霍嫖姚。","弄影便從天禁出，碧蹄聲碎五門橋。"]', '["噴沫團香小桂條，玉鞭兼賜霍嫖姚。","弄影便從天禁出，碧蹄声碎五门橋。"]', '诗', 'shi', '', NULL, '春遊曲 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b37edae0-497b-4ba6-a5d7-0ea0adbc3e3f', '廣州王園寺伏日即事寄北中親友', '廣州王园寺伏日即事寄北中親友', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["南越逢初伏，東林度一朝。","曲池煎畏景，高閣絕微飇。","竹簟移先灑，蒲葵破復搖。","地偏毛瘴近，山毒火威饒。","裛汗絺如濯，親牀枕竝燒。","墮枝傷翠羽，萎葉惜紅蕉。","且困流金熾，難成獨酌謠。","望霖窺潤礎，思吹候生條。","旅恨生烏滸，鄉心繫洛橋。","誰憐在炎客，一夕壯容銷。"]', '["南越逢初伏，东林度一朝。","曲池煎畏景，高閣絕微飇。","竹簟移先灑，蒲葵破复搖。","地偏毛瘴近，山毒火威饒。","裛汗絺如濯，親牀枕竝燒。","墮枝傷翠羽，萎葉惜紅蕉。","且困流金熾，难成独酌謠。","望霖窺潤礎，思吹候生條。","旅恨生烏滸，乡心繫洛橋。","誰怜在炎客，一夕壯容銷。"]', '诗', 'shi', '', NULL, '廣州王園寺伏日即事寄北中親友 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be6139d-9f86-4c80-8689-babed4019d9f', '立秋', '立秋', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["茲晨戒流火，商飇早已驚。","雲天收夏色，木葉動秋聲。"]', '["茲晨戒流火，商飇早已驚。","云天收夏色，木葉动秋声。"]', '诗', 'shi', '', NULL, '立秋 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4cf3361-d8ac-48f7-9120-f58bff432536', '別落花', '別落花', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["風豔霏霏去，羈人處處游。","明年縱相見，不在此枝頭。"]', '["风豔霏霏去，羈人处处游。","明年縱相见，不在此枝头。"]', '诗', 'shi', '', NULL, '別落花 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2b2d38c-9a11-48df-a7be-a47c3aa44e0e', '登甘露臺', '登甘露台', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["偶至無塵空翠間，雨花甘露境閑閑。","身心未寂終爲累，非想天中獨退還。"]', '["偶至無塵空翠间，雨花甘露境闲闲。","身心未寂終爲累，非想天中独退還。"]', '诗', 'shi', '', NULL, '登甘露臺 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcfd4a4f-69d0-4de5-b609-28eb7608c9bb', '夜泊潤州江口', '夜泊潤州江口', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["秋江欲起白頭波，賈客瞻風無渡河。","千船火絕寒宵半，獨聽鐘聲覺寺多。"]', '["秋江欲起白头波，賈客瞻风無渡河。","千船火絕寒宵半，独听鐘声覺寺多。"]', '诗', 'shi', '', NULL, '夜泊潤州江口 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2d1b5b7-a667-462c-bc61-5cd7ebde7bcc', '看山木瓜花二首 一', '看山木瓜花二首 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["裛露凝氛紫豔新，千般婉娜不勝春。","年年此樹花開日，出盡丹陽郭裏人。"]', '["裛露凝氛紫豔新，千般婉娜不勝春。","年年此樹花开日，出尽丹陽郭裏人。"]', '诗', 'shi', '', NULL, '看山木瓜花二首 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d9a74e6-a65c-497f-bbd0-9f5d37d4255d', '看山木瓜花二首 二', '看山木瓜花二首 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["柔枝濕豔亞朱欄，暫作庭芳便欲殘。","深藏數片將歸去，紅縷金針繡取看。"]', '["柔枝濕豔亞朱欄，暫作庭芳便欲殘。","深藏數片將归去，紅縷金針繡取看。"]', '诗', 'shi', '', NULL, '看山木瓜花二首 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5d3922-f997-44f7-8cc7-72b017e320f8', '題十三弟竹園', '題十三弟竹园', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["繞屋扶疎聳翠莖，苔滋粉漾有幽情。","丹陽萬戶春光靜，獨自君家秋雨聲。"]', '["繞屋扶疎聳翠莖，苔滋粉漾有幽情。","丹陽万戶春光静，独自君家秋雨声。"]', '诗', 'shi', '', NULL, '題十三弟竹園 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ddcde7-d0a1-4aff-aed2-e715b4718bd7', '樂府雜詞三首 一', '乐府杂词三首 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["紫禁梨花飛雪毛，春風絲管翠樓高。","城裏萬家聞不見，君王試舞鄭櫻桃。"]', '["紫禁梨花飞雪毛，春风絲管翠楼高。","城裏万家闻不见，君王試舞鄭櫻桃。"]', '诗', 'shi', '', NULL, '樂府雜詞三首 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15fe86ed-edfe-4f94-86fd-8877d8d97182', '樂府雜詞三首 二', '乐府杂词三首 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["蟬鬢紅冠粉黛輕，雲和新教羽衣成。","月光如雪金堦上，迸却頗梨義甲聲。"]', '["蟬鬢紅冠粉黛轻，云和新教羽衣成。","月光如雪金堦上，迸却頗梨義甲声。"]', '诗', 'shi', '', NULL, '樂府雜詞三首 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa7a45a-49ec-41aa-bb3f-ede353c76957', '樂府雜詞三首 三', '乐府杂词三首 三', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["不耐簷前紅槿枝，薄妝春寢覺仍遲。","夢中無限風流事，夫壻多情亦未知。"]', '["不耐簷前紅槿枝，薄妝春寢覺仍遲。","梦中無限风流事，夫壻多情亦未知。"]', '诗', 'shi', '', NULL, '樂府雜詞三首 三 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e9e9f5-c0cb-4da9-9274-f407121aa5b3', '歲暮題楊錄事江亭', '歲暮題楊錄事江亭', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["垂絲蜀客涕濡衣，歲盡長沙未得歸。","腸斷錦帆風日好，可憐桐鳥出花飛。"]', '["垂絲蜀客涕濡衣，歲尽长沙未得归。","腸斷錦帆风日好，可怜桐鸟出花飞。"]', '诗', 'shi', '', NULL, '歲暮題楊錄事江亭 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9fc950a-f38f-4afa-9651-39cfecafba6d', '冬日峽中旅泊', '冬日峽中旅泊', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["霜月明明雪復殘，孤舟夜泊使君灘。","一聲鐘出遠山裏，暗想雪窗僧起寒。"]', '["霜月明明雪复殘，孤舟夜泊使君灘。","一声鐘出远山裏，暗想雪窗僧起寒。"]', '诗', 'shi', '', NULL, '冬日峽中旅泊 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54fdc1da-b71b-465c-b8f8-dc9d91069fec', '泊花石浦', '泊花石浦', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["舊業叢臺廢苑東，幾年爲梗復爲蓬。","杜鵑啼斷回家夢，半在邯鄲驛樹中。"]', '["旧業叢台廢苑东，幾年爲梗复爲蓬。","杜鵑啼斷回家梦，半在邯鄲驛樹中。"]', '诗', 'shi', '', NULL, '泊花石浦 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f674d5-2011-4d86-aa84-f8ec4c1b8315', '聞崔倚旅葬', '闻崔倚旅葬', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["遠客那能返故廬，蒼梧埋骨痛何如。","他時親戚空相憶，席上同悲一紙書。"]', '["远客那能返故廬，蒼梧埋骨痛何如。","他时親戚空相憶，席上同悲一紙书。"]', '诗', 'shi', '', NULL, '聞崔倚旅葬 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d190fd-838a-4d42-a10b-cb5e0e514fbf', '賦蕃子牧馬', '賦蕃子牧马', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["磧淨山高見極邊，孤烽引上一條煙。","蕃落多晴塵擾擾，天軍獵到鸊鵜泉。"]', '["磧淨山高见極邊，孤烽引上一條煙。","蕃落多晴塵擾擾，天軍獵到鸊鵜泉。"]', '诗', 'shi', '', NULL, '賦蕃子牧馬 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41e7ebc7-76c3-4292-8f3d-4c2bb6fa4c6b', '牧馬泉', '牧马泉', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["平沙漫漫馬悠悠，弓箭閑拋郊水頭。","鼠毛衣裏取羌笛，吹向秋天眉眼愁。"]', '["平沙漫漫马悠悠，弓箭闲拋郊水头。","鼠毛衣裏取羌笛，吹向秋天眉眼愁。"]', '诗', 'shi', '', NULL, '牧馬泉 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835d1c01-fd05-4d92-ab55-700116717b60', '越井臺望', '越井台望', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["獨立陽臺望廣州，更添羈客異鄉愁。","晚潮未至早潮落，井邑暫依沙上頭。"]', '["独立陽台望廣州，更添羈客異乡愁。","晚潮未至早潮落，井邑暫依沙上头。"]', '诗', 'shi', '', NULL, '越井臺望 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96827e11-bc6c-4705-b95c-64c46f9f1ea8', '扶病春亭', '扶病春亭', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["強梳稀髮著綸巾，捨杖空行試病身。","花間自欲裴回立，穉子牽衣不許人。"]', '["強梳稀髮著綸巾，捨杖空行試病身。","花间自欲裴回立，穉子牽衣不許人。"]', '诗', 'shi', '', NULL, '扶病春亭 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6dc08a7-68bb-4817-a92f-48c2bc8657a6', '贈童尼', '贈童尼', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["舊時豔質如明玉，今日空心是冷灰。","料得襄王惆悵極，更無雲雨到陽臺。"]', '["旧时豔質如明玉，今日空心是冷灰。","料得襄王惆悵極，更無云雨到陽台。"]', '诗', 'shi', '', NULL, '贈童尼 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c6e7d3c-7de5-4949-959a-65da6d51b651', '讀故友于君集', '读故友于君集', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["大底從頭總是悲，就中偏愴築城詞。","依然想得初成日，寄出秋山與我時。"]', '["大底從头總是悲，就中偏愴築城词。","依然想得初成日，寄出秋山與我时。"]', '诗', 'shi', '', NULL, '讀故友于君集 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('919ced72-3e21-43d5-ad6b-a75172bb2285', '病僧二首 一', '病僧二首 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["竺國鄉程算不回，病中衣錫徧浮埃。","如今漢地諸經本，自過流沙遠背來。"]', '["竺国乡程算不回，病中衣錫徧浮埃。","如今漢地諸經本，自過流沙远背来。"]', '诗', 'shi', '', NULL, '病僧二首 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb58a591-d3a0-4a5e-855d-548921296e29', '病僧二首 二', '病僧二首 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["空林衰病臥多時，白髮從成數寸絲。","西行却過流沙日，枕上寥寥心獨知。"]', '["空林衰病臥多时，白髮從成數寸絲。","西行却過流沙日，枕上寥寥心独知。"]', '诗', 'shi', '', NULL, '病僧二首 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0083f12c-2f19-4008-bf97-41445b57ab40', '右軍墨池', '右軍墨池', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["永嘉人事盡歸空，逸少遺居蔓草中。","至今池水涵餘墨，猶共諸泉色不同。"]', '["永嘉人事尽归空，逸少遺居蔓草中。","至今池水涵餘墨，猶共諸泉色不同。"]', '诗', 'shi', '', NULL, '右軍墨池 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e58831f-7fe8-498b-b296-a686ea422fae', '送僧歸山', '送僧归山', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["楚俗翻花自送迎，密人來往豈知情。","夜行獨自寒山寺，雪徑泠泠金錫聲。"]', '["楚俗翻花自送迎，密人来往豈知情。","夜行独自寒山寺，雪徑泠泠金錫声。"]', '诗', 'shi', '', NULL, '送僧歸山 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d7ed67-a233-49ca-adbb-f984c6cd5279', '題源分竹亭', '題源分竹亭', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["繞屋扶疎千萬竿，年年相誘獨行看。","日光不透煙常在，先校諸家一月寒。"]', '["繞屋扶疎千万竿，年年相誘独行看。","日光不透煙常在，先校諸家一月寒。"]', '诗', 'shi', '', NULL, '題源分竹亭 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc422ff1-f5be-4c3d-8875-10671e9cad85', '山寺看櫻桃花題僧壁', '山寺看櫻桃花題僧壁', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["楚寺春風臘盡時，含桃先坼一千枝。","老僧不語傍邊坐，花發人來總不知。"]', '["楚寺春风臘尽时，含桃先坼一千枝。","老僧不語傍邊坐，花發人来總不知。"]', '诗', 'shi', '', NULL, '山寺看櫻桃花題僧壁 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e48b05-aa39-47f8-a9d8-06c15fd385f1', '傷清江上人', '傷清江上人', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["往年偏共仰師遊，聞過流沙淚不休。","此身豈得多時住，更著塵心起外愁。"]', '["往年偏共仰師游，闻過流沙泪不休。","此身豈得多时住，更著塵心起外愁。"]', '诗', 'shi', '', NULL, '傷清江上人 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e3c058-b9d4-4323-bdf3-fbb36c2d83a4', '山寺看海榴花', '山寺看海榴花', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["琉璃地上紺宮前，發翠凝紅已十年。","夜久月明人去盡，火光霞燄遞相燃。"]', '["琉璃地上紺宮前，發翠凝紅已十年。","夜久月明人去尽，火光霞燄遞相燃。"]', '诗', 'shi', '', NULL, '山寺看海榴花 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4808bf-073b-415d-b59c-4361c1eefa33', '贈成鍊師四首 一', '贈成鍊師四首 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["花冠蘂帔色嬋娟，一曲清簫凌紫煙。","不知今日重來意，更住人間幾百年。"]', '["花冠蘂帔色嬋娟，一曲清簫凌紫煙。","不知今日重来意，更住人间幾百年。"]', '诗', 'shi', '', NULL, '贈成鍊師四首 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d3cd67-a659-4e58-a18c-eb67a1b5d860', '贈成鍊師四首 二', '贈成鍊師四首 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["黃昏騎得下天龍，巡遍茅山數十峰。","採芝却到蓬萊上，花裏猶殘碧玉鍾。"]', '["黄昏騎得下天龙，巡遍茅山數十峰。","採芝却到蓬萊上，花裏猶殘碧玉鍾。"]', '诗', 'shi', '', NULL, '贈成鍊師四首 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2452fe4e-0c6a-46b8-a284-776140de1d81', '贈成鍊師四首 三', '贈成鍊師四首 三', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["等閑何處得靈方，丹臉雲鬟日月長。","大羅過却三千歲，更向人間魅阮郎。"]', '["等闲何处得靈方，丹臉云鬟日月长。","大羅過却三千歲，更向人间魅阮郎。"]', '诗', 'shi', '', NULL, '贈成鍊師四首 三 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98837307-06dd-4453-a57b-92fe56040323', '贈成鍊師四首 四', '贈成鍊師四首 四', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["曾隨阿母漢宮齋，鳳駕龍軿列玉堦。","當時白燕無尋處，今日雲鬟見玉釵。"]', '["曾隨阿母漢宮斋，鳳駕龙軿列玉堦。","當时白燕無尋处，今日云鬟见玉釵。"]', '诗', 'shi', '', NULL, '贈成鍊師四首 四 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029fca99-9c54-464e-b862-f3a7acc7a1be', '上巳日陪襄陽李尚書宴光風亭', '上巳日陪襄陽李尚书宴光风亭', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["碧池萍嫩柳垂波，綺席絲鏞舞翠娥。","爲報會稽亭上客，永和應不勝元和。"]', '["碧池萍嫩柳垂波，綺席絲鏞舞翠娥。","爲報會稽亭上客，永和應不勝元和。"]', '诗', 'shi', '', NULL, '上巳日陪襄陽李尚書宴光風亭 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6e6335-cfa0-4aab-bd0a-4c73bfa807f0', '奉酬', '奉酬', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["閏餘春早景沈沈，禊飲風亭恣賞心。","紅袖青娥留永夕，漢陰寧肯羨山陰。"]', '["閏餘春早景沈沈，禊饮风亭恣賞心。","紅袖青娥留永夕，漢陰寧肯羨山陰。"]', '诗', 'shi', '', NULL, '奉酬 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9298909a-189b-4e81-9e2e-9a2ae10a0735', '病中客散復言懷', '病中客散复言懷', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["華髮離披臥滿頭，暗蟲衰草入鄉愁。","枕前人去空庭暮，又見芭蕉白露秋。"]', '["华髮離披臥满头，暗蟲衰草入乡愁。","枕前人去空庭暮，又见芭蕉白露秋。"]', '诗', 'shi', '', NULL, '病中客散復言懷 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb0ee88-2134-4615-a52c-d5773649d763', '處州月夜穆中丞席和主人', '处州月夜穆中丞席和主人', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["羌竹繁弦銀燭紅，月光初出柳城東。","忽見隱侯裁一詠，還須書向郡樓中。"]', '["羌竹繁弦銀燭紅，月光初出柳城东。","忽见隐侯裁一詠，還須书向郡楼中。"]', '诗', 'shi', '', NULL, '處州月夜穆中丞席和主人 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c2ec940-b448-449e-93b5-486d762fa4d1', '尋花', '尋花', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["遊春未足春將度，訪紫尋紅少在家。","借問流鶯與飛蝶，更知何處有幽花。"]', '["游春未足春將度，訪紫尋紅少在家。","借问流鶯與飞蝶，更知何处有幽花。"]', '诗', 'shi', '', NULL, '尋花 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1932761b-ac2a-4046-9604-240eb2c07e71', '贈陳長史妓', '贈陳长史妓', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["寶鈿雲和玉禁僊，深含媚靨褭朱弦。","春風不怕君王恨，引出幽花落外邊。"]', '["寶鈿云和玉禁僊，深含媚靨褭朱弦。","春风不怕君王恨，引出幽花落外邊。"]', '诗', 'shi', '', NULL, '贈陳長史妓 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6e58e70-d76d-4bcf-adee-3e7506f01256', '題王況故居', '題王況故居', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["入巷蕭條起悲緒，兒女猶居舊貧處。","塵滿空牀屋見天，獨作驢鳴一聲去。"]', '["入巷蕭條起悲緒，兒女猶居旧貧处。","塵满空牀屋见天，独作驢鳴一声去。"]', '诗', 'shi', '', NULL, '題王況故居 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7d9615-4c04-4f5d-8cf5-2b53f2d3e8f5', '偶題', '偶題', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["遲日新妝遊冶娘，盈盈綵艇白蓮塘。","掬水遠濕岸邊郎，紅綃縷中玉釧光。"]', '["遲日新妝游冶娘，盈盈綵艇白蓮塘。","掬水远濕岸邊郎，紅綃縷中玉釧光。"]', '诗', 'shi', '', NULL, '偶題 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86fd8d10-6861-4018-ad11-7e711ea2ef44', '慟柳論', '慟柳論', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["孀妻棲戶仍無嗣，欲訪孤墳誰引至。","裴回無處展哀情，惟有衣襟知下淚。"]', '["孀妻棲戶仍無嗣，欲訪孤墳誰引至。","裴回無处展哀情，惟有衣襟知下泪。"]', '诗', 'shi', '', NULL, '慟柳論 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e071579-37de-4201-95fe-46f35d6552e4', '夜入簡子古城', '夜入簡子古城', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["遠火熒熒聚寒鬼，綠燄欲銷還復起。","夜深風雪古城空，行客衣襟汗如水。"]', '["远火熒熒聚寒鬼，綠燄欲銷還复起。","夜深风雪古城空，行客衣襟汗如水。"]', '诗', 'shi', '', NULL, '夜入簡子古城 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb06249-d0dd-4c5a-8088-a2bb673daaa6', '桂江中題香頂臺', '桂江中題香頂台', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["岧岧香積凌空翠，天上名花落幽地。","老僧相對竟無言，山鳥却呼諸佛字。"]', '["岧岧香積凌空翠，天上名花落幽地。","老僧相对竟無言，山鸟却呼諸佛字。"]', '诗', 'shi', '', NULL, '桂江中題香頂臺 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9c1b74-7e1d-49d0-8545-20d97205601e', '僧簷前獨竹詠', '僧簷前独竹詠', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["亂石田中寄孤本，亭亭不住凌虛引。","欲以袈裟拂著來，一邊碧玉無輕粉。"]', '["亂石田中寄孤本，亭亭不住凌虛引。","欲以袈裟拂著来，一邊碧玉無轻粉。"]', '诗', 'shi', '', NULL, '僧簷前獨竹詠 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('327e2367-7dab-4ab9-96b1-8a357b515b1e', '送人隨姊夫任雲安令', '送人隨姊夫任云安令', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["閑逐維私向武城，北風青雀片時行。","孤帆瞥過荆州岸，認得瞿塘急浪聲。"]', '["闲逐維私向武城，北风青雀片时行。","孤帆瞥過荆州岸，認得瞿塘急浪声。"]', '诗', 'shi', '', NULL, '送人隨姊夫任雲安令 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51d5251-66c3-4cf4-a82c-dea77a717389', '山中喜崔補闕見尋', '山中喜崔補闕见尋', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["鹿袖青藜鼠耳巾，潛夫豈解拜朝臣。","白屋藜牀還共入，山妻老大不羞人。"]', '["鹿袖青藜鼠耳巾，潛夫豈解拜朝臣。","白屋藜牀還共入，山妻老大不羞人。"]', '诗', 'shi', '', NULL, '山中喜崔補闕見尋 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8eb81b-8ff1-4088-8a43-9e3223a6d7a8', '偶題二首 一', '偶題二首 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["金榜榮名俱失盡，病身爲庶更投魑。","春娥慢笑無愁色，別向人家舞柘枝。"]', '["金榜榮名俱失尽，病身爲庶更投魑。","春娥慢笑無愁色，別向人家舞柘枝。"]', '诗', 'shi', '', NULL, '偶題二首 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b2f201-6f6a-4302-968c-75874e20b09e', '偶題二首 二', '偶題二首 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["得罪除名謫海頭，驚心無暇與身愁。","中使不知何處住，家書莫寄向春州。"]', '["得罪除名謫海头，驚心無暇與身愁。","中使不知何处住，家书莫寄向春州。"]', '诗', 'shi', '', NULL, '偶題二首 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cdb17fe-03cc-49ec-8165-88d4fdca1566', '嘉興社日', '嘉兴社日', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["消渴天涯寄病身，臨邛知我是何人。","今年社日分餘肉，不值陳平又不均。"]', '["消渴天涯寄病身，臨邛知我是何人。","今年社日分餘肉，不值陳平又不均。"]', '诗', 'shi', '', NULL, '嘉興社日 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0cf02ab-c5a8-4fc3-a3cb-53e21d4a3679', '席上贈李尹', '席上贈李尹', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["傴僂山夫髮似絲，松間石上坐多時。","瓢飲不曾看酒肆，世人空笑亦何爲。"]', '["傴僂山夫髮似絲，松间石上坐多时。","瓢饮不曾看酒肆，世人空笑亦何爲。"]', '诗', 'shi', '', NULL, '席上贈李尹 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62398c45-64ca-45a1-af5c-f788c479f1f8', '弼公院問病', '弼公院问病', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["一頭細髮兩分絲，臥見芭蕉白露滋。","欲令居士身無病，直待衆生苦盡時。"]', '["一头細髮兩分絲，臥见芭蕉白露滋。","欲令居士身無病，直待衆生苦尽时。"]', '诗', 'shi', '', NULL, '弼公院問病 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba152c85-e889-40b0-812b-2fb34179e18f', '惜花', '惜花', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["年少共憐含露色，老人偏惜委塵紅。","如何遂得心中事，每要花時不厭風。"]', '["年少共怜含露色，老人偏惜委塵紅。","如何遂得心中事，每要花时不厭风。"]', '诗', 'shi', '', NULL, '惜花 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85d5ca9c-bcd9-4cbc-b1dd-265dc92dc649', '代胡僧留別', '代胡僧留別', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["此地緣疎語未通，歸時老病去無窮。","定知不徹南天竺，死在條支陰磧中。"]', '["此地緣疎語未通，归时老病去無窮。","定知不徹南天竺，死在條支陰磧中。"]', '诗', 'shi', '', NULL, '代胡僧留別 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35b581c-9679-4bac-9c39-5c2b0d043910', '桂江逢王使君旅櫬歸', '桂江逢王使君旅櫬归', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["故人丹旐出南威，少婦隨喪哭漸歸。","遙想北原新壠上，日寒光淺水松稀。"]', '["故人丹旐出南威，少婦隨喪哭漸归。","遙想北原新壠上，日寒光淺水松稀。"]', '诗', 'shi', '', NULL, '桂江逢王使君旅櫬歸 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('223fbd22-9e58-4cb8-8185-7d404ae4e3ec', '玉京詞', '玉京词', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["絕景寥寥日更遲，人間甲子不同時。","未知樵客終何得，歸後無家是看棋。"]', '["絕景寥寥日更遲，人间甲子不同时。","未知樵客終何得，归後無家是看棋。"]', '诗', 'shi', '', NULL, '玉京詞 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b862611f-7390-4eae-b8e4-0a31e57d6993', '葛巾歌', '葛巾歌', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["一片白葛巾，潛夫自能結。","籬邊折枯蒿，聊用簪華髮。","有時醉倒長松側，酒醒不見心還憶。","谷鳥銜將却趁來，野風吹去還尋得。","十年紫竹溪南住，跡同玄豹依深霧。","草堂窗底漉春醅，山寺門前逢暮雨。","臨汝袁郎得相見，閑雲引到東陽縣。","魯性將他類此身，還拈野物贈傍人。","空留梲杖犢鼻褌，濛濛煙雨歸山村。"]', '["一片白葛巾，潛夫自能結。","籬邊折枯蒿，聊用簪华髮。","有时醉倒长松側，酒醒不见心還憶。","谷鸟銜將却趁来，野风吹去還尋得。","十年紫竹溪南住，跡同玄豹依深霧。","草堂窗底漉春醅，山寺门前逢暮雨。","臨汝袁郎得相见，闲云引到东陽縣。","魯性將他類此身，還拈野物贈傍人。","空留梲杖犢鼻褌，濛濛煙雨归山村。"]', '诗', 'shi', '', NULL, '葛巾歌 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bbef731-af78-45d6-8fa4-868a1ec97821', '北原情三首 一', '北原情三首 一', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["錯莫天色愁，挽歌出重闉。","誰家白網車，送客入幽塵。","銘旌下官道，葬輿去轔轔。","蕭條黃蒿中，奠酒花翠新。","米雪晚霏微，墓成悄無人。","烏鳶下空地，煙火殘荒榛。","生人更多苦，入戶事盈身。","營營日易深，却到不得頻。","寂寥孤隧頭，草綠棠梨春。"]', '["錯莫天色愁，挽歌出重闉。","誰家白網车，送客入幽塵。","銘旌下官道，葬輿去轔轔。","蕭條黄蒿中，奠酒花翠新。","米雪晚霏微，墓成悄無人。","烏鳶下空地，煙火殘荒榛。","生人更多苦，入戶事盈身。","營營日易深，却到不得頻。","寂寥孤隧头，草綠棠梨春。"]', '诗', 'shi', '', NULL, '北原情三首 一 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bda257f6-9f1d-4194-a076-32d79968eb20', '北原情三首 二', '北原情三首 二', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["洛陽城北山，古今葬冥客。","聚骨朽成泥，此山土多白。","近來送葬人，亦去聞歸聲。","豈能車輪疾，漸是墓侵城。","城中人不絕，哀挽相次行。","莫非北邙後，重向洛城生。"]', '["洛陽城北山，古今葬冥客。","聚骨朽成泥，此山土多白。","近来送葬人，亦去闻归声。","豈能车輪疾，漸是墓侵城。","城中人不絕，哀挽相次行。","莫非北邙後，重向洛城生。"]', '诗', 'shi', '', NULL, '北原情三首 二 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad3e909-fb79-445d-b108-df85d7a28d5f', '北原情三首 三', '北原情三首 三', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["卜地起孤墳，全家送葬去。","歸來却到時，不復重知處。","疊疊葬相續，土乾草已綠。","列紙瀉壺漿，空向春雲哭。"]', '["卜地起孤墳，全家送葬去。","归来却到时，不复重知处。","叠叠葬相續，土乾草已綠。","列紙瀉壺漿，空向春云哭。"]', '诗', 'shi', '', NULL, '北原情三首 三 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d39e8c-a34a-4a4b-b569-6f9a87b44b05', '林中獨醒', '林中独醒', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["晚來林沼靜，獨坐間瓢尊。","向己非前跡，齊心欲不言。","微涼生亂篠，輕馥起孤萱。","未得渾無事，瓜田草正繁。"]', '["晚来林沼静，独坐间瓢尊。","向己非前跡，齊心欲不言。","微涼生亂篠，轻馥起孤萱。","未得渾無事，瓜田草正繁。"]', '诗', 'shi', '', NULL, '林中獨醒 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edfa6d28-d658-49ed-939d-c52c34d5d22d', '江陵客舍留別樊尚書', '江陵客舍留別樊尚书', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["信陵門館下，多病有歸思。","墜履忘情後，寒灰更濕時。","委欄芳蕙晚，憑几雪髫垂。","明日秋關外，單車風雨隨。"]', '["信陵门館下，多病有归思。","墜履忘情後，寒灰更濕时。","委欄芳蕙晚，憑几雪髫垂。","明日秋关外，單车风雨隨。"]', '诗', 'shi', '', NULL, '江陵客舍留別樊尚書 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7f9bd4-42f8-47cc-9ad9-2e410647b389', '擬古詠河邊枯樹', '擬古詠河邊枯樹', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["野火燒枝水洗根，數圍孤樹半心存。","應是無機承雨露，却將春色寄苔痕。"]', '["野火燒枝水洗根，數圍孤樹半心存。","應是無機承雨露，却將春色寄苔痕。"]', '诗', 'shi', '', NULL, '擬古詠河邊枯樹 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('206b89d1-ec09-42c4-97cf-b0b2cff84e29', '別友人', '別友人', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["愁多不忍醒時別，想極還尋靜處行。","誰遣同衾又分手，不如行路本無情。"]', '["愁多不忍醒时別，想極還尋静处行。","誰遣同衾又分手，不如行路本無情。"]', '诗', 'shi', '', NULL, '別友人 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0cfc3de-c236-4904-aca1-f3c8536c5e17', '傷故人歌妓', '傷故人歌妓', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["愁臉無紅衣滿塵，萬家門戶不容身。","曾將一笑君前去，悞殺幾多回顧人。"]', '["愁臉無紅衣满塵，万家门戶不容身。","曾將一笑君前去，悞殺幾多回顧人。"]', '诗', 'shi', '', NULL, '傷故人歌妓 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc27b340-1e98-48f2-b3f6-2a8e67608bc0', '南中客舍對雨送故人歸北', '南中客舍对雨送故人归北', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["猨聲啾啾雁聲苦，卷簾相對愁不語。","幾年客吳君在楚，況送君歸我猶阻。","家書作得不忍封，北風吹斷堦前雨。"]', '["猨声啾啾雁声苦，卷簾相对愁不語。","幾年客吳君在楚，況送君归我猶阻。","家书作得不忍封，北风吹斷堦前雨。"]', '诗', 'shi', '', NULL, '南中客舍對雨送故人歸北 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3355f85a-00ae-422d-b446-f3df558da00c', '杭州秋日別故友', '杭州秋日別故友', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["相見又相別，大江秋水深。","悲歡一世事，去住兩鄉心。","淅瀝籬下葉，淒清階上琴。"]', '["相见又相別，大江秋水深。","悲歡一世事，去住兩乡心。","淅瀝籬下葉，淒清階上琴。"]', '诗', 'shi', '', NULL, '杭州秋日別故友 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c050a0b4-59c6-44fb-b232-5be59cb4d784', '代別後夢別', '代別後梦別', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["別中還夢別，悲後更生悲。","覺夢俱千里，追隨難再期。","翻思夢裏苦，却恨覺來遲。","縱是非真事，何妨夢會時。"]', '["別中還梦別，悲後更生悲。","覺梦俱千里，追隨难再期。","翻思梦裏苦，却恨覺来遲。","縱是非真事，何妨梦會时。"]', '诗', 'shi', '', NULL, '代別後夢別 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aefdb6f-b553-4f13-94cc-cb7a922a9855', '荅邊信', '荅邊信', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["征人去年戍遼水，夜得邊書字盈紙。","揮刀就燭裁紅綺，結作同心荅千里。","君寄邊書書莫絕，妾荅同心心自結。","同心再解心不離，書字頻看字愁滅。","結成一夜和淚封，貯書只在懷袖中。","莫如書字故難久，願學同心長可同。"]', '["征人去年戍遼水，夜得邊书字盈紙。","揮刀就燭裁紅綺，結作同心荅千里。","君寄邊书书莫絕，妾荅同心心自結。","同心再解心不離，书字頻看字愁滅。","結成一夜和泪封，貯书只在懷袖中。","莫如书字故难久，願学同心长可同。"]', '诗', 'shi', '', NULL, '荅邊信 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e2d1361-03c5-444c-ab51-166201d23d35', '對鏡吟', '对镜吟', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["憶昔逢君新納娉，青銅鑄出千年鏡。","意憐光彩固無瑕，義比恩情永相映。","每將鑒面兼鑒心，鑒來不輟情逾深。","君非結心空結帶，結處尚新恩已背。","開簾覽鏡悲難語，對面相看孟門阻。","掩匣徒慙雙鳳飛，懸臺欲效孤鸞舞。","昔日照來人共許，今朝照罷自生疑。","鏡上有塵猶可淬，君恩詎肯無迴時。"]', '["憶昔逢君新納娉，青銅鑄出千年镜。","意怜光彩固無瑕，義比恩情永相映。","每將鑒面兼鑒心，鑒来不輟情逾深。","君非結心空結带，結处尚新恩已背。","开簾覽镜悲难語，对面相看孟门阻。","掩匣徒慙雙鳳飞，懸台欲效孤鸾舞。","昔日照来人共許，今朝照罷自生疑。","镜上有塵猶可淬，君恩詎肯無迴时。"]', '诗', 'shi', '', NULL, '對鏡吟 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfcd7fea-4ff7-456b-bf87-8cbf77ca87e1', '山行書事', '山行书事', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["日落風䬘䬘，驅車行遠郊。","中心有所悲，古墓穿黃茅。","茅中狐兔窠，四面烏鳶巢。","鬼火時獨出，人煙不相交。","行行近破村，一徑欹還坳。","迎霜聽蟋蟀，向月看蠨蛸。","翁喜客來至，客來羞廚庖。","濁醪誇潑蟻，時果仍新苞。","相勸對寒燈，呼兒爇枯梢。","性朴頗近古，其言無斗筲。","憂歡世上幷，歲月途中拋。","誰知問津客，空作楊雄嘲。"]', '["日落风䬘䬘，驱车行远郊。","中心有所悲，古墓穿黄茅。","茅中狐兔窠，四面烏鳶巢。","鬼火时独出，人煙不相交。","行行近破村，一徑欹還坳。","迎霜听蟋蟀，向月看蠨蛸。","翁喜客来至，客来羞廚庖。","濁醪誇潑蟻，时果仍新苞。","相勸对寒灯，呼兒爇枯梢。","性朴頗近古，其言無斗筲。","憂歡世上幷，歲月途中拋。","誰知问津客，空作楊雄嘲。"]', '诗', 'shi', '', NULL, '山行書事 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd0a168-459e-485c-824b-54b29ea51736', '古宮怨', '古宮怨', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["窗前好樹名玫瑰，去年花落今年開。","無情春色尚識返，君心忽斷何時來。","憶昔妝成候僊仗，宮璅玲瓏日新上。","拊心却笑西子嚬，掩鼻誰憂鄭姬謗。","草染文章衣下履，花黏甲乙牀前帳。","三千玉貌休自誇，十二金釵獨相向。","盛衰傾奪欲何如，嬌愛翻悲逐佞諛。","重遠豈能慙沼鵠，棄前方見泣船魚。","看籠不記薰龍腦，詠扇空曾禿鼠鬚。","始喜類蘿新託柏，終傷如薺却甘荼。","院深獨開還獨閉，鸚鵡驚飛苔覆地。","滿箱舊賜前日衣，漬枕新垂夜來淚。","痕多開鏡照還悲，綠髻青蛾尚未衰。","莫道新縑長絕比，猶逢故劒會相追。"]', '["窗前好樹名玫瑰，去年花落今年开。","無情春色尚識返，君心忽斷何时来。","憶昔妝成候僊仗，宮璅玲瓏日新上。","拊心却笑西子嚬，掩鼻誰憂鄭姬謗。","草染文章衣下履，花黏甲乙牀前帳。","三千玉貌休自誇，十二金釵独相向。","盛衰傾奪欲何如，嬌愛翻悲逐佞諛。","重远豈能慙沼鵠，棄前方见泣船鱼。","看籠不記薰龙腦，詠扇空曾禿鼠鬚。","始喜類蘿新託柏，終傷如薺却甘荼。","院深独开還独閉，鸚鵡驚飞苔覆地。","满箱旧賜前日衣，漬枕新垂夜来泪。","痕多开镜照還悲，綠髻青蛾尚未衰。","莫道新縑长絕比，猶逢故劒會相追。"]', '诗', 'shi', '', NULL, '古宮怨 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f933ee2-48fe-4db9-aebe-339daabdeb75', '關山月', '关山月', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["淒淒還切切，戍客多離別。","何處最傷心，關山見秋月。","關月竟如何，由來遠近過。","始經玄菟塞，終繞白狼河。","忽憶秦樓婦，流光應共有。","已得並蛾眉，還知攬纖手。","去歲照同行，比翼復連形。","今宵照獨立，顧影自煢煢。","餘暉漸西落，夜夜看如昨。","借問暎旌旗，何如鑒帷幕。","拂曉朔風悲，蓬驚鴈不飛。","幾時征戍罷，還向月中歸。"]', '["淒淒還切切，戍客多離別。","何处最傷心，关山见秋月。","关月竟如何，由来远近過。","始經玄菟塞，終繞白狼河。","忽憶秦楼婦，流光應共有。","已得並蛾眉，還知攬纖手。","去歲照同行，比翼复連形。","今宵照独立，顧影自煢煢。","餘暉漸西落，夜夜看如昨。","借问暎旌旗，何如鑒帷幕。","拂晓朔风悲，蓬驚鴈不飞。","幾时征戍罷，還向月中归。"]', '诗', 'shi', '', NULL, '關山月 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b51bc4-cf49-48d2-a578-d1305c057455', '隴西行', '隴西行', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["陰雲凝朔氣，隴上正飛雪。","四月草不生，北風勁如切。","朝來羽書急，夜救長城窟。","道隘行不前，相呼抱鞍歇。","人寒指欲墮，馬凍蹄亦裂。","射雁旋充飢，斧冰還止渴。","寧辭解圍鬬，但恐乘疲沒。","早晚邊候空，歸來養羸卒。"]', '["陰云凝朔氣，隴上正飞雪。","四月草不生，北风勁如切。","朝来羽书急，夜救长城窟。","道隘行不前，相呼抱鞍歇。","人寒指欲墮，马凍蹄亦裂。","射雁旋充飢，斧冰還止渴。","寧辞解圍鬬，但恐乘疲沒。","早晚邊候空，归来養羸卒。"]', '诗', 'shi', '', NULL, '隴西行 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e8f6d2d-015f-49f6-9756-3131b2d5e793', '尋山家', '尋山家', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["獨訪山家歇還涉，茅屋斜連隔松葉。","主人聞語未開門，繞籬野菜飛黃蝶。"]', '["独訪山家歇還涉，茅屋斜連隔松葉。","主人闻語未开门，繞籬野菜飞黄蝶。"]', '诗', 'shi', '', NULL, '尋山家 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e56e93-9ca5-442b-9aa1-42f401bc7589', '山居', '山居', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["看書愛幽寂，結宇青冥間。","飛泉引風聽，古桂和雲攀。","地深草木稠，境靜魚鳥閑。","陰氣晚出谷，朝光先照山。","有時獨杖藜，入夜猶啓關。","星昏歸鳥過，火出樵童還。","神體自和適，不是離人寰。"]', '["看书愛幽寂，結宇青冥间。","飞泉引风听，古桂和云攀。","地深草木稠，境静鱼鸟闲。","陰氣晚出谷，朝光先照山。","有时独杖藜，入夜猶啓关。","星昏归鸟過，火出樵童還。","神體自和適，不是離人寰。"]', '诗', 'shi', '', NULL, '山居 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d2ccb80-ac5b-4193-a65e-b5980715b2f7', '楚州鹽𡏖古牆望海', '楚州鹽𡏖古牆望海', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["混沌本冥冥，泄爲洪川流。","雄哉大造化，萬古橫中州。","我從西北來，登高望蓬丘。","陰晴乍開合，天地相沈浮。","長風卷繁雲，日出扶桑頭。","水淨露鮫室，煙銷凝蜃樓。","時來會雲翔，道蹇即津遊。","明發促歸軫，滄波非宿謀。"]', '["混沌本冥冥，泄爲洪川流。","雄哉大造化，万古橫中州。","我從西北来，登高望蓬丘。","陰晴乍开合，天地相沈浮。","长风卷繁云，日出扶桑头。","水淨露鮫室，煙銷凝蜃楼。","时来會云翔，道蹇即津游。","明發促归軫，滄波非宿謀。"]', '诗', 'shi', '', NULL, '楚州鹽𡏖古牆望海 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198447a8-8c14-4edb-b1ce-0adf48bfad63', '聞韋駙馬使君遷拜台州', '闻韋駙马使君遷拜台州', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["溟藩軫帝憂，見說初鳴騶。","德勝禍先戢，情閑思自流。","蠶殷桑柘空，廩實雀鼠稠。","諫虎昔賜駿，安人將問牛。","曾陪後乘光，共逐平津遊。","旌斾擁追賞，歌鐘催獻酬。","音徽一寂寥，貴賤雙沈浮。","北郭乏中崖，東方稱上頭。","躋山望百城，目盡增遐愁。","海逼日月近，天高星漢秋。","無階異漸鴻，有志慙馴鷗。","終期促孤櫂，暫訪天台幽。"]', '["溟藩軫帝憂，见说初鳴騶。","德勝禍先戢，情闲思自流。","蠶殷桑柘空，廩實雀鼠稠。","諫虎昔賜駿，安人將问牛。","曾陪後乘光，共逐平津游。","旌斾擁追賞，歌鐘催獻酬。","音徽一寂寥，貴賤雙沈浮。","北郭乏中崖，东方稱上头。","躋山望百城，目尽增遐愁。","海逼日月近，天高星漢秋。","無階異漸鴻，有志慙馴鷗。","終期促孤櫂，暫訪天台幽。"]', '诗', 'shi', '', NULL, '聞韋駙馬使君遷拜台州 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe5e136-876f-4a59-b9c8-07030731961e', '山行經村徑', '山行經村徑', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["一徑有人迹，到來唯數家。","依稀聽機杼，寂歷看桑麻。","雨濕渡頭草，風吹墳上花。","却驅羸馬去，數點歸林鴉。"]', '["一徑有人迹，到来唯數家。","依稀听機杼，寂歷看桑麻。","雨濕渡头草，风吹墳上花。","却驱羸马去，數点归林鴉。"]', '诗', 'shi', '', NULL, '山行經村徑 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ccf7c9c-b897-4c42-b550-8faa35864d71', '野田行', '野田行', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["風昏晝色飛斜雨，冤骨千堆髑髏語。","八紘牢落人物悲，是箇田園荒廢主。","悲嗟自古爭天下，幾度乾坤復如此。","秦皇矻矻築長城，漢祖區區白蛇死。","野田之骨兮又成塵，樓閣風煙兮還復新。","願得華山之下長歸馬，野田無復堆冤者。"]', '["风昏晝色飞斜雨，冤骨千堆髑髏語。","八紘牢落人物悲，是箇田园荒廢主。","悲嗟自古爭天下，幾度乾坤复如此。","秦皇矻矻築长城，漢祖區區白蛇死。","野田之骨兮又成塵，楼閣风煙兮還复新。","願得华山之下长归马，野田無复堆冤者。"]', '诗', 'shi', '', NULL, '野田行 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc46bde3-b694-4690-a1bf-cbcdbd3e0829', '貧女', '貧女', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["豈是昧容華，豈不知機織。","自是生寒門，良媒不相識。"]', '["豈是昧容华，豈不知機织。","自是生寒门，良媒不相識。"]', '诗', 'shi', '', NULL, '貧女 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74002940-307e-4d52-940e-0aeadf86e0c1', '幽思', '幽思', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["金爐煙靄微，錦釭殘影滅。","出戶獨裴回，落花滿明月。"]', '["金爐煙靄微，錦釭殘影滅。","出戶独裴回，落花满明月。"]', '诗', 'shi', '', NULL, '幽思 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b087bb0-7346-405f-888d-4e926134f9a6', '惜花三首 一', '惜花三首 一', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["千枝萬枝占春開，彤霞著地紅成堆。","一窖閑愁驅不去，殷勤對爾酌金杯。"]', '["千枝万枝占春开，彤霞著地紅成堆。","一窖闲愁驱不去，殷勤对爾酌金杯。"]', '诗', 'shi', '', NULL, '惜花三首 一 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aae1a96c-39e5-4b58-be2e-232eff1e671f', '惜花三首 二', '惜花三首 二', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["老鴉拍翼盤空疾，准擬浮生如瞬息。","阿母蟠桃香未齊，漢皇骨葬秋山碧。"]', '["老鴉拍翼盤空疾，准擬浮生如瞬息。","阿母蟠桃香未齊，漢皇骨葬秋山碧。"]', '诗', 'shi', '', NULL, '惜花三首 二 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8fc048b-6b07-408d-a125-634818bc95ee', '惜花三首 三', '惜花三首 三', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["朝開暮落煎人老，無人爲報東君道。","留取穠紅伴醉吟，莫教少女來吹掃。"]', '["朝开暮落煎人老，無人爲報东君道。","留取穠紅伴醉吟，莫教少女来吹掃。"]', '诗', 'shi', '', NULL, '惜花三首 三 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e18fb650-be22-4f0e-925b-e8e0252c1d85', '遊春引三首 一', '游春引三首 一', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["句芒愛弄春風權，開萌發翠無黨偏。","句芒小女精神巧，機羅杼綺滿平川。"]', '["句芒愛弄春风權，开萌發翠無黨偏。","句芒小女精神巧，機羅杼綺满平川。"]', '诗', 'shi', '', NULL, '遊春引三首 一 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b006226-237f-4f13-b01f-5f8cee04c2bb', '遊春引三首 二', '游春引三首 二', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["五陵年少輕薄客，蠻錦花多春袖窄。","酌桂鳴金翫物華，星蹄繡轂填香陌。"]', '["五陵年少轻薄客，蠻錦花多春袖窄。","酌桂鳴金翫物华，星蹄繡轂填香陌。"]', '诗', 'shi', '', NULL, '遊春引三首 二 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11ed140-dae9-4923-828a-1379113fd0e1', '遊春引三首 三', '游春引三首 三', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["千條碧綠輕拖水，金毛泣怕春江死。","萬彙俱含造化恩，見我春工無私理。"]', '["千條碧綠轻拖水，金毛泣怕春江死。","万彙俱含造化恩，见我春工無私理。"]', '诗', 'shi', '', NULL, '遊春引三首 三 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c8565cc-bd2e-4b5a-87e3-00119062da17', '農父', '農父', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["運鋤耕斸侵星起，隴畝豐盈滿家喜。","到頭禾黍屬他人，不知何處抛妻子。"]', '["運鋤耕斸侵星起，隴畝豐盈满家喜。","到头禾黍屬他人，不知何处抛妻子。"]', '诗', 'shi', '', NULL, '農父 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec20615e-d3da-4109-b0f3-f754488e7b42', '古意', '古意', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["鑾輿不碾香塵滅，更殘三十六宮月。","手持紈扇獨含情，秋風吹落橫波血。"]', '["鑾輿不碾香塵滅，更殘三十六宮月。","手持紈扇独含情，秋风吹落橫波血。"]', '诗', 'shi', '', NULL, '古意 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efad3f8b-87d3-406e-a916-fc8fb2bdf381', '秋日登岳陽樓晴望', '秋日登岳陽楼晴望', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["三秋倚練飛金盞，洞庭波定平如剗。","天高雲卷綠羅低，一點君山礙人眼。","漫漫萬頃鋪琉璃，煙波闊遠無鳥飛。","西南東北競無際，直疑侵斷青天涯。","屈原回日牽愁吟，龍宮感激致應沈。","賈生憔悴說不得，茫茫煙靄堆湖心。"]', '["三秋倚練飞金盞，洞庭波定平如剗。","天高云卷綠羅低，一点君山礙人眼。","漫漫万頃鋪琉璃，煙波闊远無鸟飞。","西南东北競無際，直疑侵斷青天涯。","屈原回日牽愁吟，龙宮感激致應沈。","賈生憔悴说不得，茫茫煙靄堆湖心。"]', '诗', 'shi', '', NULL, '秋日登岳陽樓晴望 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb869dca-e445-493b-a97b-1031cdb5f49b', '鴻溝', '鴻溝', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["毒龍銜日天地昏，八紘靉靆生愁雲。","秦園走鹿無藏處，紛紛爭處蜂成羣。","四溟波立鯨相吞，蕩搖五岳崩山根。","魚蝦舞浪狂鰍鯤，龍蛇膽戰登鴻門。","星旗羽鏃強者尊，黑風白雨東西屯。","山河欲拆人煙分，壯士鼓勇君王存。","項莊憤氣吐不得，亞父斗聲天上聞。","玉光墮地驚崑崙，留侯氣魄吞太華。","舌頭一寸生陽春，神農女媧愁不言。","蛇枯老媼啼淚痕，星曹定秤秤王孫。","項籍骨輕迷精魂，沛公仰面爭乾坤。","須臾垓下賊星起，歌聲繚繞悽人耳。","吳娃捧酒橫秋波，霜天月照空城壘。","力拔山兮忽到此，騅嘶懶渡烏江水。","新豐瑞色生樓臺，西楚寒蒿哭愁鬼。","三尺霜鳴金匣裏，神光一掉八千里。","漢皇驟馬意氣生，西南掃地迎天子。"]', '["毒龙銜日天地昏，八紘靉靆生愁云。","秦园走鹿無藏处，紛紛爭处蜂成羣。","四溟波立鯨相吞，蕩搖五岳崩山根。","鱼蝦舞浪狂鰍鯤，龙蛇膽戰登鴻门。","星旗羽鏃強者尊，黑风白雨东西屯。","山河欲拆人煙分，壯士鼓勇君王存。","項莊憤氣吐不得，亞父斗声天上闻。","玉光墮地驚崑崙，留侯氣魄吞太华。","舌头一寸生陽春，神農女媧愁不言。","蛇枯老媼啼泪痕，星曹定秤秤王孫。","項籍骨轻迷精魂，沛公仰面爭乾坤。","須臾垓下賊星起，歌声繚繞悽人耳。","吳娃捧酒橫秋波，霜天月照空城壘。","力拔山兮忽到此，騅嘶懶渡烏江水。","新豐瑞色生楼台，西楚寒蒿哭愁鬼。","三尺霜鳴金匣裏，神光一掉八千里。","漢皇驟马意氣生，西南掃地迎天子。"]', '诗', 'shi', '', NULL, '鴻溝 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e66e7b43-a267-43d2-a201-49c17bcddcf9', '美人梳頭', '美人梳头', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["玉堂花院小枝紅，綠窗一片春光曉。","玉容驚覺濃睡醒，圓蟾挂出妝臺表。","金盤解下叢鬟碎，三尺巫雲綰朝翠。","皓指高低寸黛愁，水精梳滑參差墜。","須臾攏掠蟬鬢生，玉釵冷透冬冰明。","芙蓉拆向新開臉，秋泉慢轉眸波橫。","鸚鵡偷來話心曲，屏風半倚遙山綠。"]', '["玉堂花院小枝紅，綠窗一片春光晓。","玉容驚覺濃睡醒，圓蟾挂出妝台表。","金盤解下叢鬟碎，三尺巫云綰朝翠。","皓指高低寸黛愁，水精梳滑參差墜。","須臾攏掠蟬鬢生，玉釵冷透冬冰明。","芙蓉拆向新开臉，秋泉慢轉眸波橫。","鸚鵡偷来話心曲，屏风半倚遙山綠。"]', '诗', 'shi', '', NULL, '美人梳頭 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff7a464-23c9-406b-b0ee-8c59bc0f3183', '題祖山人池上怪石', '題祖山人池上怪石', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["寒姿數片奇突兀，曾作秋江秋水骨。","先生應是厭風雲，著向江邊塞龍窟。","我來池上傾酒尊，半酣書破青煙痕。","參差翠縷擺不落，筆頭驚怪黏秋雲。","我聞吳中項容水墨有高價，邀得將來倚松下。","鋪却雙繒直道難，掉首空歸不成畫。"]', '["寒姿數片奇突兀，曾作秋江秋水骨。","先生應是厭风云，著向江邊塞龙窟。","我来池上傾酒尊，半酣书破青煙痕。","參差翠縷擺不落，笔头驚怪黏秋云。","我闻吳中項容水墨有高價，邀得將来倚松下。","鋪却雙繒直道难，掉首空归不成畫。"]', '诗', 'shi', '', NULL, '題祖山人池上怪石 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd50445d-5cb4-40c4-b2b4-c24f1b205aa2', '山居雨霽即事', '山居雨霽即事', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["結茅蒼嶺下，自與喧卑隔。","況值雷雨晴，郊原轉岑寂。","出門看反照，繞屋殘溜滴。","古路絕人行，荒陂響螻蟈。","籬崩瓜豆蔓，圃壞牛羊跡。","斷續古祠鴉，高低遠村笛。","喜聞東臯潤，欲往未通屐。","杖策試危橋，攀蘿瞰苔壁。","鄰翁夜相訪，緩酌聊跂石。","新月出汙尊，浮雲在巾舃。","常隳腐儒操，謬習經邦畫。","有待時未知，非關慕沮溺。"]', '["結茅蒼嶺下，自與喧卑隔。","況值雷雨晴，郊原轉岑寂。","出门看反照，繞屋殘溜滴。","古路絕人行，荒陂响螻蟈。","籬崩瓜豆蔓，圃壞牛羊跡。","斷續古祠鴉，高低远村笛。","喜闻东臯潤，欲往未通屐。","杖策試危橋，攀蘿瞰苔壁。","鄰翁夜相訪，緩酌聊跂石。","新月出汙尊，浮云在巾舃。","常隳腐儒操，謬習經邦畫。","有待时未知，非关慕沮溺。"]', '诗', 'shi', '', NULL, '山居雨霽即事 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b580a2e7-ef9a-4853-b003-445e9f52a792', '贈琴棋僧歌', '贈琴棋僧歌', '7368ea37-37f4-49f2-bf59-4b2d1eef89bb', '唐', '["我嘗聽師法一說，波上蓮花水中月。","不垢不淨是色空，無法無空亦無滅。","我嘗聽師禪一觀，浪溢鰲頭蟾魄滿。","河沙世界盡空空，一寸寒灰冷燈畔。","我又聽師琴一撫，長松喚住秋山雨。","弦中雅弄若鏗金，指下寒泉流太古。","我又聽師棋一著，山頂坐沈紅日腳。","阿誰稱是國手人，羅浮道士賭却鶴。","輸却藥，法懷斟下紅霞丹，束手不敢爭頭角。"]', '["我嘗听師法一说，波上蓮花水中月。","不垢不淨是色空，無法無空亦無滅。","我嘗听師禪一观，浪溢鰲头蟾魄满。","河沙世界尽空空，一寸寒灰冷灯畔。","我又听師琴一撫，长松喚住秋山雨。","弦中雅弄若鏗金，指下寒泉流太古。","我又听師棋一著，山頂坐沈紅日腳。","阿誰稱是国手人，羅浮道士賭却鹤。","輸却藥，法懷斟下紅霞丹，束手不敢爭头角。"]', '诗', 'shi', '', NULL, '贈琴棋僧歌 張瀛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda12646-31b5-4d99-ad4d-e046a6d265cc', '妾換馬', '妾換马', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["伴鳳樓中妾，如龍櫪上宛。","同年辭舊寵，異地受新恩。","香閣更衣處，塵蒙噴草痕。","連嘶將忍淚，俱戀主人門。"]', '["伴鳳楼中妾，如龙櫪上宛。","同年辞旧寵，異地受新恩。","香閣更衣处，塵蒙噴草痕。","連嘶將忍泪，俱戀主人门。"]', '诗', 'shi', '', NULL, '妾換馬 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f4e80c2-593c-4273-aff7-4fe977f6dcf4', '七夕', '七夕', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["河耿月涼時，牽牛織女期。","歡娛方在此，漏刻竟由誰。","定不嫌秋駛，唯當乞夜遲。","全勝客子媍，十載泣生離。"]', '["河耿月涼时，牽牛织女期。","歡娛方在此，漏刻竟由誰。","定不嫌秋駛，唯當乞夜遲。","全勝客子媍，十載泣生離。"]', '诗', 'shi', '', NULL, '七夕 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8d206c-0bb0-4e9f-acb9-a7a447fc6c31', '月夜', '月夜', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["露下涼生簟，無人月滿庭。","難聞逆河浪，徒望白榆星。","樹遶孤棲鵲，窗飛就暗螢。","移時宿蘭影，思共習芳馨。"]', '["露下涼生簟，無人月满庭。","难闻逆河浪，徒望白榆星。","樹遶孤棲鵲，窗飞就暗螢。","移时宿蘭影，思共習芳馨。"]', '诗', 'shi', '', NULL, '月夜 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55a8cfb-2b3e-4948-85ec-d6473d853a63', '仲夏寄江南', '仲夏寄江南', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["五月行將近，三年客未迴。","夢成千里去，酒醒百憂來。","晚暮時看槿，悲酸不食梅。","空將白團扇，從寄復裴回。"]', '["五月行將近，三年客未迴。","梦成千里去，酒醒百憂来。","晚暮时看槿，悲酸不食梅。","空將白團扇，從寄复裴回。"]', '诗', 'shi', '', NULL, '仲夏寄江南 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c345b92f-9b61-4434-b082-6f2a9449108e', '欲銷雲', '欲銷云', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["欲隱從龍質，仍餘觸石文。","霏微依碧落，髣髴悞非雲。","度月光無隔，傾河影不分。","如逢作霖處，當爲起氤氳。"]', '["欲隐從龙質，仍餘觸石文。","霏微依碧落，髣髴悞非云。","度月光無隔，傾河影不分。","如逢作霖处，當爲起氤氳。"]', '诗', 'shi', '', NULL, '欲銷雲 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7f2085-67ca-4b38-b9ec-7153f430559d', '遇邊使', '遇邊使', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["累年無的信，每夜夢邊城。","袖掩千行淚，書封一尺情。"]', '["累年無的信，每夜梦邊城。","袖掩千行泪，书封一尺情。"]', '诗', 'shi', '', NULL, '遇邊使 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c7dd89-9d35-4399-9859-8ec8e1d34aef', '移住別居', '移住別居', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["自到西川住，唯君別有情。","常逢對門遠，又隔一重城。"]', '["自到西川住，唯君別有情。","常逢对门远，又隔一重城。"]', '诗', 'shi', '', NULL, '移住別居 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('692fe24d-082f-4305-a4de-adfee955322b', '堋口逢友人', '堋口逢友人', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["艱難別離久，中外往還深。","已改當時法，空餘舊日心。"]', '["艱难別離久，中外往還深。","已改當时法，空餘旧日心。"]', '诗', 'shi', '', NULL, '堋口逢友人 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cca0a6d-cc6b-4465-846b-5e3b4ff39470', '雨霽登北岸寄友人', '雨霽登北岸寄友人', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["稻黃撲撲黍油油，野樹連山澗自流。","憶得年時馮翊部，謝郎相引上樓頭。"]', '["稻黄撲撲黍油油，野樹連山澗自流。","憶得年时馮翊部，謝郎相引上楼头。"]', '诗', 'shi', '', NULL, '雨霽登北岸寄友人 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b6f371-3af0-4ee9-aaab-8c42e1bc9f9b', '長安親故', '长安親故', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["楚蘭不佩佩吳鉤，帶酒城頭別舊遊。","年事已多筋力在，試將弓箭到幷州。"]', '["楚蘭不佩佩吳鉤，带酒城头別旧游。","年事已多筋力在，試將弓箭到幷州。"]', '诗', 'shi', '', NULL, '長安親故 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b57f5d4c-ed74-4a50-b93b-8bda505ca726', '悲秋', '悲秋', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["秋空雁度青天遠，疎樹蟬嘶白露寒。","階下敗蘭猶有氣，手中團扇漸無端。"]', '["秋空雁度青天远，疎樹蟬嘶白露寒。","階下敗蘭猶有氣，手中團扇漸無端。"]', '诗', 'shi', '', NULL, '悲秋 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e24eb7-cdb4-4e50-823a-e1dd7e00423a', '晚蟬', '晚蟬', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["深藏高柳背斜暉，能軫孤愁減昔圍。","猶畏旅人頭不白，再三移樹帶聲飛。"]', '["深藏高柳背斜暉，能軫孤愁減昔圍。","猶畏旅人头不白，再三移樹带声飞。"]', '诗', 'shi', '', NULL, '晚蟬 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b73970-1dbf-43e8-9162-4c503882e241', '維揚郡西亭贈友人', '維揚郡西亭贈友人', 'a5076ed1-98cc-4fb4-b669-e046fe554cf3', '唐', '["萍颯風池香滿船，楊花漠漠暮春天。","玉人此日心中事，何似乘羊入市年。"]', '["萍颯风池香满船，楊花漠漠暮春天。","玉人此日心中事，何似乘羊入市年。"]', '诗', 'shi', '', NULL, '維揚郡西亭贈友人 盧殷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec5c013d-fda1-4825-bba0-90b06cfcfd7b', '終南精舍月中聞磬', '終南精舍月中闻磬', '26f0fdd8-19d2-4e8a-a569-89d4aa5a9694', '唐', '["精廬殘夜景，天宇滅埃氛。","幽磬此時擊，餘音幾處聞。","隨風樹杪去，支策月中分。","斷絕如殘漏，淒清不隔雲。","羇人方罷夢，獨鴈忽迷羣。","響盡河漢落，千山空糾紛。"]', '["精廬殘夜景，天宇滅埃氛。","幽磬此时擊，餘音幾处闻。","隨风樹杪去，支策月中分。","斷絕如殘漏，淒清不隔云。","羇人方罷梦，独鴈忽迷羣。","响尽河漢落，千山空糾紛。"]', '诗', 'shi', '', NULL, '終南精舍月中聞磬 獨孤申叔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46bf764a-2ccb-479c-991b-e83fc8966b16', '題漢州西湖', '題漢州西湖', '5bee647f-2fe6-44fa-b9bf-553cc14d5867', '唐', '["西湖創置自房公，心匠縱橫造化同。","見說鳳池推獨步，高名何事滯川中。"]', '["西湖創置自房公，心匠縱橫造化同。","见说鳳池推独步，高名何事滯川中。"]', '诗', 'shi', '', NULL, '題漢州西湖 嚴公弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('632dc421-6fac-46f6-9e92-590d5adfb994', '題漢州西湖', '題漢州西湖', '2c3503be-a89c-4fe0-b6fd-0f19e7ad76f0', '唐', '["鳳沼才難盡，餘思鑿西湖。","珍木羅修岸，冰光映坐隅。","琴臺今寂寞，竹島尚縈紆。","猶蘊濟川志，芳名終不渝。"]', '["鳳沼才难尽，餘思鑿西湖。","珍木羅修岸，冰光映坐隅。","琴台今寂寞，竹島尚縈紆。","猶蘊濟川志，芳名終不渝。"]', '诗', 'shi', '', NULL, '題漢州西湖 嚴公貺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb64625-be19-4118-bc44-bafaf721b140', '湘弦曲', '湘弦曲', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["楚雲錚錚戛秋露，巫雲峽雨飛朝暮。","古磬高敲百尺樓，孤猨夜哭千丈樹。","雲軒碾火聲瓏瓏，連山卷盡長江空。","鶯啼寂寞花枝雨，鬼嘯荒郊松柏風。","滿堂怨咽悲相續，苦調中含古離曲。","繁弦響絕楚魂遙，湘江水碧湘山綠。"]', '["楚云錚錚戛秋露，巫云峽雨飞朝暮。","古磬高敲百尺楼，孤猨夜哭千丈樹。","云軒碾火声瓏瓏，連山卷尽长江空。","鶯啼寂寞花枝雨，鬼嘯荒郊松柏风。","满堂怨咽悲相續，苦調中含古離曲。","繁弦响絕楚魂遙，湘江水碧湘山綠。"]', '诗', 'shi', '', NULL, '湘弦曲 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a307890-59f1-4f39-a01d-75d5fca72b77', '黃雀行', '黄雀行', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["穿屋穿牆不知止，爭樹爭巢入營死。","林間公子夾彈弓，一丸致斃花叢裏。","小口黃雛未有知，青天不解高高飛。","虞人設網當要路，白日啾嘲禍萬機。"]', '["穿屋穿牆不知止，爭樹爭巢入營死。","林间公子夾彈弓，一丸致斃花叢裏。","小口黄雛未有知，青天不解高高飞。","虞人設網當要路，白日啾嘲禍万機。"]', '诗', 'shi', '', NULL, '黃雀行 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('764d0ce9-8a0c-4770-b26e-0edc9a54a6b9', '雁門太守行', '雁门太守行', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["旌旗閃閃搖天末，長笛橫吹虜塵闊。","跨下嘶風白練獰，腰間切玉青蛇活。","擊革摐金燧牛尾，犬羊兵敗如山死。","九泉寂寞葬秋蟲，濕雲荒草啼秋思。"]', '["旌旗閃閃搖天末，长笛橫吹虜塵闊。","跨下嘶风白練獰，腰间切玉青蛇活。","擊革摐金燧牛尾，犬羊兵敗如山死。","九泉寂寞葬秋蟲，濕云荒草啼秋思。"]', '诗', 'shi', '', NULL, '雁門太守行 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('541a9825-1c3c-4d42-a5d7-f1e11b3fac7a', '陽春曲', '陽春曲', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["紫錦紅囊香滿風，金鸞玉軾搖丁冬。","沙鷗白羽翦晴碧，野桃紅豔燒春空。","芳草緜延鏁平地，壠蝶雙雙舞幽翠。","鳳葉龍吟白日長，落花聲底仙娥醉。"]', '["紫錦紅囊香满风，金鸾玉軾搖丁冬。","沙鷗白羽翦晴碧，野桃紅豔燒春空。","芳草緜延鏁平地，壠蝶雙雙舞幽翠。","鳳葉龙吟白日长，落花声底仙娥醉。"]', '诗', 'shi', '', NULL, '陽春曲 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c0cb93-023b-49e7-8227-055140ea43b9', '傷歌行', '傷歌行', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["兔走烏飛不相見，人事依稀速如電。","王母夭桃一度開，玉樓紅粉千回變。","車馳馬走咸陽道，石家舊宅空荒草。","秋雨無情不惜花，芙蓉一一驚香倒。","勸君莫謾栽荆棘，秦皇虛費驅山力。","英風一去更無言，白骨沈埋暮山碧。"]', '["兔走烏飞不相见，人事依稀速如電。","王母夭桃一度开，玉楼紅粉千回变。","车驰马走咸陽道，石家旧宅空荒草。","秋雨無情不惜花，芙蓉一一驚香倒。","勸君莫謾栽荆棘，秦皇虛費驱山力。","英风一去更無言，白骨沈埋暮山碧。"]', '诗', 'shi', '', NULL, '傷歌行 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c808a5d-d8c5-4280-bb32-9efd90c3f831', '無題', '無題', '762549c3-767a-42f0-baac-d289fb53aa45', '唐', '["喬木挂斗邑，水驛壞門開。","向月片帆去，背雲行雁來。","晚年名利跡，寧免路岐哀。","前計不能息，若爲玄鬢迴。"]', '["喬木挂斗邑，水驛壞门开。","向月片帆去，背云行雁来。","晚年名利跡，寧免路岐哀。","前計不能息，若爲玄鬢迴。"]', '诗', 'shi', '', NULL, '無題 李溟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be8bb2b-1e40-4e51-8632-98e33d27f5e5', '客舍喜友人相訪', '客舍喜友人相訪', '60e1819c-71a9-4afa-a62b-30d2cee4e52d', '唐', '["荒居無四隣，誰肯訪來頻。","古樹秋中葉，他鄉病裏身。","鴈聲風送急，螢影月流新。","獨爲成名晚，多慙見友人。"]', '["荒居無四隣，誰肯訪来頻。","古樹秋中葉，他乡病裏身。","鴈声风送急，螢影月流新。","独爲成名晚，多慙见友人。"]', '诗', 'shi', '', NULL, '客舍喜友人相訪 賀蘭朋吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff4f244-0714-4046-8b5f-069cf67d1b5a', '詣李侍郎', '詣李侍郎', '54b66031-94fa-497a-9e0d-963d5a8c410e', '唐', '["文字元無底，功夫轉到難。","苦心三百首，暫請侍郎看。"]', '["文字元無底，功夫轉到难。","苦心三百首，暫請侍郎看。"]', '诗', 'shi', '', NULL, '詣李侍郎 王魯復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd157d95-20f8-4e64-b2df-bda96308e128', '弔靈均', '弔靈均', '54b66031-94fa-497a-9e0d-963d5a8c410e', '唐', '["萬古汨羅深，騷人道不沈。","明明唐日月，應見楚臣心。"]', '["万古汨羅深，騷人道不沈。","明明唐日月，應见楚臣心。"]', '诗', 'shi', '', NULL, '弔靈均 王魯復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0375e10-11a5-4d5d-9644-98de60f215f6', '弔韓侍郎', '弔韓侍郎', '54b66031-94fa-497a-9e0d-963d5a8c410e', '唐', '["星落少微宮，高人入古風。","幾年才子淚，併寫五言中。"]', '["星落少微宮，高人入古风。","幾年才子泪，併寫五言中。"]', '诗', 'shi', '', NULL, '弔韓侍郎 王魯復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd3fd1e-2b3c-4f55-af83-8af3b2b0e662', '故白巖禪師院', '故白巖禪師院', '54b66031-94fa-497a-9e0d-963d5a8c410e', '唐', '["能師還世名還在，空閉禪堂滿院苔。","花樹不隨人寂寞，數枝猶自出牆來。"]', '["能師還世名還在，空閉禪堂满院苔。","花樹不隨人寂寞，數枝猶自出牆来。"]', '诗', 'shi', '', NULL, '故白巖禪師院 王魯復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658a51ea-a071-4fdb-b6f2-1d356b199e44', '招玉川子詠新文', '招玉川子詠新文', '0e6be6a4-6ad9-49ce-b011-17e4ba926bba', '唐', '["清氣宿我心，結爲清泠音。","一夜吟不足，君來相和吟。"]', '["清氣宿我心，結爲清泠音。","一夜吟不足，君来相和吟。"]', '诗', 'shi', '', NULL, '招玉川子詠新文 徐希仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d27677-f275-4f9b-9eb8-d717fb1fc98c', '五雜組', '五杂組', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["五雜組，刺繡窠。","往復還，織錦梭。","不得已，戍交河。"]', '["五杂組，刺繡窠。","往复還，织錦梭。","不得已，戍交河。"]', '诗', 'shi', '', NULL, '五雜組 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0e0450-dc67-42b1-b59d-718213cee4b4', '剪綵花', '剪綵花', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["敢競桃李色，自呈刀尺功。","蝶猶迷剪翠，人豈辨裁紅。"]', '["敢競桃李色，自呈刀尺功。","蝶猶迷剪翠，人豈辨裁紅。"]', '诗', 'shi', '', NULL, '剪綵花 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe7c75d-41bb-461c-984c-bbcbd4756045', '春晦送客', '春晦送客', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["野酌亂無巡，送君兼送春。","明年春色至，莫作未歸人。"]', '["野酌亂無巡，送君兼送春。","明年春色至，莫作未归人。"]', '诗', 'shi', '', NULL, '春晦送客 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec20bca9-81ab-429f-b0e2-07c8f349d735', '自君之出矣', '自君之出矣', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["自君之出矣，寶鏡爲誰明。","思君如隴水，長聞嗚咽聲。"]', '["自君之出矣，寶镜爲誰明。","思君如隴水，长闻嗚咽声。"]', '诗', 'shi', '', NULL, '自君之出矣 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c473b868-563b-4842-912e-5330ba6118ee', '自君之出矣', '自君之出矣', '23a99c89-7fb7-4606-9a77-630c7e15276e', '唐', '["自君之出矣，明鏡暗不治。","思君如流水，無有窮已時。"]', '["自君之出矣，明镜暗不治。","思君如流水，無有窮已时。"]', '诗', 'shi', '', NULL, '自君之出矣 徐幹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbe8c32-7aa3-4820-afb3-58d2cbaac62d', '四氣', '四氣', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["春禽猶競囀，夏木忽交陰。","稍覺秋山遠，俄驚冬霰深。"]', '["春禽猶競囀，夏木忽交陰。","稍覺秋山远，俄驚冬霰深。"]', '诗', 'shi', '', NULL, '四氣 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8da3cfd-7ae4-44e2-88d8-10edf684b897', '四色 一', '四色 一', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["壺中冰始結，盤上露初圓。","何意瑤池雪，欲奪鶴毛鮮。"]', '["壺中冰始結，盤上露初圓。","何意瑤池雪，欲奪鹤毛鲜。"]', '诗', 'shi', '', NULL, '四色 一 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01e5bc67-93fe-4b56-9d7d-b2c0b1f15114', '四色 二', '四色 二', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["道士牛已至，仙家鳥亦來。","骨爲神不朽，眼向故人開。"]', '["道士牛已至，仙家鸟亦来。","骨爲神不朽，眼向故人开。"]', '诗', 'shi', '', NULL, '四色 二 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ab44cb-b70a-4dc8-9f8d-2dd1d715761e', '四色 三', '四色 三', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["勞魴蓮渚內，汗馬火旂間。","平生血誠盡，不獨左輪殷。"]', '["勞魴蓮渚內，汗马火旂间。","平生血誠尽，不独左輪殷。"]', '诗', 'shi', '', NULL, '四色 三 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d9737c3-972b-48df-84e4-690345d6addc', '四色 四', '四色 四', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["已見池盡墨，誰言突不黔。","漆身恩未報，貂裘弊豈嫌。"]', '["已见池尽墨，誰言突不黔。","漆身恩未報，貂裘弊豈嫌。"]', '诗', 'shi', '', NULL, '四色 四 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('185735b4-b90a-4212-b23f-afc0dac17a3b', '大言', '大言', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["四溟杯淥醑，五嶽髻青螺。","揮汗曾成雨，畫地亦成河。"]', '["四溟杯淥醑，五嶽髻青螺。","揮汗曾成雨，畫地亦成河。"]', '诗', 'shi', '', NULL, '大言 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b6cceb-d0d9-47f7-a69d-823dff274f69', '細言', '細言', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["蚊眉自可託，蝸角豈勞爭。","欲効絲毫力，誰知螻蟻誠。"]', '["蚊眉自可託，蝸角豈勞爭。","欲効絲毫力，誰知螻蟻誠。"]', '诗', 'shi', '', NULL, '細言 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c71dd95f-e267-4ca3-a39a-fe9292db4d4f', '山中桂', '山中桂', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["八樹拂丹霄，四時青不凋。","秋風何處起，先褭最長條。"]', '["八樹拂丹霄，四时青不凋。","秋风何处起，先褭最长條。"]', '诗', 'shi', '', NULL, '山中桂 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1ba143-42bb-453d-9c93-cd2ae33423d2', '蘆花', '蘆花', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["夾岸復連沙，枝枝搖浪花。","月明渾似雪，無處認漁家。"]', '["夾岸复連沙，枝枝搖浪花。","月明渾似雪，無处認漁家。"]', '诗', 'shi', '', NULL, '蘆花 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b7f4a4-04cc-4070-9691-49f7ea85a285', '江邊柳', '江邊柳', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["嫋嫋古堤邊，青青一樹煙。","若爲絲不斷，留取繫郎船。"]', '["嫋嫋古堤邊，青青一樹煙。","若爲絲不斷，留取繫郎船。"]', '诗', 'shi', '', NULL, '江邊柳 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8671f488-8c25-4389-9d2c-8d0f90423def', '江上山', '江上山', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["綺霞明赤岸，錦纜繞丹枝。","楚客正愁絕，西風且莫吹。"]', '["綺霞明赤岸，錦纜繞丹枝。","楚客正愁絕，西风且莫吹。"]', '诗', 'shi', '', NULL, '江上山 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed07bdf7-1d97-427a-b813-a799dc79e653', '游絲', '游絲', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["游絲何所似，應最似春心。","一向風前亂，千條不可尋。"]', '["游絲何所似，應最似春心。","一向风前亂，千條不可尋。"]', '诗', 'shi', '', NULL, '游絲 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a995dd6-3654-4985-8822-a54a58c0896f', '柳絮', '柳絮', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["無風纔到地，有風還滿空。","緣渠偏似雪，莫近鬢毛生。"]', '["無风纔到地，有风還满空。","緣渠偏似雪，莫近鬢毛生。"]', '诗', 'shi', '', NULL, '柳絮 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88820d3f-9dd5-44d6-9856-1f6c71aaa5c9', '殘鶯', '殘鶯', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["花闌鶯亦嬾，不語似含情。","何言百囀舌，唯餘一兩聲。"]', '["花闌鶯亦嬾，不語似含情。","何言百囀舌，唯餘一兩声。"]', '诗', 'shi', '', NULL, '殘鶯 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9821dd28-bd05-4339-b7de-3d7f5fe78e4e', '早蟬', '早蟬', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["一聲清溽暑，幾處促流年。","志士心偏苦，初聞獨泫然。"]', '["一声清溽暑，幾处促流年。","志士心偏苦，初闻独泫然。"]', '诗', 'shi', '', NULL, '早蟬 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c806c9c2-8095-46bc-9eb7-af8135598f2a', '秋蛩', '秋蛩', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["雨絕蒼苔地，月斜青草階。","蛩鳴誰不怨，況是正離懷。"]', '["雨絕蒼苔地，月斜青草階。","蛩鳴誰不怨，況是正離懷。"]', '诗', 'shi', '', NULL, '秋蛩 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72dcbb00-71cf-41e7-ac0e-3be3588a0e8e', '江上聞猨', '江上闻猨', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["楓岸月斜明，猨啼旅夢驚。","愁多腸易斷，不待第三聲。"]', '["楓岸月斜明，猨啼旅梦驚。","愁多腸易斷，不待第三声。"]', '诗', 'shi', '', NULL, '江上聞猨 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ee4182-ab14-4737-8593-1177650000e4', '折柳贈行人', '折柳贈行人', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["那言柳亂垂，盡日任風吹。","欲識千條恨，和煙折一枝。"]', '["那言柳亂垂，尽日任风吹。","欲識千條恨，和煙折一枝。"]', '诗', 'shi', '', NULL, '折柳贈行人 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24874ce6-2857-4664-b438-b0edeeddd629', '題蒲葵扇', '題蒲葵扇', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["傾心曾向日，在手幸搖風。","羨爾逢提握，知名自謝公。"]', '["傾心曾向日，在手幸搖风。","羨爾逢提握，知名自謝公。"]', '诗', 'shi', '', NULL, '題蒲葵扇 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2656c70c-14ef-4d3a-9270-2a1185df063b', '贈苦行僧', '贈苦行僧', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["幽深紅葉寺，清淨白毫僧。","古殿長鳴磬，低頭禮晝燈。"]', '["幽深紅葉寺，清淨白毫僧。","古殿长鳴磬，低头禮晝灯。"]', '诗', 'shi', '', NULL, '贈苦行僧 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6c99d2-8022-4fd0-b44f-69a71e5441dd', '兩頭纖纖', '兩头纖纖', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["兩頭纖纖八字眉，半白半黑燈影帷。","腷腷[膊膊]曉禽飛，磊磊落落秋果垂。"]', '["兩头纖纖八字眉，半白半黑灯影帷。","腷腷[膊膊]晓禽飞，磊磊落落秋果垂。"]', '诗', 'shi', '', NULL, '兩頭纖纖 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71c886d4-010e-48eb-ade3-d6bef06a89a3', '了語', '了語', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["掃却煙塵寇初勦，深水高林放魚鳥。","雞人唱絕殘漏曉，仙樂拍終天悄悄。"]', '["掃却煙塵寇初勦，深水高林放鱼鸟。","雞人唱絕殘漏晓，仙乐拍終天悄悄。"]', '诗', 'shi', '', NULL, '了語 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400113e1-554d-4b53-9b8b-1bd1fb79f975', '不了語', '不了語', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["浮名世利知多少，朝市喧喧塵擾擾。","車馬交馳往復來，鐘鼓相催天又曉。"]', '["浮名世利知多少，朝市喧喧塵擾擾。","车马交驰往复来，鐘鼓相催天又晓。"]', '诗', 'shi', '', NULL, '不了語 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac996c6-46f4-4c3e-bea1-666ae911badc', '聽彈沈湘', '听彈沈湘', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["賈誼投文弔屈平，瑤琴能寫此時情。","秋風一奏沈湘曲，流水千年作恨聲。"]', '["賈誼投文弔屈平，瑤琴能寫此时情。","秋风一奏沈湘曲，流水千年作恨声。"]', '诗', 'shi', '', NULL, '聽彈沈湘 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd0df055-d7b9-4fae-b979-ec07e0608cc4', '豪家夏冰詠', '豪家夏冰詠', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["金錯銀盤貯賜冰，清光如聳玉山稜。","無論塵客閑停扇，直到消時不見蠅。"]', '["金錯銀盤貯賜冰，清光如聳玉山稜。","無論塵客闲停扇，直到消时不见蠅。"]', '诗', 'shi', '', NULL, '豪家夏冰詠 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a814fd-1ab9-4929-8ef5-e04ca850144e', '宿棣華館聞雁', '宿棣华館闻雁', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["不堪旅宿棣花館，況有離羣鴻雁聲。","一點秋燈殘影下，不知寒夢幾回驚。"]', '["不堪旅宿棣花館，況有離羣鴻雁声。","一点秋灯殘影下，不知寒梦幾回驚。"]', '诗', 'shi', '', NULL, '宿棣華館聞雁 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b82ac48-695a-4089-b1a6-72f02ca4f358', '農家望晴', '農家望晴', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["嘗聞秦地西風雨，爲問西風早晚回。","白髮老農如鶴立，麥場高處望雲開。"]', '["嘗闻秦地西风雨，爲问西风早晚回。","白髮老農如鹤立，麦場高处望云开。"]', '诗', 'shi', '', NULL, '農家望晴 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d60413e-e371-4d78-81c7-64c671b37a6f', '宮人斜', '宮人斜', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["幾多紅粉委黃泥，野鳥如歌又似啼。","應有春魂化爲燕，年來飛入未央栖。"]', '["幾多紅粉委黄泥，野鸟如歌又似啼。","應有春魂化爲燕，年来飞入未央栖。"]', '诗', 'shi', '', NULL, '宮人斜 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6429b9cd-ead6-4622-a647-570e3c557aa7', '曲江池上', '曲江池上', '388b5f11-e754-4699-88a1-5dd80a18e529', '唐', '["殷勤春在曲江頭，全藉羣仙占勝遊。","何必三山待鸞鶴，年年此地是瀛洲。"]', '["殷勤春在曲江头，全藉羣仙占勝游。","何必三山待鸾鹤，年年此地是瀛洲。"]', '诗', 'shi', '', NULL, '曲江池上 雍裕之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d393803e-31e4-4bc7-b5c5-44d2df454749', '奉陪呂使君樓上夜看花', '奉陪呂使君楼上夜看花', '30962e62-340a-456f-8510-c4457ef6b594', '唐', '["城上芳園花滿枝，城頭太守夜看時。","爲報林中高舉燭，感人情思欲題詩。"]', '["城上芳园花满枝，城头太守夜看时。","爲報林中高舉燭，感人情思欲題诗。"]', '诗', 'shi', '', NULL, '奉陪呂使君樓上夜看花 段弘古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c3ffaea-e426-461a-91a2-e3e8bdf5e613', '所居寺院涼夜書情呈上呂和叔溫郎中', '所居寺院涼夜书情呈上呂和叔溫郎中', 'f14d31e3-42f9-46b3-b3bb-5b44fbf898b2', '唐', '["庾公念病宜清暑，遣向僧家占上方。","月光似水衣裳濕，松氣如秋枕簟涼。","幸以薄才當客次，無因弱羽逐鸞翔。","何由一示雲霄路，腸斷星星兩鬢霜。"]', '["庾公念病宜清暑，遣向僧家占上方。","月光似水衣裳濕，松氣如秋枕簟涼。","幸以薄才當客次，無因弱羽逐鸾翔。","何由一示云霄路，腸斷星星兩鬢霜。"]', '诗', 'shi', '', NULL, '所居寺院涼夜書情呈上呂和叔溫郎中 何元上 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6855bbb3-cf49-491a-923d-3b1817d44fca', '塞上聞笛', '塞上闻笛', '7682bebf-84a6-4bc0-b38a-e3e58afe2f8e', '唐', '["胡兒吹笛戍樓間，樓上蕭條海月閑。","借問梅花何處落，風吹一夜滿關山。"]', '["胡兒吹笛戍楼间，楼上蕭條海月闲。","借问梅花何处落，风吹一夜满关山。"]', '诗', 'shi', '', NULL, '塞上聞笛 宋濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4e82f30-de7c-46fa-b0a3-96cdd3b93aab', '塞上聞笛', '塞上闻笛', '7682bebf-84a6-4bc0-b38a-e3e58afe2f8e', '唐', '["雪淨遥天牧馬還，月明羌笛戍樓閑。","借問梅花何處落，風吹一夜滿關山。"]', '["雪淨遥天牧马還，月明羌笛戍楼闲。","借问梅花何处落，风吹一夜满关山。"]', '诗', 'shi', '', NULL, '塞上聞笛 宋濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19cbe028-c532-4ed8-8bac-6e31be493dbd', '東鄰美人歌', '东鄰美人歌', '7682bebf-84a6-4bc0-b38a-e3e58afe2f8e', '唐', '["花暖江城斜日陰，鶯啼繡戶曉雲深。","春風不道珠簾隔，傳得歌聲與客心。"]', '["花暖江城斜日陰，鶯啼繡戶晓云深。","春风不道珠簾隔，傳得歌声與客心。"]', '诗', 'shi', '', NULL, '東鄰美人歌 宋濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2ce4d22-d04d-4f8d-8ff0-ece377b5aec6', '題李八百洞', '題李八百洞', 'ff5d435e-a499-4a4e-a0d1-688cb01a766a', '唐', '["太極之年混沌坼，此山亦是神仙宅。","後世何人來飛昇，紫陽真人李八百。"]', '["太極之年混沌坼，此山亦是神仙宅。","後世何人来飞昇，紫陽真人李八百。"]', '诗', 'shi', '', NULL, '題李八百洞 符載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cad4b83-fc93-4a29-900e-a342b2d82b85', '甘州歌', '甘州歌', 'ff5d435e-a499-4a4e-a0d1-688cb01a766a', '唐', '["月裏嫦娥不畫眉，只將雲霧作羅衣。","不知夢逐青鸞去，猶把花枝蓋面歸。"]', '["月裏嫦娥不畫眉，只將云霧作羅衣。","不知梦逐青鸾去，猶把花枝蓋面归。"]', '诗', 'shi', '', NULL, '甘州歌 符載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f68351b5-88af-45e6-81ea-dbdb33d78f51', '句', '句', 'ff5d435e-a499-4a4e-a0d1-688cb01a766a', '唐', '["綠迸穿籬筍，紅飄隔戶花。"]', '["綠迸穿籬筍，紅飄隔戶花。"]', '诗', 'shi', '', NULL, '句 符載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8527b3ec-f4d8-40ae-bd54-505e4a8165be', '貞元八年十二月謁先主廟絕句三首 一', '貞元八年十二月謁先主廟絕句三首 一', '2d05e7c5-155c-4245-8ef8-057a65874442', '唐', '["仗順繼皇業，幷吞勢由己。","天命屈雄圖，誰歌大風起。"]', '["仗順繼皇業，幷吞勢由己。","天命屈雄圖，誰歌大风起。"]', '诗', 'shi', '', NULL, '貞元八年十二月謁先主廟絕句三首 一 張儼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbdff036-d789-4327-886c-939c9f29fa16', '貞元八年十二月謁先主廟絕句三首 二', '貞元八年十二月謁先主廟絕句三首 二', '2d05e7c5-155c-4245-8ef8-057a65874442', '唐', '["得股肱賢明，能以奇用兵。","何事傷客情，何人歸帝京。"]', '["得股肱賢明，能以奇用兵。","何事傷客情，何人归帝京。"]', '诗', 'shi', '', NULL, '貞元八年十二月謁先主廟絕句三首 二 張儼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf291c4-1fe4-4a1c-93e9-638a3330c7d6', '貞元八年十二月謁先主廟絕句三首 三', '貞元八年十二月謁先主廟絕句三首 三', '2d05e7c5-155c-4245-8ef8-057a65874442', '唐', '["雄名垂竹帛，荒陵壓阡陌。","終古更何聞，悲風入松栢。"]', '["雄名垂竹帛，荒陵壓阡陌。","終古更何闻，悲风入松栢。"]', '诗', 'shi', '', NULL, '貞元八年十二月謁先主廟絕句三首 三 張儼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16488c94-8f7e-4277-bdc9-fe83bce4a670', '題安樂山', '題安乐山', 'e77bb233-98bb-40d3-a12e-d2160b6fc4f3', '唐', '["碧峰橫倚白雲端，隋氏真人化蹟殘。","翠栢不凋龍骨瘦，石泉猶在鏡光寒。"]', '["碧峰橫倚白云端，隋氏真人化蹟殘。","翠栢不凋龙骨瘦，石泉猶在镜光寒。"]', '诗', 'shi', '', NULL, '題安樂山 先汪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad618fa-7d73-4df3-ab70-59a4534c5c57', '姑熟雜詠 姑熟溪', '姑熟杂詠 姑熟溪', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["愛此溪水閑，乘流興無極。","擊檝怕鷗驚，垂竿待魚食。","波翻曉霞影，岸疊春山色。","何處浣紗人，紅顏未相識。"]', '["愛此溪水闲，乘流兴無極。","擊檝怕鷗驚，垂竿待鱼食。","波翻晓霞影，岸叠春山色。","何处浣紗人，紅顏未相識。"]', '诗', 'shi', '', NULL, '姑熟雜詠 姑熟溪 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b2fa983-01ec-4aed-a9f3-3a50bc295323', '姑熟雜詠 丹陽湖', '姑熟杂詠 丹陽湖', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["湖與元氣通，風波浩難止。","天外賈客歸，雲間片帆起。","龜游蓮葉上，鳥宿蘆花裏。","少女棹舟歸，歌聲逐流水。"]', '["湖與元氣通，风波浩难止。","天外賈客归，云间片帆起。","龟游蓮葉上，鸟宿蘆花裏。","少女棹舟归，歌声逐流水。"]', '诗', 'shi', '', NULL, '姑熟雜詠 丹陽湖 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f39a71-1f3b-4772-bbf0-77963dc0e35f', '姑熟雜詠 謝公宅', '姑熟杂詠 謝公宅', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["青山日將暝，寂寞謝公宅。","竹裏無人聲，池中虛月白。","荒庭衰草徧，廢井蒼苔積。","唯有清風聞，時時起泉石。"]', '["青山日將暝，寂寞謝公宅。","竹裏無人声，池中虛月白。","荒庭衰草徧，廢井蒼苔積。","唯有清风闻，时时起泉石。"]', '诗', 'shi', '', NULL, '姑熟雜詠 謝公宅 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400b2396-b7f7-42b3-bed8-5e9cbf1a7a0d', '姑熟雜詠 凌[歊]臺', '姑熟杂詠 凌[歊]台', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["曠望登古臺，臺高極人目。","疊嶂列遠空，閑花雜平陸。","白雲入窗牖，野翠生松竹。","欲覽碑上文，苔侵豈堪讀。"]', '["曠望登古台，台高極人目。","叠嶂列远空，闲花杂平陸。","白云入窗牖，野翠生松竹。","欲覽碑上文，苔侵豈堪读。"]', '诗', 'shi', '', NULL, '姑熟雜詠 凌[歊]臺 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c91cfd-11a0-4e1f-9e52-66ee7c47d259', '姑熟雜詠 桓公井', '姑熟杂詠 桓公井', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["桓公名已古，廢井曾未竭。","石甃冷蒼苔，寒泉湛孤月。","秋來桐暫落，春至桃還發。","路遠人罕窺，誰能見清澈。"]', '["桓公名已古，廢井曾未竭。","石甃冷蒼苔，寒泉湛孤月。","秋来桐暫落，春至桃還發。","路远人罕窺，誰能见清澈。"]', '诗', 'shi', '', NULL, '姑熟雜詠 桓公井 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce3d2a74-0d46-41ac-9d58-ad95c18e0da4', '姑熟雜詠 慈姥竹', '姑熟杂詠 慈姥竹', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["野竹攢石生，含煙映江島。","翠色落波深，虛聲帶寒早。","龍吟曾未聽，鳳曲吹應好。","不學蒲柳凋，貞心常自保。"]', '["野竹攢石生，含煙映江島。","翠色落波深，虛声带寒早。","龙吟曾未听，鳳曲吹應好。","不学蒲柳凋，貞心常自保。"]', '诗', 'shi', '', NULL, '姑熟雜詠 慈姥竹 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed347645-de13-496a-9078-cea6912d3c1c', '姑熟雜詠 望夫山', '姑熟杂詠 望夫山', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["顒望臨碧空，怨情感離別。","芳草不知愁，巖花但爭發。","雲山萬重隔，音信千里絕。","春去秋復來，相思幾時歇。"]', '["顒望臨碧空，怨情感離別。","芳草不知愁，巖花但爭發。","云山万重隔，音信千里絕。","春去秋复来，相思幾时歇。"]', '诗', 'shi', '', NULL, '姑熟雜詠 望夫山 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e4e03c2-33b9-4cdd-8c8c-a5a7ec0d10e8', '姑熟雜詠 牛渚磯', '姑熟杂詠 牛渚磯', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["絕壁臨巨川，連峰勢相向。","亂石流洑間，迴波自成浪。","但驚羣木秀，莫測精靈狀。","更聽猨夜啼，憂心醉江上。"]', '["絕壁臨巨川，連峰勢相向。","亂石流洑间，迴波自成浪。","但驚羣木秀，莫測精靈狀。","更听猨夜啼，憂心醉江上。"]', '诗', 'shi', '', NULL, '姑熟雜詠 牛渚磯 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d05392d8-6055-4a73-8f26-21182eb38768', '姑熟雜詠 靈墟山', '姑熟杂詠 靈墟山', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["丁令辭世人，拂衣向仙路。","伏鍊九丹成，方隨五雲去。","松蘿蔽幽洞，桃杏深隱處。","不知曾化鶴，遼海歸幾度。"]', '["丁令辞世人，拂衣向仙路。","伏鍊九丹成，方隨五云去。","松蘿蔽幽洞，桃杏深隐处。","不知曾化鹤，遼海归幾度。"]', '诗', 'shi', '', NULL, '姑熟雜詠 靈墟山 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('765fdf4b-1622-4468-a1d7-809dff28a441', '姑熟雜詠 天門山', '姑熟杂詠 天门山', '42a65ed4-02f7-436e-810d-ead68f874253', '唐', '["迥出江水上，雙峰自相對。","岸映松色寒，石分浪花碎。","參差遠天際，縹緲晴霞外。","落日舟去遙，回首沈青靄。"]', '["迥出江水上，雙峰自相对。","岸映松色寒，石分浪花碎。","參差远天際，縹緲晴霞外。","落日舟去遙，回首沈青靄。"]', '诗', 'shi', '', NULL, '姑熟雜詠 天門山 李赤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('670a79ca-fcc1-46a5-b5d5-f23d05fe5e64', '勅贈康尚書美人', '勅贈康尚书美人', '37dc3078-76a0-448a-bb59-aea3e65868c5', '唐', '["天門喜氣曉氛氳，聖主臨軒召冠軍。","欲令從此行霖雨，先賜巫山一片雲。"]', '["天门喜氣晓氛氳，聖主臨軒召冠軍。","欲令從此行霖雨，先賜巫山一片云。"]', '诗', 'shi', '', NULL, '勅贈康尚書美人 薛𦀒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27cfd8f3-dc04-4569-9a92-3539b04cf58a', '將赴東都上李相國', '將赴东都上李相国', '038a9217-f6d5-4da7-bf92-c0b91e797ec4', '唐', '["四海兵初偃，平津閣正開。","誰知大爐火，還有不然灰。"]', '["四海兵初偃，平津閣正开。","誰知大爐火，還有不然灰。"]', '诗', 'shi', '', NULL, '將赴東都上李相國 孫叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9d715f-464e-4976-83ae-e95220d1417a', '題昭應溫泉', '題昭應溫泉', '038a9217-f6d5-4da7-bf92-c0b91e797ec4', '唐', '["一道溫泉遶御樓，先皇曾向此中游。","雖然水是無情物，也到宮前咽不流。"]', '["一道溫泉遶御楼，先皇曾向此中游。","雖然水是無情物，也到宮前咽不流。"]', '诗', 'shi', '', NULL, '題昭應溫泉 孫叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f3fd12d-8dd2-41b7-a5ef-62aa300a3bbe', '送咸安公主', '送咸安公主', '038a9217-f6d5-4da7-bf92-c0b91e797ec4', '唐', '["鹵簿遲遲出國門，漢家公主嫁烏孫。","玉顏便向穹廬去，衛霍空承明主恩。"]', '["鹵簿遲遲出国门，漢家公主嫁烏孫。","玉顏便向穹廬去，衛霍空承明主恩。"]', '诗', 'shi', '', NULL, '送咸安公主 孫叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03d2d673-c147-4a37-a717-fbe578d229bf', '邊城柳', '邊城柳', '710f339c-95a5-4c8f-8be4-734cc16e4aa1', '唐', '["一株新柳色，十里斷孤城。","爲近東西路，長懸離別情。"]', '["一株新柳色，十里斷孤城。","爲近东西路，长懸離別情。"]', '诗', 'shi', '', NULL, '邊城柳 劉皂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20696ee7-637c-42bc-8dce-ef4a1dd67b37', '長門怨三首 一', '长门怨三首 一', '710f339c-95a5-4c8f-8be4-734cc16e4aa1', '唐', '["雨滴長門秋夜長，愁心和雨到昭陽。","淚痕不學君恩斷，拭却千行更萬行。"]', '["雨滴长门秋夜长，愁心和雨到昭陽。","泪痕不学君恩斷，拭却千行更万行。"]', '诗', 'shi', '', NULL, '長門怨三首 一 劉皂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d995cd69-6e1a-4f0d-bc9d-bbbedc747d33', '長門怨三首 二', '长门怨三首 二', '710f339c-95a5-4c8f-8be4-734cc16e4aa1', '唐', '["宮殿沈沈月欲分，昭陽更漏不堪聞。","珊瑚枕上千行淚，不是思君是恨君。"]', '["宮殿沈沈月欲分，昭陽更漏不堪闻。","珊瑚枕上千行泪，不是思君是恨君。"]', '诗', 'shi', '', NULL, '長門怨三首 二 劉皂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14025f1e-c4e6-4a70-b0c7-0f5c46720449', '長門怨三首 三', '长门怨三首 三', '710f339c-95a5-4c8f-8be4-734cc16e4aa1', '唐', '["蟬鬢慵梳倚帳門，蛾眉不掃慣承恩。","旁人未必知心事，一面殘妝空淚痕。"]', '["蟬鬢慵梳倚帳门，蛾眉不掃慣承恩。","旁人未必知心事，一面殘妝空泪痕。"]', '诗', 'shi', '', NULL, '長門怨三首 三 劉皂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a9d922c-4204-4708-8664-7618495553be', '旅次朔方', '旅次朔方', '710f339c-95a5-4c8f-8be4-734cc16e4aa1', '唐', '["客舍幷州數十霜，歸心日夜憶咸陽。","無端又渡桑乾水，却望幷州似故鄉。"]', '["客舍幷州數十霜，归心日夜憶咸陽。","無端又渡桑乾水，却望幷州似故乡。"]', '诗', 'shi', '', NULL, '旅次朔方 劉皂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af5c74a2-84a3-4dac-9e4c-c86065f395a2', '早起', '早起', 'f5d64608-9c1e-4233-b4bc-4741733f5fa1', '唐', '["星漢轉寒更，伊余索寞情。","鐘催歸夢斷，雁引遠愁生。","危壁蘭光暗，疎簾露氣清。","閑庭聊一望，海日爲分明。"]', '["星漢轉寒更，伊余索寞情。","鐘催归梦斷，雁引远愁生。","危壁蘭光暗，疎簾露氣清。","闲庭聊一望，海日爲分明。"]', '诗', 'shi', '', NULL, '早起 楊厚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a7bc67-c231-4821-908b-d6c0e81007d4', '長門怨', '长门怨', 'aae75949-588d-4fb8-8a52-286732c05f63', '唐', '["自閉長門經幾秋，羅衣濕盡淚還流。","一種蛾眉明月夜，南宮歌管北宮愁。"]', '["自閉长门經幾秋，羅衣濕尽泪還流。","一種蛾眉明月夜，南宮歌管北宮愁。"]', '诗', 'shi', '', NULL, '長門怨 裴交泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a6e2d0-d3e7-4335-aed4-72f88593b741', '禁中送任山人', '禁中送任山人', 'fda5ac6d-4f7c-465d-8879-83df69b33d63', '唐', '["子去非長往，君恩取大還。","補天留彩石，縮地入青山。","獻壽千春外，來朝數月間。","莫拋殘藥物，竊取駐童顏。"]', '["子去非长往，君恩取大還。","補天留彩石，縮地入青山。","獻壽千春外，来朝數月间。","莫拋殘藥物，竊取駐童顏。"]', '诗', 'shi', '', NULL, '禁中送任山人 李祕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d0922f-6240-4a11-8e01-adeec4928421', '府試中元觀道流步虛', '府試中元观道流步虛', '1ade54a1-841c-437c-9b95-54598329abbc', '唐', '["玄都開秘籙，白石禮先生。","上界秋光靜，中元夜景清。","星辰朝帝處，鸞鶴步虛聲。","玉洞花長發，珠宮月最明。","掃壇天地肅，投簡鬼神驚。","儻賜刀圭藥，還成不死名。"]', '["玄都开秘籙，白石禮先生。","上界秋光静，中元夜景清。","星辰朝帝处，鸾鹤步虛声。","玉洞花长發，珠宮月最明。","掃壇天地肅，投簡鬼神驚。","儻賜刀圭藥，還成不死名。"]', '诗', 'shi', '', NULL, '府試中元觀道流步虛 殷堯恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a25bff-3b02-442b-bb20-aee0cbac4d2a', '王仙壇', '王仙壇', '5766d30b-6228-4bc2-bc26-b5f48f4abd7b', '唐', '["羽客已登仙路去，丹鑪草木盡凋殘。","不知千載歸何日，空使時人掃舊壇。"]', '["羽客已登仙路去，丹鑪草木尽凋殘。","不知千載归何日，空使时人掃旧壇。"]', '诗', 'shi', '', NULL, '王仙壇 林傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4fb444-ae63-4764-8acd-dabf1e82fe23', '乞巧', '乞巧', '5766d30b-6228-4bc2-bc26-b5f48f4abd7b', '唐', '["七夕今宵看碧霄，牽牛織女渡河橋。","家家乞巧望秋月，穿盡紅絲幾萬條。"]', '["七夕今宵看碧霄，牽牛织女渡河橋。","家家乞巧望秋月，穿尽紅絲幾万條。"]', '诗', 'shi', '', NULL, '乞巧 林傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('903bd047-49ab-401d-a07f-4c62095f3dca', '句', '句', '5766d30b-6228-4bc2-bc26-b5f48f4abd7b', '唐', '["金盤摘下挂朱顆，紅殼開時飲玉漿。"]', '["金盤摘下挂朱顆，紅殼开时饮玉漿。"]', '诗', 'shi', '', NULL, '句 林傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ae0c1a8-700c-4f7d-a8a3-d6b3615f3dd7', '哭林傑', '哭林傑', 'e3bb075a-96e8-405b-b2db-32e721a2037d', '唐', '["才高未及賈生年，何事孤魂逐逝川。","螢聚帳中人已去，鶴離臺上月空圓。"]', '["才高未及賈生年，何事孤魂逐逝川。","螢聚帳中人已去，鹤離台上月空圓。"]', '诗', 'shi', '', NULL, '哭林傑 鄭立之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('603011ce-f76d-48f8-84b5-da89d641b408', '詠和親', '詠和親', 'ee9a77ef-9b62-4ebe-815f-a770f68d3875', '唐', '["關月夜懸青冢鏡，寒雲秋薄漢宮羅。","君王莫信和親策，生得胡雛虜更多。"]', '["关月夜懸青冢镜，寒云秋薄漢宮羅。","君王莫信和親策，生得胡雛虜更多。"]', '诗', 'shi', '', NULL, '詠和親 蘇郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51a5fb3-9e4c-483f-a4a3-502c02cda6b5', '鸚鵡詞', '鸚鵡词', 'ee9a77ef-9b62-4ebe-815f-a770f68d3875', '唐', '["莫把金籠閉鸚鵡，箇箇分明解人語。","忽然更向君前言，三十六宮愁幾許。"]', '["莫把金籠閉鸚鵡，箇箇分明解人語。","忽然更向君前言，三十六宮愁幾許。"]', '诗', 'shi', '', NULL, '鸚鵡詞 蘇郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bbd87b4-c9f0-4434-aca4-25b1a0ea5fb6', '步虛詞', '步虛词', 'ee9a77ef-9b62-4ebe-815f-a770f68d3875', '唐', '["十二樓藏玉堞中，鳳凰雙宿碧芙蓉。","流霞淺酌誰同醉，今夜笙歌第幾重。"]', '["十二楼藏玉堞中，鳳凰雙宿碧芙蓉。","流霞淺酌誰同醉，今夜笙歌第幾重。"]', '诗', 'shi', '', NULL, '步虛詞 蘇郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe67e7a5-7f23-4293-adf1-d7fb1c8b7a64', '句', '句', 'ee9a77ef-9b62-4ebe-815f-a770f68d3875', '唐', '["吟倚雨殘樹，月收山下村。"]', '["吟倚雨殘樹，月收山下村。"]', '诗', 'shi', '', NULL, '句 蘇郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1642ad20-a4da-43e3-884e-bf41e837f10d', '賦得琢玉成器', '賦得琢玉成器', 'be4218c0-f689-49d0-b974-39ec26a60cc8', '唐', '["已沐識堅貞，應憐器未成。","輝山方可重，散璞乍堪驚。","玷滅隨心正，瑕消奪眼明。","琢磨虹氣在，拂拭水容生。","賞翫冰光冷，提攜月魄輕。","佇當親捧握，瑚璉幸齊名。"]', '["已沐識堅貞，應怜器未成。","輝山方可重，散璞乍堪驚。","玷滅隨心正，瑕消奪眼明。","琢磨虹氣在，拂拭水容生。","賞翫冰光冷，提携月魄轻。","佇當親捧握，瑚璉幸齊名。"]', '诗', 'shi', '', NULL, '賦得琢玉成器 浩虛舟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7323d9ca-ba59-47f3-bceb-b47a0278e872', '責商山四皓', '責商山四皓', '422ff150-5512-4a7a-9920-6c433a513a3e', '唐', '["秦末家家思逐鹿，商山四皓獨忘機。","如何鬢髮霜相似，更出深山定是非。"]', '["秦末家家思逐鹿，商山四皓独忘機。","如何鬢髮霜相似，更出深山定是非。"]', '诗', 'shi', '', NULL, '責商山四皓 蔡京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1856cf-c7d6-4e06-bdd0-488281bf93ab', '假節邕交道由吳溪', '假節邕交道由吳溪', '422ff150-5512-4a7a-9920-6c433a513a3e', '唐', '["停橈橫水中，舉目孤煙外。","借問吳溪人，誰家有山賣。"]', '["停橈橫水中，舉目孤煙外。","借问吳溪人，誰家有山賣。"]', '诗', 'shi', '', NULL, '假節邕交道由吳溪 蔡京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d84bafce-1546-4d65-be8d-e3528e5cc367', '詠子規', '詠子規', '422ff150-5512-4a7a-9920-6c433a513a3e', '唐', '["千年冤魄化爲禽，永逐悲風叫遠林。","愁血滴花春豔死，月明飄浪冷光沈。","凝成紫塞風前淚，驚破紅樓夢裏心。","腸斷楚詞歸不得，劒門迢遰蜀江深。"]', '["千年冤魄化爲禽，永逐悲风叫远林。","愁血滴花春豔死，月明飄浪冷光沈。","凝成紫塞风前泪，驚破紅楼梦裏心。","腸斷楚词归不得，劒门迢遰蜀江深。"]', '诗', 'shi', '', NULL, '詠子規 蔡京 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3bb0eb8-5bf2-4489-9edf-1ff56178c787', '獻蔡京', '獻蔡京', 'b6fa77c7-2ab1-46f1-adde-604dbdf7c8b2', '唐', '["拋却長竿卷却絲，手持蓑笠獻新詩。","臨川太守清如鏡，不是漁人下釣時。"]', '["拋却长竿卷却絲，手持蓑笠獻新诗。","臨川太守清如镜，不是漁人下釣时。"]', '诗', 'shi', '', NULL, '獻蔡京 張頂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('687d3659-19ca-4e01-b6a6-a92a9d01b076', '享惠昭太子廟樂章', '享惠昭太子廟乐章', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["既潔酒醴，聿陳熟腥。","肅將震念，昭格儲靈。","展矣禮典，薰然德馨。","愔愔管磬，亦具是聽。"]', '["既潔酒醴，聿陳熟腥。","肅將震念，昭格儲靈。","展矣禮典，薰然德馨。","愔愔管磬，亦具是听。"]', '诗', 'shi', '', NULL, '享惠昭太子廟樂章 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd5eb30-e884-4c6b-ae9d-fc0cc866d226', '望京樓上寄令狐華州', '望京楼上寄令狐华州', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["祗役滯南服，頹思屬暮年。","閑上望京臺，萬山蔽其前。","落日歸飛翼，連翩東北天。","涪江適在下，爲我久潺湲。","中葉成文教，德威清遠邊。","頒條信徒爾，華髮生蒼然。","寄懷三峰守，岐路隔雲煙。"]', '["祗役滯南服，頹思屬暮年。","闲上望京台，万山蔽其前。","落日归飞翼，連翩东北天。","涪江適在下，爲我久潺湲。","中葉成文教，德威清远邊。","頒條信徒爾，华髮生蒼然。","寄懷三峰守，岐路隔云煙。"]', '诗', 'shi', '', NULL, '望京樓上寄令狐華州 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e6cf897-36ad-477a-9cc9-d1c9cde971c7', '再赴襄陽辱宣武相公貽詩今用奉酬', '再赴襄陽辱宣武相公貽诗今用奉酬', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["解韍辭丹禁，揚旌去赤墀。","自驚非素望，何力及清時。","又據三公席，多慙四老祠。","峴山風已遠，棠樹事難追。","江漢饒春色，荆蠻足夢思。","唯憐吐鳳句，相示鑿龍期。"]', '["解韍辞丹禁，揚旌去赤墀。","自驚非素望，何力及清时。","又據三公席，多慙四老祠。","峴山风已远，棠樹事难追。","江漢饒春色，荆蠻足梦思。","唯怜吐鳳句，相示鑿龙期。"]', '诗', 'shi', '', NULL, '再赴襄陽辱宣武相公貽詩今用奉酬 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8cd4e1-2227-47f3-ae49-2c567d0c6033', '奉送李相公重鎮襄陽', '奉送李相公重鎮襄陽', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["海內埏埴徧，漢陰旌斾還。","望留丹闕下，恩在紫霄間。","冰雪背秦嶺，風煙經武關。","樹皆人尚愛，轅即吏曾攀。","自惜兩心合，相看雙鬢斑。","終期謝戎務，同隱鑿龍山。"]', '["海內埏埴徧，漢陰旌斾還。","望留丹闕下，恩在紫霄间。","冰雪背秦嶺，风煙經武关。","樹皆人尚愛，轅即吏曾攀。","自惜兩心合，相看雙鬢斑。","終期謝戎務，同隐鑿龙山。"]', '诗', 'shi', '', NULL, '奉送李相公重鎮襄陽 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b54bcc9-2aa7-43ec-8d3c-2e29138e5a3a', '和嚴揆省中宿齋遇令狐員外當直之作', '和嚴揆省中宿斋遇令狐員外當直之作', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["致齋分直宿南宮，越石盧諶此夜同。","位極班行猶念舊，名題章奏亦從公。","曾驅爪士三邊靜，新贈髯參六義窮。","竟夕文昌知有月，可憐如在庾樓中。"]', '["致斋分直宿南宮，越石盧諶此夜同。","位極班行猶念旧，名題章奏亦從公。","曾驱爪士三邊静，新贈髯參六義窮。","竟夕文昌知有月，可怜如在庾楼中。"]', '诗', 'shi', '', NULL, '和嚴揆省中宿齋遇令狐員外當直之作 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c0838e-bd8c-4b12-9669-3d27ee29a4ac', '奉酬忠武李相公見寄', '奉酬忠武李相公见寄', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["直繼先朝衛與英，能移孝友作忠貞。","劒門失險曾縛虎，淮水安流緣斬鯨。","黃閣碧幢惟是儉，三公二伯未爲榮。","惠連忽贈池塘句，又遣羸師破膽驚。"]', '["直繼先朝衛與英，能移孝友作忠貞。","劒门失險曾縛虎，淮水安流緣斬鯨。","黄閣碧幢惟是儉，三公二伯未爲榮。","惠連忽贈池塘句，又遣羸師破膽驚。"]', '诗', 'shi', '', NULL, '奉酬忠武李相公見寄 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc948e9-b51c-4816-a914-d5fea60403e4', '酬致政楊祭酒見寄', '酬致政楊祭酒见寄', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["初還相印罷戎旃，獲守皇居在紫煙。","妄比酇侯功蔑爾，每懷疏傅意悠然。","應將半俸霑閭里，料入中條訪洞天。","十載別離那可道，倍令驚喜見來篇。"]', '["初還相印罷戎旃，獲守皇居在紫煙。","妄比酇侯功蔑爾，每懷疏傅意悠然。","應將半俸霑閭里，料入中條訪洞天。","十載別離那可道，倍令驚喜见来篇。"]', '诗', 'shi', '', NULL, '酬致政楊祭酒見寄 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7472bede-ec71-48cf-9b45-26ca7ec65ac1', '送令狐秀才赴舉', '送令狐秀才赴舉', '2db0b02e-25c1-4351-9fd7-5f29fc60a673', '唐', '["子有雄文藻思繁，齠年射策向金門。","前隨鸞鶴登霄漢，却望風沙走塞垣。","獨憶忘機陪出處，自憐何力繼飛翻。","那堪兩地生離緒，蓬戶長扃行旅喧。"]', '["子有雄文藻思繁，齠年射策向金门。","前隨鸾鹤登霄漢，却望风沙走塞垣。","独憶忘機陪出处，自怜何力繼飞翻。","那堪兩地生離緒，蓬戶长扃行旅喧。"]', '诗', 'shi', '', NULL, '送令狐秀才赴舉 李逢吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8eb0b45-88ed-475c-afc8-5a7cb868a116', '郡齋臥疾贈晝上人', '郡斋臥疾贈晝上人', '10b08d37-db47-47c6-96ad-5b0d94e879ba', '唐', '["夙陪翰墨徒，深論窮文格。","麗則風騷後，公然我詞客。","晚依方外友，極理探精賾。","吻合南北宗，晝公我禪伯。","尤明性不染，故我行貞白。","隨順令得解，故我言芳澤。","霅水漾清潯，吳山橫碧岑。","含珠復蘊玉，價重雙南金。","的皪曜奇彩，淒清流雅音。","商聲發楚調，調切譜瑤琴。","吳山爲我高，霅水爲我深。","萬景徒有象，孤雲本無心。","衆木豈無聲，椅桐有清響。","衆耳豈不聆，鍾期有真賞。","高潔古人操，素懷夙所仰。","覿君冰雪姿，祛我淫滯想。","常吟柳惲詩，苕浦久相思。","逮此遠爲郡，蘋洲芳草衰。","逢師年臘長，值我病容羸。","共話無生理，聊用契心期。"]', '["夙陪翰墨徒，深論窮文格。","丽則风騷後，公然我词客。","晚依方外友，極理探精賾。","吻合南北宗，晝公我禪伯。","尤明性不染，故我行貞白。","隨順令得解，故我言芳澤。","霅水漾清潯，吳山橫碧岑。","含珠复蘊玉，價重雙南金。","的皪曜奇彩，淒清流雅音。","商声發楚調，調切譜瑤琴。","吳山爲我高，霅水爲我深。","万景徒有象，孤云本無心。","衆木豈無声，椅桐有清响。","衆耳豈不聆，鍾期有真賞。","高潔古人操，素懷夙所仰。","覿君冰雪姿，祛我淫滯想。","常吟柳惲诗，苕浦久相思。","逮此远爲郡，蘋洲芳草衰。","逢師年臘长，值我病容羸。","共話無生理，聊用契心期。"]', '诗', 'shi', '', NULL, '郡齋臥疾贈晝上人 于頔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('549fb397-6297-4c75-bbe0-f9bace405b5d', '和丘員外題湛長史舊居', '和丘員外題湛长史旧居', '10b08d37-db47-47c6-96ad-5b0d94e879ba', '唐', '["蕭條歷山下，水木無氛滓。","王門結長裾，巖扃怡暮齒。","昔賢枕高躅，今彥仰知止。","依依矚煙霞，眷眷返墟里。","湛生久已沒，丘也亦同恥。","立言咸不朽，何必在青史。"]', '["蕭條歷山下，水木無氛滓。","王门結长裾，巖扃怡暮齒。","昔賢枕高躅，今彥仰知止。","依依矚煙霞，眷眷返墟里。","湛生久已沒，丘也亦同恥。","立言咸不朽，何必在青史。"]', '诗', 'shi', '', NULL, '和丘員外題湛長史舊居 于頔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b164994f-94c1-4b16-920a-0725c091bedb', '寒夜聞霜鐘', '寒夜闻霜鐘', '0d83aede-aa1e-4242-bab9-346bc5d03020', '唐', '["洪鐘發長夜，清響出層岑。","暗入繁霜切，遙傳古寺深。","何城亂遠漏，幾處雜疎砧。","已警離人夢，仍霑旅客襟。","待時當命侶，抱器本無心。","儻若無知者，誰能設此音。"]', '["洪鐘發长夜，清响出層岑。","暗入繁霜切，遙傳古寺深。","何城亂远漏，幾处杂疎砧。","已警離人梦，仍霑旅客襟。","待时當命侶，抱器本無心。","儻若無知者，誰能設此音。"]', '诗', 'shi', '', NULL, '寒夜聞霜鐘 盧景亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd30d03-bad0-4f27-b9fb-7212cd74d89b', '南溪詩', '南溪诗', 'a1a05324-626d-4c9b-93f7-6d9ab7e63659', '唐', '["玄巖麗南溪，新泉發幽色。","巖泉孕靈秀，雲煙紛崖壁。","斜峰信天插，奇洞固神闢。","窈窕去未窮，環迴勢難極。","玉池似無水，玄井昏不測。","仙戶掩復開，乳膏凝更滴。","丹砂有遺址，石徑無留跡。","南眺蒼梧雲，北望洞庭客。","蕭條風煙外，爽朗形神寂。","若值浮丘翁，從此謝塵役。"]', '["玄巖丽南溪，新泉發幽色。","巖泉孕靈秀，云煙紛崖壁。","斜峰信天插，奇洞固神闢。","窈窕去未窮，环迴勢难極。","玉池似無水，玄井昏不測。","仙戶掩复开，乳膏凝更滴。","丹砂有遺址，石徑無留跡。","南眺蒼梧云，北望洞庭客。","蕭條风煙外，爽朗形神寂。","若值浮丘翁，從此謝塵役。"]', '诗', 'shi', '', NULL, '南溪詩 李渤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b795db08-a132-4d2c-9925-654193077602', '喜弟淑再至爲長歌', '喜弟淑再至爲长歌', 'a1a05324-626d-4c9b-93f7-6d9ab7e63659', '唐', '["前年別時秋九月，白露吹霜金吹烈。","離鴻一別影初分，淚袖雙揮心哽咽。","別來幾度得音書，南岳知□□□□。","廬山峨峨倚天碧，捧排空崖千萬尺。","社牓長題高士名，食堂每記雲山跡。","我本開雲此山住，偶爲名利相縈誤。","自負心機四十年，羞聞社客山中篇。","憂時魂夢憶歸路，覺來疑在林中眠。","昨日亭前烏鵲喜，果得今朝爾來此。","吾吟行路五十篇，盡說江南數千里。","自憐兄弟今五人，共縈儒素家尚貧。","雖然廩餼各不一，就中總免拘常倫。","長兄年少曾落托，拔劒沙場隨衛霍。","口裏雖譚周孔文，懷中不舍孫吳略。","次兄一生能苦節，夏聚流螢冬映雪。","非論疾惡志如霜，更覺臨泉心似鐵。","第三之兄更奇異，昂昂獨負青雲志。","下看金玉不如泥，肯道王侯身可貴。","却愁清逸不干時，高蹤大器無人知。","倘逢感激許然諾，必能萬古留清規。","念爾年來方二十，夙夜孜孜能獨立。","卷中筆落星漢搖，洞裏丹靈鬼神泣。","嗟余流浪心最狂，十年學劒逢時康。","心中不解事拘束，世間談笑多相妨。","廣海青山殊未足，逢著高樓還醉宿。","朝走安公櫪上駒，暮倫陶令籬邊菊。","近來詩思殊無況，苦被時流不相放。","雲騰浪走勢未衰，鶴膝蜂腰豈能障。","送爾爲文殊不識，貴從一一傳胷臆。","若到湖南見紫霄，會須待我同攀陟。"]', '["前年別时秋九月，白露吹霜金吹烈。","離鴻一別影初分，泪袖雙揮心哽咽。","別来幾度得音书，南岳知□□□□。","廬山峨峨倚天碧，捧排空崖千万尺。","社牓长題高士名，食堂每記云山跡。","我本开云此山住，偶爲名利相縈誤。","自負心機四十年，羞闻社客山中篇。","憂时魂梦憶归路，覺来疑在林中眠。","昨日亭前烏鵲喜，果得今朝爾来此。","吾吟行路五十篇，尽说江南數千里。","自怜兄弟今五人，共縈儒素家尚貧。","雖然廩餼各不一，就中總免拘常倫。","长兄年少曾落托，拔劒沙場隨衛霍。","口裏雖譚周孔文，懷中不舍孫吳略。","次兄一生能苦節，夏聚流螢冬映雪。","非論疾惡志如霜，更覺臨泉心似鐵。","第三之兄更奇異，昂昂独負青云志。","下看金玉不如泥，肯道王侯身可貴。","却愁清逸不干时，高蹤大器無人知。","倘逢感激許然諾，必能万古留清規。","念爾年来方二十，夙夜孜孜能独立。","卷中笔落星漢搖，洞裏丹靈鬼神泣。","嗟余流浪心最狂，十年学劒逢时康。","心中不解事拘束，世间談笑多相妨。","廣海青山殊未足，逢著高楼還醉宿。","朝走安公櫪上駒，暮倫陶令籬邊菊。","近来诗思殊無況，苦被时流不相放。","云腾浪走勢未衰，鹤膝蜂腰豈能障。","送爾爲文殊不識，貴從一一傳胷臆。","若到湖南见紫霄，會須待我同攀陟。"]', '诗', 'shi', '', NULL, '喜弟淑再至爲長歌 李渤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f00a135-544d-4360-9988-a8bea3fe943a', '留別南溪二首 一', '留別南溪二首 一', 'a1a05324-626d-4c9b-93f7-6d9ab7e63659', '唐', '["常歎春泉去不回，我今此去更難來。","欲知別後留情處，手種巖花次第開。"]', '["常歎春泉去不回，我今此去更难来。","欲知別後留情处，手種巖花次第开。"]', '诗', 'shi', '', NULL, '留別南溪二首 一 李渤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10719e77-ef12-475d-9f69-be8809c12649', '留別南溪二首 二', '留別南溪二首 二', 'a1a05324-626d-4c9b-93f7-6d9ab7e63659', '唐', '["如雲不厭蒼梧遠，似鴈逢春又北歸。","惟有隱山溪上月，年年相望兩依依。"]', '["如云不厭蒼梧远，似鴈逢春又北归。","惟有隐山溪上月，年年相望兩依依。"]', '诗', 'shi', '', NULL, '留別南溪二首 二 李渤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('770594bc-7922-4ac1-b7b6-38f972d20ae1', '桂林歎鴈', '桂林歎鴈', 'a1a05324-626d-4c9b-93f7-6d9ab7e63659', '唐', '["三朝四黜倦遐征，往復皆愁萬里程。","爾解分飛却回去，我方從此向南行。"]', '["三朝四黜倦遐征，往复皆愁万里程。","爾解分飞却回去，我方從此向南行。"]', '诗', 'shi', '', NULL, '桂林歎鴈 李渤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc67ec48-0190-4d7b-8486-b1fca790b357', '享惠昭太子廟樂章', '享惠昭太子廟乐章', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["喧喧金石容既缺，肅肅羽駕就行列。","緱山遺響昔所聞，廟庭進旅今攸設。"]', '["喧喧金石容既缺，肅肅羽駕就行列。","緱山遺响昔所闻，廟庭進旅今攸設。"]', '诗', 'shi', '', NULL, '享惠昭太子廟樂章 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20bd82ef-4cd6-4bb0-8729-cb29b5d04157', '擬古', '擬古', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["劒客不誇貌，主人知此心。","但營纖毫義，肯計千萬金。","勇發看鷙擊，憤來聽虎吟。","平生貴酬德，刃敵無幽深。"]', '["劒客不誇貌，主人知此心。","但營纖毫義，肯計千万金。","勇發看鷙擊，憤来听虎吟。","平生貴酬德，刃敵無幽深。"]', '诗', 'shi', '', NULL, '擬古 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f780230-4ba7-484e-8614-400c6ca4e19d', '詠歐陽行周事', '詠歐陽行周事', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["有客西北逐，驅馬次太原。","太原有佳人，神豔照行雲。","座上轉橫波，流光注夫君。","夫君意蕩漾，即日相交歡。","定情非一詞，結念誓青山。","生死不變易，中誠無間言。","此爲太學徒，彼屬北府官。","中夜欲相從，嚴城限軍門。","白日欲同居，君畏仁人聞。","忽如隴頭水，坐作東西分。","驚離腸千結，滴淚眼雙昏。","本達京師迴，賀期相追攀。","宿約始乖阻，彼憂已纏緜。","高髻若黃鸝，危鬢如玉蟬。","纖手自整理，剪刀斷其根。","柔情託侍兒，爲我遺所歡。","所歡使者來，侍兒因復前。","抆淚取遺寄，深誠祈爲傳。","封來贈君子，願言慰窮泉。","使者迴復命，遲遲蓄悲酸。","詹生喜言旋，倒屨走迎門。","長跪聽未畢，驚傷涕漣漣。","不飲亦不食，哀心百千端。","襟情一夕空，精爽旦日殘。","哀哉浩然氣，潰散歸化元。","短生雖別離，長夜無阻難。","雙魂終會合，兩劒遂蜿蜒。","丈夫早通脫，巧笑安能干。","防身本苦節，一去何由還。","後生莫沈迷，沈迷喪其真。"]', '["有客西北逐，驱马次太原。","太原有佳人，神豔照行云。","座上轉橫波，流光注夫君。","夫君意蕩漾，即日相交歡。","定情非一词，結念誓青山。","生死不变易，中誠無间言。","此爲太学徒，彼屬北府官。","中夜欲相從，嚴城限軍门。","白日欲同居，君畏仁人闻。","忽如隴头水，坐作东西分。","驚離腸千結，滴泪眼雙昏。","本達京師迴，賀期相追攀。","宿約始乖阻，彼憂已纏緜。","高髻若黄鸝，危鬢如玉蟬。","纖手自整理，剪刀斷其根。","柔情託侍兒，爲我遺所歡。","所歡使者来，侍兒因复前。","抆泪取遺寄，深誠祈爲傳。","封来贈君子，願言慰窮泉。","使者迴复命，遲遲蓄悲酸。","詹生喜言旋，倒屨走迎门。","长跪听未畢，驚傷涕漣漣。","不饮亦不食，哀心百千端。","襟情一夕空，精爽旦日殘。","哀哉浩然氣，潰散归化元。","短生雖別離，长夜無阻难。","雙魂終會合，兩劒遂蜿蜒。","丈夫早通脫，巧笑安能干。","防身本苦節，一去何由還。","後生莫沈迷，沈迷喪其真。"]', '诗', 'shi', '', NULL, '詠歐陽行周事 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('788adf7b-78dd-4750-81ad-cd59c871a18e', '惜分陰', '惜分陰', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["業廣因功苦，拳拳志士心。","九流難酌挹，四海易消沉。","對景嗟移晷，窺園詎改陰。","三冬勞聚學，駟景重兼金。","刺股情方勵，偷光思益深。","再中如可冀，終嗣絕編音。"]', '["業廣因功苦，拳拳志士心。","九流难酌挹，四海易消沉。","对景嗟移晷，窺园詎改陰。","三冬勞聚学，駟景重兼金。","刺股情方勵，偷光思益深。","再中如可冀，終嗣絕編音。"]', '诗', 'shi', '', NULL, '惜分陰 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5727b7ac-a026-4b83-bb4b-b8fe0706636d', '嘉禾合穎', '嘉禾合穎', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["玉燭將成歲，封人亦自歌。","八方霑聖澤，異畝發嘉禾。","共秀芳何遠，連莖瑞且多。","穎低甘露滴，影亂惠風過。","表稔由神化，爲祥識氣和。","因知興嗣歲，王道舊無頗。"]', '["玉燭將成歲，封人亦自歌。","八方霑聖澤，異畝發嘉禾。","共秀芳何远，連莖瑞且多。","穎低甘露滴，影亂惠风過。","表稔由神化，爲祥識氣和。","因知兴嗣歲，王道旧無頗。"]', '诗', 'shi', '', NULL, '嘉禾合穎 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f4ec54-5d81-4fd5-8eef-abf0908ed971', '賦得亞父碎玉斗', '賦得亞父碎玉斗', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["獻謀既我違，積憤從心痗。","鴻門入已迫，赤帝時潛退。","寶位方苦競，玉斗何情愛。","猶看虹氣凝，詎惜冰姿碎。","而嗟大事返，當起千里悔。","誰爲西楚王，坐見東城潰。"]', '["獻謀既我違，積憤從心痗。","鴻门入已迫，赤帝时潛退。","寶位方苦競，玉斗何情愛。","猶看虹氣凝，詎惜冰姿碎。","而嗟大事返，當起千里悔。","誰爲西楚王，坐见东城潰。"]', '诗', 'shi', '', NULL, '賦得亞父碎玉斗 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c79c77-63ae-4bf2-9f93-5c7132301dd5', '酬施先輩', '酬施先輩', 'bd272f87-8332-47ff-b1f6-849e80d96d8f', '唐', '["襄陽才子得聲多，四海皆傳古鏡歌。","樂府正聲三百首，[梨]園新入教青娥。"]', '["襄陽才子得声多，四海皆傳古镜歌。","乐府正声三百首，[梨]园新入教青娥。"]', '诗', 'shi', '', NULL, '酬施先輩 孟簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e31443-c3ec-4c2a-8c39-bdb2d589aa29', '寄李十員外', '寄李十員外', '0b705791-f702-4c37-900b-ce1af1806af1', '唐', '["百丈懸泉舊臥龍，欲將肝膽佐時雍。","惟愁又入煙霞去，知在廬峰第幾重。"]', '["百丈懸泉旧臥龙，欲將肝膽佐时雍。","惟愁又入煙霞去，知在廬峰第幾重。"]', '诗', 'shi', '', NULL, '寄李十員外 王仲舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('162eb552-a496-4979-87e2-e441847d4e6f', '訪羊尊師', '訪羊尊師', '526c9d0a-6fc3-4112-a4b7-9070e0dada8e', '唐', '["松下問童子，言師採藥去。","只在此山中，雲深不知處。"]', '["松下问童子，言師採藥去。","只在此山中，云深不知处。"]', '诗', 'shi', '', NULL, '訪羊尊師 孫革 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17508318-e5f7-487d-8087-88637ee17c96', '晚眺', '晚眺', 'ca9a628c-53dc-4f0b-88f1-dd936579ef3f', '唐', '["杖策倚柴門，泉聲隔岸聞。","夕陽諸嶺出，晴雪萬山分。","靜對豺狼窟，幽觀鹿豕羣。","今宵寒月近，東北埽浮雲。"]', '["杖策倚柴门，泉声隔岸闻。","夕陽諸嶺出，晴雪万山分。","静对豺狼窟，幽观鹿豕羣。","今宵寒月近，东北埽浮云。"]', '诗', 'shi', '', NULL, '晚眺 汪萬於 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250fab5b-4a5c-47bd-8ef0-d9d82e14b16b', '亞父碎玉斗', '亞父碎玉斗', '2ffbe3f9-3bd3-4e85-a30f-731748c10ba8', '唐', '["嬴女昔解網，楚王有遺躅。","破關既定秦，碎首聞獻玉。","貞姿應刃散，清響因風續。","匪狥切泥功，將明懷璧辱。","莫量漢祖德，空受項君勗。","事去見前心，千秋渭水綠。"]', '["嬴女昔解網，楚王有遺躅。","破关既定秦，碎首闻獻玉。","貞姿應刃散，清响因风續。","匪狥切泥功，將明懷璧辱。","莫量漢祖德，空受項君勗。","事去见前心，千秋渭水綠。"]', '诗', 'shi', '', NULL, '亞父碎玉斗 何儒亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6adbaba6-15ae-4ed1-96b2-fd45c5d18d23', '贈毛仙翁', '贈毛仙翁', '87f7de9f-3c5a-4c96-88c0-3a8b22562705', '唐', '["不知仙客占青春，肌骨纔教稱兩旬。","俗眼暫驚相見日，疑心未測幾時人。","閑推甲子經何代，笑說浮生老此身。","殘藥儻能沾朽質，願將霄漢永爲鄰。"]', '["不知仙客占青春，肌骨纔教稱兩旬。","俗眼暫驚相见日，疑心未測幾时人。","闲推甲子經何代，笑说浮生老此身。","殘藥儻能沾朽質，願將霄漢永爲鄰。"]', '诗', 'shi', '', NULL, '贈毛仙翁 李宗閔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4545449-1757-4265-96bb-8fb65870b953', '池州夫子廟麟臺', '池州夫子廟麟台', '6c39473a-3173-4ca2-b57a-1a874785ca14', '唐', '["二儀既閉，三象乃乖。","聖道埋鬱，人心不開。","上無文武，下有定哀。","吁嗟麟兮，孰爲來哉。","周雖不綱，孔實嗣聖。","詩書既刪，禮樂大定。","勸善懲惡，姦邪乃正。","吁嗟麟兮，克昭符命。","聖與時合，化行位尊。","苟或乖戾，身窮道存。","於昭魯邑，棲遲孔門。","吁嗟麟兮，孰知其仁。","運極數殘，德至時否。","楚國寖廣，秦封益侈。","牆仞迫阨，崎嶇闕里。","吁嗟麟兮，靡有攸止。","世治則麟，世亂則麕。","出非其時，麋鹿同羣。","孔不自聖，麟不自祥。","吁嗟麟兮，天何所亡。"]', '["二儀既閉，三象乃乖。","聖道埋鬱，人心不开。","上無文武，下有定哀。","吁嗟麟兮，孰爲来哉。","周雖不綱，孔實嗣聖。","诗书既刪，禮乐大定。","勸善懲惡，姦邪乃正。","吁嗟麟兮，克昭符命。","聖與时合，化行位尊。","苟或乖戾，身窮道存。","於昭魯邑，棲遲孔门。","吁嗟麟兮，孰知其仁。","運極數殘，德至时否。","楚国寖廣，秦封益侈。","牆仞迫阨，崎嶇闕里。","吁嗟麟兮，靡有攸止。","世治則麟，世亂則麕。","出非其时，麋鹿同羣。","孔不自聖，麟不自祥。","吁嗟麟兮，天何所亡。"]', '诗', 'shi', '', NULL, '池州夫子廟麟臺 韋表微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e46a04-dba5-4ecb-952f-416ed2cd527c', '送馬向入蜀', '送马向入蜀', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["遊子出咸京，巴山萬里程。","白雲連鳥道，青壁遰猨聲。","雨雪經泥坂，煙花望錦城。","工文人共許，應紀蜀中行。"]', '["游子出咸京，巴山万里程。","白云連鸟道，青壁遰猨声。","雨雪經泥坂，煙花望錦城。","工文人共許，應紀蜀中行。"]', '诗', 'shi', '', NULL, '送馬向入蜀 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991d5c5b-acb7-43c9-8389-24e4e32c1c05', '送李補闕歸朝', '送李補闕归朝', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["駟馬歸咸秦，雙鳧出海門。","還從清切禁，再沐聖明恩。","禮樂中朝貴，文章大雅存。","江湖多放逸，獻替欲誰論。"]', '["駟马归咸秦，雙鳧出海门。","還從清切禁，再沐聖明恩。","禮乐中朝貴，文章大雅存。","江湖多放逸，獻替欲誰論。"]', '诗', 'shi', '', NULL, '送李補闕歸朝 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2c273aa-9617-4100-bbca-193f58f31d5f', '送日本使還', '送日本使還', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["絕國將無外，扶桑更有東。","來朝逢聖日，歸去及秋風。","夜泛潮迴際，晨征蒼莽中。","鯨波騰水府，蜃氣壯仙宮。","天眷何期遠，王文久已同。","相望杳不見，離恨托飛鴻。"]', '["絕国將無外，扶桑更有东。","来朝逢聖日，归去及秋风。","夜泛潮迴際，晨征蒼莽中。","鯨波腾水府，蜃氣壯仙宮。","天眷何期远，王文久已同。","相望杳不见，離恨托飞鴻。"]', '诗', 'shi', '', NULL, '送日本使還 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9baec9fe-04ce-4768-a180-4b89e4f877ae', '題開元寺牡丹', '題开元寺牡丹', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["此花南地知難種，慚愧僧閑用意栽。","海燕解憐頻睥睨，胡蜂未識更徘徊。","虛生芍藥徒勞妒，羞殺玫瑰不敢開。","惟有數苞紅蕚在，含芳只待舍人來。"]', '["此花南地知难種，慚愧僧闲用意栽。","海燕解怜頻睥睨，胡蜂未識更徘徊。","虛生芍藥徒勞妒，羞殺玫瑰不敢开。","惟有數苞紅蕚在，含芳只待舍人来。"]', '诗', 'shi', '', NULL, '題開元寺牡丹 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55d2348a-a37d-4823-924a-076e72e86451', '香爐峰', '香爐峰', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["香爐一峰絕，頂在寺門前。","盡是玲瓏石，時生旦暮煙。"]', '["香爐一峰絕，頂在寺门前。","尽是玲瓏石，时生旦暮煙。"]', '诗', 'shi', '', NULL, '香爐峰 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17ef0a8-ab13-40ad-8372-77ca7ed74d98', '白銅鞮', '白銅鞮', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["騕褭錦障泥，樓頭日又西。","留歡住不住，素齒白銅鞮。"]', '["騕褭錦障泥，楼头日又西。","留歡住不住，素齒白銅鞮。"]', '诗', 'shi', '', NULL, '白銅鞮 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ab2b31-9c18-457b-909b-17a6581d1fbd', '楊叛兒', '楊叛兒', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["哀怨楊叛兒，駘蕩郎知否。","香死博山爐，煙生白門柳。"]', '["哀怨楊叛兒，駘蕩郎知否。","香死博山爐，煙生白门柳。"]', '诗', 'shi', '', NULL, '楊叛兒 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b846b5-590c-4b5f-b207-b047060fe574', '春寒', '春寒', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["亂雪從教舞，回風任聽吹。","春寒能作底，已被柳條欺。"]', '["亂雪從教舞，回风任听吹。","春寒能作底，已被柳條欺。"]', '诗', 'shi', '', NULL, '春寒 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d346c4dc-4c39-45bc-ac89-33f0a917781e', '廬山獨夜', '廬山独夜', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["寒空五老雪，斜月九江雲。","鐘聲知何處，蒼蒼樹裏聞。"]', '["寒空五老雪，斜月九江云。","鐘声知何处，蒼蒼樹裏闻。"]', '诗', 'shi', '', NULL, '廬山獨夜 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb45cedb-7f1c-4a52-8db3-bd19eb2e8ff4', '天台獨夜', '天台独夜', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["銀地秋月色，石梁夜溪聲。","誰知屐齒盡，爲破煙苔行。"]', '["銀地秋月色，石梁夜溪声。","誰知屐齒尽，爲破煙苔行。"]', '诗', 'shi', '', NULL, '天台獨夜 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f7c052-7358-4b2d-996f-ea11c6f60009', '送寒巖歸士', '送寒巖归士', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["不挂絲纊衣，歸向寒巖棲。","寒巖風雪夜，又過巖前溪。"]', '["不挂絲纊衣，归向寒巖棲。","寒巖风雪夜，又過巖前溪。"]', '诗', 'shi', '', NULL, '送寒巖歸士 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b841c536-c468-4588-85bd-196dbc4c1d57', '送陳司馬', '送陳司马', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["家寄茅洞中，身遊越城下。","寧知許長史，不憶陳司馬。"]', '["家寄茅洞中，身游越城下。","寧知許长史，不憶陳司马。"]', '诗', 'shi', '', NULL, '送陳司馬 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c38ebe-ad88-49a6-813e-ab4ae75323fb', '武夷山仙城', '武夷山仙城', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["武夷無上路，毛徑不通風。","欲共麻姑住，仙城半在空。"]', '["武夷無上路，毛徑不通风。","欲共麻姑住，仙城半在空。"]', '诗', 'shi', '', NULL, '武夷山仙城 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d394ffc-594e-4190-92d4-1d24efe48cce', '避暑二首 一', '避暑二首 一', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["一株金染密，數畝碧鮮疎。","避暑臨溪坐，何妨直釣魚。"]', '["一株金染密，數畝碧鲜疎。","避暑臨溪坐，何妨直釣鱼。"]', '诗', 'shi', '', NULL, '避暑二首 一 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe3d8c6-37fc-4bc9-bc9e-1088182cb3b7', '避暑二首 二', '避暑二首 二', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["斑多筒簟冷，髮少角冠清。","避暑長林下，寒蟬又有聲。"]', '["斑多筒簟冷，髮少角冠清。","避暑长林下，寒蟬又有声。"]', '诗', 'shi', '', NULL, '避暑二首 二 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69a917d4-ac5e-4de2-b02a-4e74ac948ef4', '浙西李尚書奏毀淫昏廟', '浙西李尚书奏毀淫昏廟', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["傳聞廢淫祀，萬里靜山陂。","欲慰靈均恨，先燒靳尚祠。"]', '["傳闻廢淫祀，万里静山陂。","欲慰靈均恨，先燒靳尚祠。"]', '诗', 'shi', '', NULL, '浙西李尚書奏毀淫昏廟 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfe1a801-5a11-4b7c-91b8-35fef6586d6a', '酬相公再遊雲門寺', '酬相公再游云门寺', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["遠羨五雲路，逶迤千騎回。","遺簪唯一去，貴賞不重來。"]', '["远羨五云路，逶迤千騎回。","遺簪唯一去，貴賞不重来。"]', '诗', 'shi', '', NULL, '酬相公再遊雲門寺 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52b7f53-837c-4f84-91ea-62e7428bbbe0', '杭州祝濤頭二首 一', '杭州祝濤头二首 一', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["不道沙堤盡，猶欺石棧頑。","寄言飛白雪，休去打青山。"]', '["不道沙堤尽，猶欺石棧頑。","寄言飞白雪，休去打青山。"]', '诗', 'shi', '', NULL, '杭州祝濤頭二首 一 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7ef894-3733-4537-b206-78e9cdae884e', '杭州祝濤頭二首 二', '杭州祝濤头二首 二', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["倒打錢塘郭，長驅白浪花。","吞吳休得也，輸却五千家。"]', '["倒打錢塘郭，长驱白浪花。","吞吳休得也，輸却五千家。"]', '诗', 'shi', '', NULL, '杭州祝濤頭二首 二 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('922c7947-1e06-4f51-a593-0f5205ba434c', '問漁叟', '问漁叟', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["生事同漂梗，機心在野船。","如何臨逝水，白髮未忘筌。"]', '["生事同漂梗，機心在野船。","如何臨逝水，白髮未忘筌。"]', '诗', 'shi', '', NULL, '問漁叟 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94b5fa09-9eef-4b3c-acc3-99cd9be66a57', '雲封菴', '云封菴', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["登巖背山河，立石秋風裏。","隱見浙江濤，一尺東溝水。"]', '["登巖背山河，立石秋风裏。","隐见浙江濤，一尺东溝水。"]', '诗', 'shi', '', NULL, '雲封菴 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c36c7a57-52d7-46d0-8fa9-036d7802c8aa', '漢宮曲', '漢宮曲', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["水色簾前流玉霜，趙家飛燕侍昭陽。","掌中舞罷簫聲絕，三十六宮秋夜長。"]', '["水色簾前流玉霜，趙家飞燕侍昭陽。","掌中舞罷簫声絕，三十六宮秋夜长。"]', '诗', 'shi', '', NULL, '漢宮曲 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a0d35e-9aae-4ed8-b659-770eed8c0770', '和嵩陽客月夜憶上清人', '和嵩陽客月夜憶上清人', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["獨夜嵩陽憶上仙，月明三十六峰前。","瑤池月勝嵩陽月，人在玉清眠不眠。"]', '["独夜嵩陽憶上仙，月明三十六峰前。","瑤池月勝嵩陽月，人在玉清眠不眠。"]', '诗', 'shi', '', NULL, '和嵩陽客月夜憶上清人 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aa09ddf-357d-4b7b-a3e9-8b8ea7913829', '八月望夕雨', '八月望夕雨', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["今年八月十五夜，寒雨蕭蕭不可聞。","如練如霜在何處，吳山越水萬重雲。"]', '["今年八月十五夜，寒雨蕭蕭不可闻。","如練如霜在何处，吳山越水万重云。"]', '诗', 'shi', '', NULL, '八月望夕雨 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994f5da5-7097-49f3-9225-8f268fca39da', '觀浙江濤', '观浙江濤', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["浙江悠悠海西綠，驚濤日夜兩翻覆。","錢塘郭裏看潮人，直至白頭看不足。"]', '["浙江悠悠海西綠，驚濤日夜兩翻覆。","錢塘郭裏看潮人，直至白头看不足。"]', '诗', 'shi', '', NULL, '觀浙江濤 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7448b7d5-4a3b-40f9-9174-5b0405dd04b0', '廬山瀑布', '廬山瀑布', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["虛空落泉千仞直，雷奔入江不暫息。","今古長如白練飛，一條界破青山色。"]', '["虛空落泉千仞直，雷奔入江不暫息。","今古长如白練飞，一條界破青山色。"]', '诗', 'shi', '', NULL, '廬山瀑布 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c632e93-518e-46e1-af7c-3dadd656f33f', '嘉興寒食', '嘉兴寒食', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["嘉興郭裏逢寒食，落日家家拜掃回。","唯有縣前蘇小小，無人送與紙錢來。"]', '["嘉兴郭裏逢寒食，落日家家拜掃回。","唯有縣前蘇小小，無人送與紙錢来。"]', '诗', 'shi', '', NULL, '嘉興寒食 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7a8989-7aa2-4665-901e-6b979e4bbb2e', '憶揚州', '憶揚州', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["蕭娘臉下難勝淚，桃葉眉頭易得愁。","天下三分明月夜，二分無賴是揚州。"]', '["蕭娘臉下难勝泪，桃葉眉头易得愁。","天下三分明月夜，二分無賴是揚州。"]', '诗', 'shi', '', NULL, '憶揚州 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ceefec8-ea4d-4e8d-9059-9a35acdfa91c', '八月燈夕寄游越施秀才', '八月灯夕寄游越施秀才', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["四天淨色寒如水，八月清輝冷似霜。","想得越人今夜見，孟家珠在鏡中央。"]', '["四天淨色寒如水，八月清輝冷似霜。","想得越人今夜见，孟家珠在镜中央。"]', '诗', 'shi', '', NULL, '八月燈夕寄游越施秀才 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c98876-3e6b-489a-b6f4-ec3a4fd386c5', '八月十五夜', '八月十五夜', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["皎皎秋空八月圓，常娥端正桂枝鮮。","一年無似如今夜，十二峰前看不眠。"]', '["皎皎秋空八月圓，常娥端正桂枝鲜。","一年無似如今夜，十二峰前看不眠。"]', '诗', 'shi', '', NULL, '八月十五夜 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f04cb3ec-4bb5-4194-a31a-8e46bf754193', '題伍員廟', '題伍員廟', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["千載空祠雲海頭，夫差亡國已千秋。","浙波只有靈濤在，拜奠青山人不休。"]', '["千載空祠云海头，夫差亡国已千秋。","浙波只有靈濤在，拜奠青山人不休。"]', '诗', 'shi', '', NULL, '題伍員廟 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c7717e-b8b5-4e3c-8ef7-fe0fb2e9c71b', '員嶠先生', '員嶠先生', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["員嶠先生無白髮，海煙深處採青芝。","逢人借問陶唐主，欲進冰蠶五色絲。"]', '["員嶠先生無白髮，海煙深处採青芝。","逢人借问陶唐主，欲進冰蠶五色絲。"]', '诗', 'shi', '', NULL, '員嶠先生 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d32af5f1-8458-4156-9878-1877b48e665b', '莫愁曲', '莫愁曲', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["玳瑁牀頭刺戰袍，碧紗窗外葉騷騷。","若爲教作遼西夢，月冷如丁風似刀。"]', '["玳瑁牀头刺戰袍，碧紗窗外葉騷騷。","若爲教作遼西梦，月冷如丁风似刀。"]', '诗', 'shi', '', NULL, '莫愁曲 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0405336-8492-4a9b-a4b0-81ea656a22a8', '寄白司馬', '寄白司马', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["三條九陌花時節，萬戶千車看牡丹。","爭遣江州白司馬，五年風景憶長安。"]', '["三條九陌花时節，万戶千车看牡丹。","爭遣江州白司马，五年风景憶长安。"]', '诗', 'shi', '', NULL, '寄白司馬 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a72210d-7fe6-4ba8-86e8-a854668fb0a9', '相思林', '相思林', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["遊客遠遊新過嶺，每逢芳樹問芳名。","長林遍是相思樹，爭遣愁人獨自行。"]', '["游客远游新過嶺，每逢芳樹问芳名。","长林遍是相思樹，爭遣愁人独自行。"]', '诗', 'shi', '', NULL, '相思林 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae58f860-dc11-42d4-8654-ca8c355a3434', '寄海嶠丈人', '寄海嶠丈人', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["萬丈只愁滄海淺，一身誰測歲華遙。","自言來此雲邊住，曾看秦王樹石橋。"]', '["万丈只愁滄海淺，一身誰測歲华遙。","自言来此云邊住，曾看秦王樹石橋。"]', '诗', 'shi', '', NULL, '寄海嶠丈人 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd9a677-68fa-483b-97a8-9b9ea2a69d01', '寄潘先生', '寄潘先生', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["至人知姓不知名，聞道黃金骨節輕。","世上仙方無覓處，欲來西岳事先生。"]', '["至人知姓不知名，闻道黄金骨節轻。","世上仙方無覓处，欲来西岳事先生。"]', '诗', 'shi', '', NULL, '寄潘先生 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715a7902-5fa5-46cf-a794-5e37ef35ae2a', '宮中曲二首 一', '宮中曲二首 一', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["披香侍宴插山花，厭著龍綃著越紗。","恃賴傾城人不及，檀妝唯約數條霞。"]', '["披香侍宴插山花，厭著龙綃著越紗。","恃賴傾城人不及，檀妝唯約數條霞。"]', '诗', 'shi', '', NULL, '宮中曲二首 一 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b91577e-ed76-4404-9954-05bb4de06515', '宮中曲二首 二', '宮中曲二首 二', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["身輕入寵盡恩私，腰細偏能舞柘枝。","一日新妝拋舊樣，六宮爭畫黑煙眉。"]', '["身轻入寵尽恩私，腰細偏能舞柘枝。","一日新妝拋旧樣，六宮爭畫黑煙眉。"]', '诗', 'shi', '', NULL, '宮中曲二首 二 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086d2815-fe51-4aad-8bfe-269496d5de65', '七夕', '七夕', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["一道鵲橋橫渺渺，千聲玉佩過玲玲。","別離還有經年客，悵望不如河鼓星。"]', '["一道鵲橋橫渺渺，千声玉佩過玲玲。","別離還有經年客，悵望不如河鼓星。"]', '诗', 'shi', '', NULL, '七夕 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3591fea0-3fb3-4d3c-9ed2-374867002317', '八月九月望夕雨', '八月九月望夕雨', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["八月繁雲連九月，兩回三五晦漫漫。","一年悵望秋將盡，不得常娥正面看。"]', '["八月繁云連九月，兩回三五晦漫漫。","一年悵望秋將尽，不得常娥正面看。"]', '诗', 'shi', '', NULL, '八月九月望夕雨 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('233c7498-3fc7-4190-89b5-4842d0fd91a3', '喜雪', '喜雪', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["長愛謝家能詠雪，今朝見雪亦狂歌。","楊花道即偷人句，不那楊花似雪何。"]', '["长愛謝家能詠雪，今朝见雪亦狂歌。","楊花道即偷人句，不那楊花似雪何。"]', '诗', 'shi', '', NULL, '喜雪 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('641ed906-b317-4613-8f29-98a524c19524', '春飲', '春饮', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["烏家若下蟻還浮，白玉尊前倒即休。","不是春來偏愛酒，應須得酒遣春愁。"]', '["烏家若下蟻還浮，白玉尊前倒即休。","不是春来偏愛酒，應須得酒遣春愁。"]', '诗', 'shi', '', NULL, '春飲 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1edd4936-c8a8-4a6c-893e-49d9d43db7bf', '二月望日', '二月望日', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["長短一年相似夜，中秋未必勝中春。","不寒不暖看明月，況是從來少睡人。"]', '["长短一年相似夜，中秋未必勝中春。","不寒不暖看明月，況是從来少睡人。"]', '诗', 'shi', '', NULL, '二月望日 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eecab1ae-38c6-4ea2-83da-9c5612bd7d2b', '讀遠書', '读远书', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["兩轉三回讀遠書，畫簷愁見燕歸初。","百花時節教人懶，雲髻朝來不欲梳。"]', '["兩轉三回读远书，畫簷愁见燕归初。","百花时節教人懶，云髻朝来不欲梳。"]', '诗', 'shi', '', NULL, '讀遠書 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d1655d8-7580-4fa8-b1e4-5dcd76d874aa', '古樹', '古樹', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["古樹欹斜臨古道，枝不生花腹生草。","行人不見樹少時，樹見行人幾番老。"]', '["古樹欹斜臨古道，枝不生花腹生草。","行人不见樹少时，樹见行人幾番老。"]', '诗', 'shi', '', NULL, '古樹 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4873d783-4757-4029-85c0-69dc29106ed5', '獨住僧', '独住僧', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["百補袈裟一比丘，數莖長睫覆青眸。","多應獨住山林慣，唯照寒泉自剃頭。"]', '["百補袈裟一比丘，數莖长睫覆青眸。","多應独住山林慣，唯照寒泉自剃头。"]', '诗', 'shi', '', NULL, '獨住僧 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf5db86-e16e-4685-92e0-7f180519ed59', '傷畫松道芬上人', '傷畫松道芬上人', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["百法驅馳百年壽，五勞消瘦五株松。","昨來聞道嚴陵死，畫到青山第幾重。"]', '["百法驱驰百年壽，五勞消瘦五株松。","昨来闻道嚴陵死，畫到青山第幾重。"]', '诗', 'shi', '', NULL, '傷畫松道芬上人 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5317925-f4e2-4ce6-a9d1-904dca95aa02', '觀釣臺畫圖', '观釣台畫圖', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["一水寂寥青靄合，兩崖崔崒白雲殘。","畫人心到啼猨破，欲作三聲出樹難。"]', '["一水寂寥青靄合，兩崖崔崒白云殘。","畫人心到啼猨破，欲作三声出樹难。"]', '诗', 'shi', '', NULL, '觀釣臺畫圖 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e102ac4-c075-454b-b10f-074ef7a659ad', '荆巫夢思', '荆巫梦思', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["楚水白波風嫋嫋，荆門暮色雨蕭蕭。","相思合眼夢何處，十二峰高巴字遙。"]', '["楚水白波风嫋嫋，荆门暮色雨蕭蕭。","相思合眼梦何处，十二峰高巴字遙。"]', '诗', 'shi', '', NULL, '荆巫夢思 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f444129-eafc-4295-80b2-e360e7177965', '浙東故孟尚書種柳', '浙东故孟尚书種柳', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["孟家種柳東城去，臨水逶迤思故人。","不似當時大司馬，重來得見漢南春。"]', '["孟家種柳东城去，臨水逶迤思故人。","不似當时大司马，重来得见漢南春。"]', '诗', 'shi', '', NULL, '浙東故孟尚書種柳 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353125de-d604-4520-b693-c2e1ec81c427', '長洲覽古', '长洲覽古', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["吳王上國長洲奢，翠黛寒江一道斜。","傷見摧殘舊宮樹，美人曾插九枝花。"]', '["吳王上国长洲奢，翠黛寒江一道斜。","傷见摧殘旧宮樹，美人曾插九枝花。"]', '诗', 'shi', '', NULL, '長洲覽古 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb3bdb2-86cb-4aee-90c3-c0ddd158a531', '却歸舊山望月有寄', '却归旧山望月有寄', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["年年明月總相似，大抵人情自不同。","今夜故山依舊見，班家扇樣碧峰東。"]', '["年年明月總相似，大抵人情自不同。","今夜故山依旧见，班家扇樣碧峰东。"]', '诗', 'shi', '', NULL, '却歸舊山望月有寄 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9dbda3-46ee-418f-9d1f-1b8a8cb01978', '再歸松溪舊居宿西林', '再归松溪旧居宿西林', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["五粒松深溪水清，衆山搖落月偏明。","西林靜夜重來宿，暗記人家犬吠聲。"]', '["五粒松深溪水清，衆山搖落月偏明。","西林静夜重来宿，暗記人家犬吠声。"]', '诗', 'shi', '', NULL, '再歸松溪舊居宿西林 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ec5edfe-d19e-4bb8-bc0c-be952d409560', '翫花五首 一', '翫花五首 一', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["一樹梨花春向暮，雪枝殘處怨風來。","明朝漸校無多去，看到黃昏不欲回。"]', '["一樹梨花春向暮，雪枝殘处怨风来。","明朝漸校無多去，看到黄昏不欲回。"]', '诗', 'shi', '', NULL, '翫花五首 一 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e62c8d7-4195-48cb-ada8-e79a38ac5156', '翫花五首 二', '翫花五首 二', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["麴塵溪上素紅枝，影在溪流半落時。","時人自惜花腸斷，春風却是等閑吹。"]', '["麴塵溪上素紅枝，影在溪流半落时。","时人自惜花腸斷，春风却是等闲吹。"]', '诗', 'shi', '', NULL, '翫花五首 二 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1e3b5f-95ce-4547-8023-a03811b1bea9', '翫花五首 三', '翫花五首 三', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["朱霞燄燄山枝動，綠野聲聲杜宇來。","誰爲蜀王身作鳥，自啼還自有花開。"]', '["朱霞燄燄山枝动，綠野声声杜宇来。","誰爲蜀王身作鸟，自啼還自有花开。"]', '诗', 'shi', '', NULL, '翫花五首 三 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7bf5a7-cb56-4556-82d3-ec722530bb99', '翫花五首 四', '翫花五首 四', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["誰家躑躅青林裏，半見殷花燄燄枝。","憶得倡樓人送客，深紅衫子影門時。"]', '["誰家躑躅青林裏，半见殷花燄燄枝。","憶得倡楼人送客，深紅衫子影门时。"]', '诗', 'shi', '', NULL, '翫花五首 四 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('566a30d5-2bb2-4cc4-95c0-babac12c7f99', '翫花五首 五', '翫花五首 五', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["花到薔薇明豔絕，燕支顆破麥風秋。","一番弄色一番退，小婦輕妝大婦愁。"]', '["花到薔薇明豔絕，燕支顆破麦风秋。","一番弄色一番退，小婦轻妝大婦愁。"]', '诗', 'shi', '', NULL, '翫花五首 五 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e22d3d-2784-4bc4-bcc9-6984dc6f668b', '長慶春', '长慶春', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["山頭水色薄籠煙，久客新愁長慶年。","身上五勞仍病酒，夭桃窗下背花眠。"]', '["山头水色薄籠煙，久客新愁长慶年。","身上五勞仍病酒，夭桃窗下背花眠。"]', '诗', 'shi', '', NULL, '長慶春 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff3b293-afd6-4eef-ad94-aecea2746558', '山鷓鴣詞', '山鷓鴣词', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["南越嶺頭山鷓鴣，傳是當時守貞女。","化爲飛鳥怨何人，猶有啼聲帶蠻語。"]', '["南越嶺头山鷓鴣，傳是當时守貞女。","化爲飞鸟怨何人，猶有啼声带蠻語。"]', '诗', 'shi', '', NULL, '山鷓鴣詞 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff7772b-6089-422b-a982-2fc5a9a2508a', '鄭女出參丈人詞', '鄭女出參丈人词', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["鳳釵翠翹雙宛轉，出見丈人梳洗晚。","掣曳羅綃跪拜時，柳條無力花枝軟。"]', '["鳳釵翠翹雙宛轉，出见丈人梳洗晚。","掣曳羅綃跪拜时，柳條無力花枝軟。"]', '诗', 'shi', '', NULL, '鄭女出參丈人詞 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('149a5238-59ef-4501-8e84-eeea990d5962', '春雨', '春雨', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["花時悶見聯綿雨，雲入人家水毀堤。","昨日春風源上路，可憐紅錦枉拋泥。"]', '["花时悶见聯綿雨，云入人家水毀堤。","昨日春风源上路，可怜紅錦枉拋泥。"]', '诗', 'shi', '', NULL, '春雨 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b40eb9-9bc0-4e38-861f-87c78dc2b1cc', '和白使君木蘭花', '和白使君木蘭花', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["枝枝轉勢雕弓動，片片搖光玉劍斜。","見說木蘭征戍女，不知那作酒邊花。"]', '["枝枝轉勢雕弓动，片片搖光玉劍斜。","见说木蘭征戍女，不知那作酒邊花。"]', '诗', 'shi', '', NULL, '和白使君木蘭花 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c201a86-27e5-487d-b958-460347483b5f', '正月十五夜呈幕中諸公', '正月十五夜呈幕中諸公', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["宵遊二萬七千人，獨坐重城圈一身。","步月遊山俱不得，可憐辜負白頭春。"]', '["宵游二万七千人，独坐重城圈一身。","步月游山俱不得，可怜辜負白头春。"]', '诗', 'shi', '', NULL, '正月十五夜呈幕中諸公 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16df4f91-7c43-4f97-91da-a45c9521b9ff', '樂府新詩', '乐府新诗', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["一聲盧女十三弦，早嫁城西好少年。","不羨越溪歌者苦，采蓮歸去綠窗眠。"]', '["一声盧女十三弦，早嫁城西好少年。","不羨越溪歌者苦，采蓮归去綠窗眠。"]', '诗', 'shi', '', NULL, '樂府新詩 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0d9fb55-eb6b-4c6a-99b9-1a36b1818155', '春陪相公看花宴會二首 一', '春陪相公看花宴會二首 一', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["丞相邀歡事事同，玉簫金管咽東風。","百分春酒莫辭醉，明日的無今日紅。"]', '["丞相邀歡事事同，玉簫金管咽东风。","百分春酒莫辞醉，明日的無今日紅。"]', '诗', 'shi', '', NULL, '春陪相公看花宴會二首 一 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('485b786c-c2e9-4167-a5de-26b61e3c0aa5', '春陪相公看花宴會二首 二', '春陪相公看花宴會二首 二', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["木蘭花謝可憐條，遠道音書轉寂寥。","春去一年春又盡，幾回空上望江橋。"]', '["木蘭花謝可怜條，远道音书轉寂寥。","春去一年春又尽，幾回空上望江橋。"]', '诗', 'shi', '', NULL, '春陪相公看花宴會二首 二 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d92a8b79-23d1-42ab-a105-ea4df0edf603', '牡丹', '牡丹', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["何人不愛牡丹花，占斷城中好物華。","疑是洛川神女作，千嬌萬態破朝霞。"]', '["何人不愛牡丹花，占斷城中好物华。","疑是洛川神女作，千嬌万態破朝霞。"]', '诗', 'shi', '', NULL, '牡丹 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8691918b-6845-4472-be12-e5173044f98c', '過馬當', '過马當', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["風波隱隱石蒼蒼，送客靈鴉拂去檣。","三月盡頭雲葉秀，小姑新著好衣裳。"]', '["风波隐隐石蒼蒼，送客靈鴉拂去檣。","三月尽头云葉秀，小姑新著好衣裳。"]', '诗', 'shi', '', NULL, '過馬當 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60bc0251-0d8a-488b-858c-310f6559d0d0', '金谷覽古', '金谷覽古', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["金谷園中數尺土，問人知是綠珠臺。","綠珠歌舞天下絕，唯與石家生禍胎。"]', '["金谷园中數尺土，问人知是綠珠台。","綠珠歌舞天下絕，唯與石家生禍胎。"]', '诗', 'shi', '', NULL, '金谷覽古 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22362105-f266-4297-b3e9-d54b40adf8f0', '上陽紅葉', '上陽紅葉', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["洛下三分紅葉秋，二分翻作上陽愁。","千聲萬片御溝上，一片出宮何處流。"]', '["洛下三分紅葉秋，二分翻作上陽愁。","千声万片御溝上，一片出宮何处流。"]', '诗', 'shi', '', NULL, '上陽紅葉 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9002272b-b17f-43bc-9b70-715b067e9395', '洛城秋砧', '洛城秋砧', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["三川水上秋砧發，五鳳樓前明月新。","誰爲秋砧明月夜，洛陽城裏更愁人。"]', '["三川水上秋砧發，五鳳楼前明月新。","誰爲秋砧明月夜，洛陽城裏更愁人。"]', '诗', 'shi', '', NULL, '洛城秋砧 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c40946-0b38-4853-960c-bbe5a15bf403', '和川守侍郎緱山題仙廟', '和川守侍郎緱山題仙廟', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["王子緱山石殿明，白家詩句詠吹笙。","安知散席人間曲，不是寥天鶴上聲。"]', '["王子緱山石殿明，白家诗句詠吹笙。","安知散席人间曲，不是寥天鹤上声。"]', '诗', 'shi', '', NULL, '和川守侍郎緱山題仙廟 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21539a9f-7b53-40d1-a3dc-d37e59b8b9e2', '和夜題玉泉寺', '和夜題玉泉寺', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["歲歲雲山玉泉寺，年年車馬洛陽塵。","風清月冷水邊宿，詩好官高能幾人。"]', '["歲歲云山玉泉寺，年年车马洛陽塵。","风清月冷水邊宿，诗好官高能幾人。"]', '诗', 'shi', '', NULL, '和夜題玉泉寺 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e23f47-af38-4d47-9b66-7fa46d94dca7', '和秋遊洛陽', '和秋游洛陽', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["洛陽自古多才子，唯愛春風爛漫游。","今到白家詩句出，無人不詠洛陽秋。"]', '["洛陽自古多才子，唯愛春风爛漫游。","今到白家诗句出，無人不詠洛陽秋。"]', '诗', 'shi', '', NULL, '和秋遊洛陽 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('669c4f14-37d8-4a29-ab94-f560ae8cb25c', '和嘲春風', '和嘲春风', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["源上拂桃燒水發，江邊吹杏暗園開。","可憐半死龍門樹，懊惱春風作底來。"]', '["源上拂桃燒水發，江邊吹杏暗园开。","可怜半死龙门樹，懊惱春风作底来。"]', '诗', 'shi', '', NULL, '和嘲春風 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e952ab-2299-4e42-a5a8-2f82a8fca5ef', '侍郎宅泛池', '侍郎宅泛池', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["蓮子花邊回竹岸，雞頭葉上盪蘭舟。","誰知洛北朱門裏，便到江南綠水遊。"]', '["蓮子花邊回竹岸，雞头葉上盪蘭舟。","誰知洛北朱门裏，便到江南綠水游。"]', '诗', 'shi', '', NULL, '侍郎宅泛池 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8859a946-777d-439c-a1ac-3af35c59450d', '和侍郎邀宿不至', '和侍郎邀宿不至', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["蟾蜍有色門應鎖，街鼓無聲夜自深。","料得白家詩思苦，一篇詩了一彈琴。"]', '["蟾蜍有色门應鎖，街鼓無声夜自深。","料得白家诗思苦，一篇诗了一彈琴。"]', '诗', 'shi', '', NULL, '和侍郎邀宿不至 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ab9eb3-d689-4d66-b9fd-4208a17017c9', '自鄂渚至河南將歸江外留辭侍郎', '自鄂渚至河南將归江外留辞侍郎', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["一生所遇唯元白，天下無人重布衣。","欲別朱門淚先盡，白頭遊子白身歸。"]', '["一生所遇唯元白，天下無人重布衣。","欲別朱门泪先尽，白头游子白身归。"]', '诗', 'shi', '', NULL, '自鄂渚至河南將歸江外留辭侍郎 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d67b0d35-6222-4e56-8dae-63a60504b650', '蠻入西川後', '蠻入西川後', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["守隘一夫何處在，長橋萬里只堪傷。","紛紛塞外烏蠻賊，驅盡江頭濯錦娘。"]', '["守隘一夫何处在，长橋万里只堪傷。","紛紛塞外烏蠻賊，驱尽江头濯錦娘。"]', '诗', 'shi', '', NULL, '蠻入西川後 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277caaef-adac-43db-a554-c183d97cb795', '憶紫溪', '憶紫溪', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["長憶紫溪春欲盡，千巖交映水回斜。","巖空水滿溪自紫，水態更籠南燭花。"]', '["长憶紫溪春欲尽，千巖交映水回斜。","巖空水满溪自紫，水態更籠南燭花。"]', '诗', 'shi', '', NULL, '憶紫溪 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0426d884-3f0f-41ca-9b4f-7c7f4cf484fe', '誇紅槿', '誇紅槿', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["誰道槿花生感促，可憐相計半年紅。","何如桃李無多少，併打千枝一夜風。"]', '["誰道槿花生感促，可怜相計半年紅。","何如桃李無多少，併打千枝一夜风。"]', '诗', 'shi', '', NULL, '誇紅槿 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c2c891-798e-4c88-8fad-175f525eb389', '題縉雲山鼎池二首 一', '題縉云山鼎池二首 一', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["黃帝旌旗去不回，空餘片石碧崔嵬。","有時風卷鼎湖浪，散作晴天雨點來。"]', '["黄帝旌旗去不回，空餘片石碧崔嵬。","有时风卷鼎湖浪，散作晴天雨点来。"]', '诗', 'shi', '', NULL, '題縉雲山鼎池二首 一 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df8e3b6a-70d8-4df8-ad83-a44cc7c24069', '題縉雲山鼎池二首 二', '題縉云山鼎池二首 二', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["天地茫茫成古今，仙都凡有幾人尋。","到來唯見山高下，只是不知湖淺深。"]', '["天地茫茫成古今，仙都凡有幾人尋。","到来唯见山高下，只是不知湖淺深。"]', '诗', 'shi', '', NULL, '題縉雲山鼎池二首 二 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d73b24b-e146-42ff-b054-a36690c29a0c', '宿冽上人房', '宿冽上人房', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["浮生不定若蓬飄，林下真僧偶見招。","覺後始知身是夢，更聞寒雨滴芭蕉。"]', '["浮生不定若蓬飄，林下真僧偶见招。","覺後始知身是梦，更闻寒雨滴芭蕉。"]', '诗', 'shi', '', NULL, '宿冽上人房 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dfd661e-00e1-4cef-b3bc-923559cf6c66', '汴河覽古', '汴河覽古', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["煬帝龍舟向此行，三千宮女采橈輕。","渡河不似如今唱，爲是楊家怨思聲。"]', '["煬帝龙舟向此行，三千宮女采橈轻。","渡河不似如今唱，爲是楊家怨思声。"]', '诗', 'shi', '', NULL, '汴河覽古 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da1fa92-587f-4cf1-aecb-efe1ed5b1dff', '柬白丈人', '柬白丈人', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["昔時丈人鬢髮白，千年松下鋤茯苓。","今來見此松樹死，丈人斬新鬢髮青。"]', '["昔时丈人鬢髮白，千年松下鋤茯苓。","今来见此松樹死，丈人斬新鬢髮青。"]', '诗', 'shi', '', NULL, '柬白丈人 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c56b37d-8d80-45f4-a649-0ae760b624cf', '覽鏡詞', '覽镜词', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["寶鏡磨來寒水清，青衣把就綠窗明。","潘郎懊惱新秋髮，拔却一莖生兩莖。"]', '["寶镜磨来寒水清，青衣把就綠窗明。","潘郎懊惱新秋髮，拔却一莖生兩莖。"]', '诗', 'shi', '', NULL, '覽鏡詞 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16da5308-d23a-40e5-8ac8-c8d2ac0fdb80', '寄玄陽先生', '寄玄陽先生', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["不能相見見人傳，{山瞿}岸山中岱岸邊。","顏貌只如三二十，道年三百亦藏年。"]', '["不能相见见人傳，{山瞿}岸山中岱岸邊。","顏貌只如三二十，道年三百亦藏年。"]', '诗', 'shi', '', NULL, '寄玄陽先生 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5bb6dd4-c1d1-4aad-8b69-c2dfc3fa774f', '白人', '白人', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["煖風入煙花漠漠，白人梳洗尋常薄。","泥郎爲插瓏璁釵，爭教一朵牙雲落。"]', '["煖风入煙花漠漠，白人梳洗尋常薄。","泥郎爲插瓏璁釵，爭教一朵牙云落。"]', '诗', 'shi', '', NULL, '白人 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('234a70e6-2a97-4e0d-95e8-ef22717d66dd', '奉酬元相公上元', '奉酬元相公上元', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["出擁樓船千萬人，入爲台輔九霄身。","如何更羨看燈夜，曾見宮花拂面春。"]', '["出擁楼船千万人，入爲台輔九霄身。","如何更羨看灯夜，曾见宮花拂面春。"]', '诗', 'shi', '', NULL, '奉酬元相公上元 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf3eb3d-1190-4660-86e7-590795636a93', '奉和鸚鵡', '奉和鸚鵡', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["毛羽曾經翦處殘，學人言語道暄寒。","任饒長被金籠闔，也免栖飛雨雪難。"]', '["毛羽曾經翦处殘，学人言語道暄寒。","任饒长被金籠闔，也免栖飞雨雪难。"]', '诗', 'shi', '', NULL, '奉和鸚鵡 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecbc2667-468b-4189-9f75-5f622d8ebb73', '將至妙喜寺', '將至妙喜寺', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["清風嫋嫋越水陂，遠樹蒼蒼妙喜寺。","自有車輪與馬蹄，未曾到此波心地。"]', '["清风嫋嫋越水陂，远樹蒼蒼妙喜寺。","自有车輪與马蹄，未曾到此波心地。"]', '诗', 'shi', '', NULL, '將至妙喜寺 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c8d2d77-b702-4179-bcdc-1245c3be8b00', '紅蕉', '紅蕉', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["紅蕉曾到嶺南看，校小芭蕉幾一般。","差是斜刀翦紅絹，卷來開去葉中安。"]', '["紅蕉曾到嶺南看，校小芭蕉幾一般。","差是斜刀翦紅絹，卷来开去葉中安。"]', '诗', 'shi', '', NULL, '紅蕉 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('603f9c15-b1eb-48c0-b0e2-f04a2b1ca3ff', '見少室', '见少室', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["適我一簞孤客性，問人三十六峰名。","青雲無忘白雲在，便可嵩陽老此生。"]', '["適我一簞孤客性，问人三十六峰名。","青云無忘白云在，便可嵩陽老此生。"]', '诗', 'shi', '', NULL, '見少室 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad1855d5-fe8f-4ff7-980c-4e0cfe1e9424', '語兒見新月', '語兒见新月', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["幾處天邊見新月，經過草市憶西施。","娟娟水宿初三夜，曾伴愁蛾到語兒。"]', '["幾处天邊见新月，經過草市憶西施。","娟娟水宿初三夜，曾伴愁蛾到語兒。"]', '诗', 'shi', '', NULL, '語兒見新月 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ef4711a-4f03-4edb-abbd-0ce9534db931', '回施先輩見寄新詩二首 一', '回施先輩见寄新诗二首 一', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["九幽仙子西山卷，讀了絛繩繫又開。","此卷玉清宮裏少，曾尋真誥讀詩來。"]', '["九幽仙子西山卷，读了絛繩繫又开。","此卷玉清宮裏少，曾尋真誥读诗来。"]', '诗', 'shi', '', NULL, '回施先輩見寄新詩二首 一 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402fc29f-0cf9-43b2-8d03-7961e8327110', '回施先輩見寄新詩二首 二', '回施先輩见寄新诗二首 二', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["紫河車裏丹成也，皁莢枝頭早晚飛。","料得仙宮列仙[籍]，如君進士出身稀。"]', '["紫河车裏丹成也，皁莢枝头早晚飞。","料得仙宮列仙[籍]，如君進士出身稀。"]', '诗', 'shi', '', NULL, '回施先輩見寄新詩二首 二 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c2fa43-3722-428f-a7ac-0ac960801c08', '送沈亞之赴郢掾', '送沈亞之赴郢掾', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["千萬乘驄沈司戶，不須惆悵郢中遊。","幾年白雪無人唱，今日唯君上雪樓。"]', '["千万乘驄沈司戶，不須惆悵郢中游。","幾年白雪無人唱，今日唯君上雪楼。"]', '诗', 'shi', '', NULL, '送沈亞之赴郢掾 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('824804d2-ec32-44ac-9f21-94dcbdb6023b', '答白公', '答白公', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["高景爭來草木頭，一生心事酒前休。","山公自是仙人侶，攜手醉登城上樓。"]', '["高景爭来草木头，一生心事酒前休。","山公自是仙人侶，携手醉登城上楼。"]', '诗', 'shi', '', NULL, '答白公 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a91e04b7-d45c-4a8c-9305-6ddb40a840eb', '句', '句', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["青山舊路在，白首醉還鄉。","試到第三橋，便入千頃花。","亂後見淮水，歸心忽迢遙。","乍疑鯨噴浪，忽似鷁凌風。","呀呷汀洲動，喧闐里巷空。"]', '["青山旧路在，白首醉還乡。","試到第三橋，便入千頃花。","亂後见淮水，归心忽迢遙。","乍疑鯨噴浪，忽似鷁凌风。","呀呷汀洲动，喧闐里巷空。"]', '诗', 'shi', '', NULL, '句 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7484e6e-8708-4236-824f-717093e5f953', '奉和聖製南郊禮畢詩', '奉和聖製南郊禮畢诗', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["磬管歌大呂，冕裘旅天神。","燒蕭闢閶闔，祈穀爲蒸人。","羽旗灑輕雪，麥隴含陽春。","昌運歲今會，王猷從此新。","三臣皆就日，萬國望如雲。","仁壽信非遠，羣生方在鈞。"]', '["磬管歌大呂，冕裘旅天神。","燒蕭闢閶闔，祈穀爲蒸人。","羽旗灑轻雪，麦隴含陽春。","昌運歲今會，王猷從此新。","三臣皆就日，万国望如云。","仁壽信非远，羣生方在鈞。"]', '诗', 'shi', '', NULL, '奉和聖製南郊禮畢詩 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac67f4d-49cf-4ccc-9bfe-d34d96095800', '郊壇回輿中書二相公蒙聖慈召至御馬前仰感恩遇輒書是詩兼呈二相公', '郊壇回輿中书二相公蒙聖慈召至御马前仰感恩遇輒书是诗兼呈二相公', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["七萃和鑾動，三條葆吹回。","相星環日道，蒼馬近龍媒。","咫尺天顏接，光華喜氣來。","自慙衰且病，無以效涓埃。"]', '["七萃和鑾动，三條葆吹回。","相星环日道，蒼马近龙媒。","咫尺天顏接，光华喜氣来。","自慙衰且病，無以效涓埃。"]', '诗', 'shi', '', NULL, '郊壇回輿中書二相公蒙聖慈召至御馬前仰感恩遇輒書是詩兼呈二相公 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14fc8546-d18f-401c-833d-39f1a9943348', '寒食日三殿侍宴奉進詩一首', '寒食日三殿侍宴奉進诗一首', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["宛轉龍歌節，參差燕羽高。","風光搖禁柳，霽色暖宮桃。","春露明仙掌，晨霞照御袍。","雪凝陳組練，林植聳干旄。","廣樂初蹌鳳，神山欲抃鼇。","鳴笳朱鷺起，疊鼓紫騂豪。","象舞嚴金鎧，豐歌耀寶刀。","不勞孫子法，自得太公韜。","分席羅玄冕，行觴舉綠醪。","彀中時落羽，橦末乍升猱。","瑞景開陰翳，薰風散鬱陶。","天顏歡益醉，臣節勁尤高。","楛矢方來貢，雕弓已載櫜。","英威揚絕漠，神算盡臨洮。","赤縣陽和布，蒼生雨露膏。","野平惟有麥，田闢久無蒿。","祿秩榮三事，功勳乏一毫。","寢謀慙汲黯，秉羽貴孫敖。","煥若遊玄圃，歡如享太牢。","輕生何以報，祗自比鴻毛。"]', '["宛轉龙歌節，參差燕羽高。","风光搖禁柳，霽色暖宮桃。","春露明仙掌，晨霞照御袍。","雪凝陳組練，林植聳干旄。","廣乐初蹌鳳，神山欲抃鼇。","鳴笳朱鷺起，叠鼓紫騂豪。","象舞嚴金鎧，豐歌耀寶刀。","不勞孫子法，自得太公韜。","分席羅玄冕，行觴舉綠醪。","彀中时落羽，橦末乍升猱。","瑞景开陰翳，薰风散鬱陶。","天顏歡益醉，臣節勁尤高。","楛矢方来貢，雕弓已載櫜。","英威揚絕漠，神算尽臨洮。","赤縣陽和布，蒼生雨露膏。","野平惟有麦，田闢久無蒿。","祿秩榮三事，功勳乏一毫。","寢謀慙汲黯，秉羽貴孫敖。","煥若游玄圃，歡如享太牢。","轻生何以報，祗自比鴻毛。"]', '诗', 'shi', '', NULL, '寒食日三殿侍宴奉進詩一首 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c3ce12a-2949-4b1a-b272-a128db95d641', '雨中自秘書省訪王三侍御知早入朝便入集賢侍御任集賢校書及升柏臺又與秘閣相對同院張學士亦余特厚故以詩贈之', '雨中自秘书省訪王三侍御知早入朝便入集賢侍御任集賢校书及升柏台又與秘閣相对同院張学士亦余特厚故以诗贈之', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["共憐獨鶴青霞姿，瀛洲故山歸已遲。","仁者焉能效鷙鶚，飛舞自合追長離。","梧桐迥齊鳷鵲觀，煙雨屢拂蛟龍旗。","鴻鴈衝颷去不盡，寒聲晚下天泉池。","顧我蓬萊靜無事，玉版寶書藏衆瑞。","青編盡以汲冢來，科斗皆從魯室至。","金門待詔何逍遙，名儒早問張子僑。","王褒軼材晚始入，宮女已能傳洞簫。","應令栢臺長對戶，別來相望獨寥寥。"]', '["共怜独鹤青霞姿，瀛洲故山归已遲。","仁者焉能效鷙鶚，飞舞自合追长離。","梧桐迥齊鳷鵲观，煙雨屢拂蛟龙旗。","鴻鴈衝颷去不尽，寒声晚下天泉池。","顧我蓬萊静無事，玉版寶书藏衆瑞。","青編尽以汲冢来，科斗皆從魯室至。","金门待詔何逍遙，名儒早问張子僑。","王褒軼材晚始入，宮女已能傳洞簫。","應令栢台长对戶，別来相望独寥寥。"]', '诗', 'shi', '', NULL, '雨中自秘書省訪王三侍御知早入朝便入集賢侍御任集賢校書及升柏臺又與秘閣相對同院張學士亦余特厚故以詩贈之 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d00f372a-c0a8-400f-b0a5-31ec29404d91', '奉和太原張尚書山亭書懷', '奉和太原張尚书山亭书懷', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["巖石在朱戶，風泉當翠樓。","始知峴亭賞，難與清暉留。","餘景淡將夕，凝嵐輕欲收。","東山有歸志，方接赤松遊。"]', '["巖石在朱戶，风泉當翠楼。","始知峴亭賞，难與清暉留。","餘景淡將夕，凝嵐轻欲收。","东山有归志，方接赤松游。"]', '诗', 'shi', '', NULL, '奉和太原張尚書山亭書懷 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f835c483-7870-4846-b4c7-138ec4af57d1', '奉和韋侍御陪相公遊開義五言六韻', '奉和韋侍御陪相公游开義五言六韻', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["羊公追勝概，茲地暫逍遙。","風景同南峴，丹青見北朝。","石渠清夏氣，高樹激鮮飆。","念法珍禽集，聞輕醉象調。","偶分甘露味，偏覺衆香饒。","爲問毘城內，餘薰幾日銷。"]', '["羊公追勝概，茲地暫逍遙。","风景同南峴，丹青见北朝。","石渠清夏氣，高樹激鲜飆。","念法珍禽集，闻轻醉象調。","偶分甘露味，偏覺衆香饒。","爲问毘城內，餘薰幾日銷。"]', '诗', 'shi', '', NULL, '奉和韋侍御陪相公遊開義五言六韻 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7bd2528-bf9f-42c9-b2c8-ffc62fbb28b1', '贈圓明上人', '贈圓明上人', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["遠公說易長松下，龍樹雙輕海藏中。","今日導師聞佛慧，始知前路化成空。"]', '["远公说易长松下，龙樹雙轻海藏中。","今日導師闻佛慧，始知前路化成空。"]', '诗', 'shi', '', NULL, '贈圓明上人 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be95130-83a9-468e-8ae0-358cacda75c7', '贈奉律上人', '贈奉律上人', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["知君學地厭多聞，廣渡羣生出世氛。","飯色不應殊寶器，樹香皆遣入禪薰。"]', '["知君学地厭多闻，廣渡羣生出世氛。","飯色不應殊寶器，樹香皆遣入禪薰。"]', '诗', 'shi', '', NULL, '贈奉律上人 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b226b9c-55ba-4bac-ba7c-cd98fea6401e', '戲贈慎微寺主道安上座三僧正', '戲贈慎微寺主道安上座三僧正', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["甘露灑空惟一味，旃檀移植自成薰。","遙知暢獻分南北，應用調柔致六羣。"]', '["甘露灑空惟一味，旃檀移植自成薰。","遙知暢獻分南北，應用調柔致六羣。"]', '诗', 'shi', '', NULL, '戲贈慎微寺主道安上座三僧正 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0bfe51e-dd19-4028-adb7-fc4cf72a6c51', '長安秋夜', '长安秋夜', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["內宮傳詔問戎機，載筆金鑾夜始歸。","萬戶千門皆寂寂，月中清露點朝衣。"]', '["內宮傳詔问戎機，載笔金鑾夜始归。","万戶千门皆寂寂，月中清露点朝衣。"]', '诗', 'shi', '', NULL, '長安秋夜 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec5456d-2dea-4968-9411-4c27429e5126', '清冷池懷古', '清冷池懷古', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["區囿三百里，常聞駟馬來。","旌旗朝甬道，簫鼓燕平臺。","追昔賦文雅，從容遊上才。","竹園秋水淨，風苑雪煙開。","牛禍釁將發，羊孫謀始回。","袁絲徒伏劒，長孺欲成灰。","興廢由所感，湮淪斯可哀。","空留故池鴈，刷羽尚徘徊。"]', '["區囿三百里，常闻駟马来。","旌旗朝甬道，簫鼓燕平台。","追昔賦文雅，從容游上才。","竹园秋水淨，风苑雪煙开。","牛禍釁將發，羊孫謀始回。","袁絲徒伏劒，长孺欲成灰。","兴廢由所感，湮淪斯可哀。","空留故池鴈，刷羽尚徘徊。"]', '诗', 'shi', '', NULL, '清冷池懷古 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b41c002-e220-45f6-b816-c8f499e39622', '述夢詩四十韻', '述梦诗四十韻', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["賦命誠非薄，良時幸已遭。","君當堯舜日，官接鳳皇曹。","目睇煙霄闊，心驚羽翼高。","椅梧連鶴禁，壀堄接龍韜。","我后憐詞客，吾僚並雋髦。","著書同陸賈，待詔比王褒。","重價連懸璧，英詞淬寶刀。","泉流初落澗，露滴更濡毫。","赤豹欣來獻，彤弓喜暫櫜非煙含瑞氣，馴雉潔霜毛。","靜室便幽獨，虛樓散鬱陶。","花光晨豔豔，松韻晚騷騷。","畫壁看飛鶴，仙圖見巨鼇。","倚簷陰藥樹，落格蔓蒲桃。","荷靜蓬池鱠，冰寒郢水醪。","荔枝來自遠，盧橘賜仍叨。","麝氣隨蘭澤，霜華入杏膏。","恩光惟覺重，攜挈未爲勞。","夕閱梨園騎，宵聞禁杖獒。","扇回交彩翟，鵰起颺銀絛。","轡待袁絲攬，書期蜀客操。","盡規常謇謇，退食尚忉忉。","龜顧垂金鈕，鸞飛曳錦袍。","御溝楊柳弱，天廐驌驦豪。","屢換青春直，閑隨上苑遨。","煙低行殿竹，風拆繞牆桃。","聚散俄成昔，悲愁益自熬。","每懷仙駕遠，更望茂陵號。","地接三茅嶺，川迎伍子濤。","花迷瓜步暗，石固蒜山牢。","蘭野凝香管，梅洲動翠篙。","泉魚驚綵妓，溪鳥避干旄。","感舊心猶絕，思歸首更搔。","無聊燃[蜜]炬，誰復勸金舠。","嵐氣朝生棟，城陰夜入濠。","望煙歸海嶠，送鴈渡江臯。","宛馬嘶寒櫪，吳鉤在錦弢。","未能追狡兔，空覺長黃蒿。","水國逾千里，風帆過萬艘。","閱川終古恨，惟見暮滔滔。"]', '["賦命誠非薄，良时幸已遭。","君當堯舜日，官接鳳皇曹。","目睇煙霄闊，心驚羽翼高。","椅梧連鹤禁，壀堄接龙韜。","我后怜词客，吾僚並雋髦。","著书同陸賈，待詔比王褒。","重價連懸璧，英词淬寶刀。","泉流初落澗，露滴更濡毫。","赤豹欣来獻，彤弓喜暫櫜非煙含瑞氣，馴雉潔霜毛。","静室便幽独，虛楼散鬱陶。","花光晨豔豔，松韻晚騷騷。","畫壁看飞鹤，仙圖见巨鼇。","倚簷陰藥樹，落格蔓蒲桃。","荷静蓬池鱠，冰寒郢水醪。","荔枝来自远，盧橘賜仍叨。","麝氣隨蘭澤，霜华入杏膏。","恩光惟覺重，携挈未爲勞。","夕閱梨园騎，宵闻禁杖獒。","扇回交彩翟，鵰起颺銀絛。","轡待袁絲攬，书期蜀客操。","尽規常謇謇，退食尚忉忉。","龟顧垂金鈕，鸾飞曳錦袍。","御溝楊柳弱，天廐驌驦豪。","屢換青春直，闲隨上苑遨。","煙低行殿竹，风拆繞牆桃。","聚散俄成昔，悲愁益自熬。","每懷仙駕远，更望茂陵號。","地接三茅嶺，川迎伍子濤。","花迷瓜步暗，石固蒜山牢。","蘭野凝香管，梅洲动翠篙。","泉鱼驚綵妓，溪鸟避干旄。","感旧心猶絕，思归首更搔。","無聊燃[蜜]炬，誰复勸金舠。","嵐氣朝生棟，城陰夜入濠。","望煙归海嶠，送鴈渡江臯。","宛马嘶寒櫪，吳鉤在錦弢。","未能追狡兔，空覺长黄蒿。","水国逾千里，风帆過万艘。","閱川終古恨，惟见暮滔滔。"]', '诗', 'shi', '', NULL, '述夢詩四十韻 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3433fb-a4d9-4cf4-b96c-ba047505806c', '招隱山觀玉蘂樹戲書即事奉寄江西沈大夫閣老', '招隐山观玉蘂樹戲书即事奉寄江西沈大夫閣老', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["玉蘂天中樹，金閨昔共窺。","落英閑舞雪，密葉乍低帷舊賞煙霄遠，前歡歲月移。","今來想顏色，還似憶瓊枝。"]', '["玉蘂天中樹，金閨昔共窺。","落英闲舞雪，密葉乍低帷旧賞煙霄远，前歡歲月移。","今来想顏色，還似憶瓊枝。"]', '诗', 'shi', '', NULL, '招隱山觀玉蘂樹戲書即事奉寄江西沈大夫閣老 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5fa2d70-5a7a-453f-9edf-b05b686c70de', '寄題惠林李侍郎舊館', '寄題惠林李侍郎旧館', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["棟宇非吾室，煙山是我鄰。","百齡惟待盡，一世樂長貧。","半壁懸秋日，空林滿夕塵。","祗應雙鶴弔，松路更無人。"]', '["棟宇非吾室，煙山是我鄰。","百齡惟待尽，一世乐长貧。","半壁懸秋日，空林满夕塵。","祗應雙鹤弔，松路更無人。"]', '诗', 'shi', '', NULL, '寄題惠林李侍郎舊館 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27bf86f8-7963-49d9-ac77-d2b4eee63446', '寄茅山孫鍊師', '寄茅山孫鍊師', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["何地最翛然，華陽第八天。","松風清有露，蘿月淨無煙。","乍警瑤壇鶴，時嘶玉樹蟬。","欲馳千里戀，惟有鳳門泉。"]', '["何地最翛然，华陽第八天。","松风清有露，蘿月淨無煙。","乍警瑤壇鹤，时嘶玉樹蟬。","欲驰千里戀，惟有鳳门泉。"]', '诗', 'shi', '', NULL, '寄茅山孫鍊師 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1775f8d0-16e3-4beb-841a-385547a9666b', '又二絕 一', '又二絕 一', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["石上谿蓀發紫茸，碧山幽藹水溶溶。","菖花定是無人見，春日惟應羽客逢。"]', '["石上谿蓀發紫茸，碧山幽藹水溶溶。","菖花定是無人见，春日惟應羽客逢。"]', '诗', 'shi', '', NULL, '又二絕 一 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fca3e65-4f5f-4e3f-a169-28c74a442701', '又二絕 二', '又二絕 二', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["獨尋蘭渚翫遲暉，閑倚松窗望翠微。","遙想春山明月曙，玉壇清磬步虛歸。"]', '["独尋蘭渚翫遲暉，闲倚松窗望翠微。","遙想春山明月曙，玉壇清磬步虛归。"]', '诗', 'shi', '', NULL, '又二絕 二 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e289d837-64ea-4881-9667-fca32ca4a161', '題奇石', '題奇石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["蘊玉抱清輝，閑庭日瀟灑。","塊然天地間，自是孤生者。"]', '["蘊玉抱清輝，闲庭日瀟灑。","塊然天地间，自是孤生者。"]', '诗', 'shi', '', NULL, '題奇石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6a6ad0f-3a83-4774-a906-ebb43f7ac5cf', '送張中丞入臺從事', '送張中丞入台從事', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["驛騎朝天去，江城睠闕深。","夜珠先去握，芳桂乍辭陰。","澤國三千里，羈孤萬感心。","自嗟文廢久，此曲爲盧諶。"]', '["驛騎朝天去，江城睠闕深。","夜珠先去握，芳桂乍辞陰。","澤国三千里，羈孤万感心。","自嗟文廢久，此曲爲盧諶。"]', '诗', 'shi', '', NULL, '送張中丞入臺從事 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4531cf45-2116-4c73-8bae-16f6413418d7', '懷京國', '懷京国', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["海上東風犯雪來，臘前先折鏡湖梅。","遙思禁苑青春夜，坐待宮人畫詔迴。"]', '["海上东风犯雪来，臘前先折镜湖梅。","遙思禁苑青春夜，坐待宮人畫詔迴。"]', '诗', 'shi', '', NULL, '懷京國 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70faba81-1c92-4ffc-84bc-f354c0326aff', '追和太師顏公同清遠道士遊虎丘寺', '追和太師顏公同清远道士游虎丘寺', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["茂苑有靈峰，嗟余未遊觀。","藏山半平陸，壞谷爲高岸。","岡繞數仞牆，巖潛千丈幹。","乃知造化意，回斡資奇玩。","鏐騰昔虎踞，劒沒嘗龍煥。","潭黛入海底，崟岑聳霄半。","層巒未升日，哀狖寧知旦。","綠篠夏凝陰，碧林秋不換。","冥搜既窈窕，回望何蕭散。","川晴嵐氣收，江春雜英亂。","逸人綴清藻，前哲留篇翰。","共扣哀玉音，皆舒文繡段。","難追彥回賞，徒起興公歎。","一夕如再升，含毫星斗爛。"]', '["茂苑有靈峰，嗟余未游观。","藏山半平陸，壞谷爲高岸。","岡繞數仞牆，巖潛千丈幹。","乃知造化意，回斡資奇玩。","鏐腾昔虎踞，劒沒嘗龙煥。","潭黛入海底，崟岑聳霄半。","層巒未升日，哀狖寧知旦。","綠篠夏凝陰，碧林秋不換。","冥搜既窈窕，回望何蕭散。","川晴嵐氣收，江春杂英亂。","逸人綴清藻，前哲留篇翰。","共扣哀玉音，皆舒文繡段。","难追彥回賞，徒起兴公歎。","一夕如再升，含毫星斗爛。"]', '诗', 'shi', '', NULL, '追和太師顏公同清遠道士遊虎丘寺 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00eca35e-b0b6-432a-a14e-2d28ca08e3ca', '東郡懷古二首 王京兆', '东郡懷古二首 王京兆', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["河水昔將決，衝波溢川潯。","崢嶸金堤下，噴薄風雷音。","投馬災未弭，爲魚歎方深。","惟公執珪璧，誓與身俱沈。","誠信不虛發，神明宜爾臨。","湍流自此回，咫尺焉能侵。","逮我守東郡，悽然懷所欽。","雖非識君面，自謂知君心。","意氣苟相合，神明無古今。","登城見遺廟，日夕空悲吟。"]', '["河水昔將決，衝波溢川潯。","崢嶸金堤下，噴薄风雷音。","投马災未弭，爲鱼歎方深。","惟公執珪璧，誓與身俱沈。","誠信不虛發，神明宜爾臨。","湍流自此回，咫尺焉能侵。","逮我守东郡，悽然懷所欽。","雖非識君面，自謂知君心。","意氣苟相合，神明無古今。","登城见遺廟，日夕空悲吟。"]', '诗', 'shi', '', NULL, '東郡懷古二首 王京兆 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3870f0a-f269-4fe8-a0ce-ea9f78147651', '東郡懷古二首 陽給事', '东郡懷古二首 陽給事', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["宋氏遠家左，豺狼滿中州。","陽君守滑臺，終古垂英猷。","數仞城既毀，萬夫心莫留。","跳身入飛鏃，免胄臨霜矛。","畢命在旗下，僵尸橫道周。","義風激河汴，壯氣淪山丘。","嗟爾抱忠烈，古來誰與儔。","就烹感漢使，握節悲陽秋。","顏子綴清藻，鏗然如素璆。","徘徊望故壘，尚想精魂遊。"]', '["宋氏远家左，豺狼满中州。","陽君守滑台，終古垂英猷。","數仞城既毀，万夫心莫留。","跳身入飞鏃，免胄臨霜矛。","畢命在旗下，僵尸橫道周。","義风激河汴，壯氣淪山丘。","嗟爾抱忠烈，古来誰與儔。","就烹感漢使，握節悲陽秋。","顏子綴清藻，鏗然如素璆。","徘徊望故壘，尚想精魂游。"]', '诗', 'shi', '', NULL, '東郡懷古二首 陽給事 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd6914d-7644-4e9e-b758-09def40c83c0', '秋日登郡樓望贊皇山感而成詠', '秋日登郡楼望贊皇山感而成詠', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔人懷井邑，爲有挂冠期。","顧我飄蓬者，長隨泛梗移。","越吟因病感，潘鬢入秋悲。","北指邯鄲道，應無歸去期。"]', '["昔人懷井邑，爲有挂冠期。","顧我飄蓬者，长隨泛梗移。","越吟因病感，潘鬢入秋悲。","北指邯鄲道，應無归去期。"]', '诗', 'shi', '', NULL, '秋日登郡樓望贊皇山感而成詠 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e8e68b8-2bc4-4ec7-aa42-bb030326e72a', '雨後淨望河西連山愴然成詠', '雨後淨望河西連山愴然成詠', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["宿雨初收晚吹繁，秋光極目自銷魂。","煙山北下歸遼海，鴻鴈南飛出薊門。","只恨無功書史籍，豈悲臨老事戎軒。","唯懷藥餌蠲衰病，爲惜餘年報主恩。"]', '["宿雨初收晚吹繁，秋光極目自銷魂。","煙山北下归遼海，鴻鴈南飞出薊门。","只恨無功书史籍，豈悲臨老事戎軒。","唯懷藥餌蠲衰病，爲惜餘年報主恩。"]', '诗', 'shi', '', NULL, '雨後淨望河西連山愴然成詠 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3af5d50-130f-4e9d-89ef-4538f1ac3fce', '秋日美晴郡樓閑眺寄荆南張書記', '秋日美晴郡楼闲眺寄荆南張书記', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["高檻涼風起，清川旭景開。","秋聲向野去，爽氣自山來。","霄外鴻初返，簷間燕已歸。","不因煙雨夕，何處夢陽臺。"]', '["高檻涼风起，清川旭景开。","秋声向野去，爽氣自山来。","霄外鴻初返，簷间燕已归。","不因煙雨夕，何处梦陽台。"]', '诗', 'shi', '', NULL, '秋日美晴郡樓閑眺寄荆南張書記 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f8f27c5-2e3f-42e7-8238-4be04f1e2849', '故人寄茶', '故人寄茶', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["劒外九華英，緘題下玉京。","開時微月上，碾處亂泉聲。","半夜邀僧至，孤吟對竹烹。","碧流霞脚碎，香泛乳花輕。","六腑睡神去，數朝詩思清。","其餘不敢費，留伴讀書行。"]', '["劒外九华英，緘題下玉京。","开时微月上，碾处亂泉声。","半夜邀僧至，孤吟对竹烹。","碧流霞脚碎，香泛乳花轻。","六腑睡神去，數朝诗思清。","其餘不敢費，留伴读书行。"]', '诗', 'shi', '', NULL, '故人寄茶 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2effbb1c-0785-47f0-8440-43e4c1c893ec', '奉送相公十八丈鎮楊州', '奉送相公十八丈鎮楊州', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["千騎風生大斾舒，春江重到武侯廬。","共懸龜印銜新綬，同憶鱣庭訪舊居。","取履橋邊啼鳥換，釣璜溪畔落花初。","今來却笑臨邛客，入蜀空馳使者車。"]', '["千騎风生大斾舒，春江重到武侯廬。","共懸龟印銜新綬，同憶鱣庭訪旧居。","取履橋邊啼鸟換，釣璜溪畔落花初。","今来却笑臨邛客，入蜀空驰使者车。"]', '诗', 'shi', '', NULL, '奉送相公十八丈鎮楊州 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b129f88c-34e3-4845-83ab-f077c4adc4c9', '題劒門', '題劒门', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["奇峰百仞懸，清眺出嵐煙。","迥若戈回日，高疑劒倚天。","參差霞壁聳，合沓翠屏連。","想是三刀夢，森然在目前。"]', '["奇峰百仞懸，清眺出嵐煙。","迥若戈回日，高疑劒倚天。","參差霞壁聳，合沓翠屏連。","想是三刀梦，森然在目前。"]', '诗', 'shi', '', NULL, '題劒門 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e4aa0f-aba7-4024-a349-3c9fb23be270', '漢州月夕遊房太尉西湖', '漢州月夕游房太尉西湖', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["丞相鳴琴地，何年閉玉徽。","偶因明月夕，重敞故樓扉。","桃柳谿空在，芙蓉客暫依。","誰憐濟川楫，長與夜舟歸。"]', '["丞相鳴琴地，何年閉玉徽。","偶因明月夕，重敞故楼扉。","桃柳谿空在，芙蓉客暫依。","誰怜濟川楫，长與夜舟归。"]', '诗', 'shi', '', NULL, '漢州月夕遊房太尉西湖 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b63a96f9-e226-4ef7-a0fb-6970d0f8465e', '重題', '重題', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["晚日臨寒渚，微風發櫂謳。","鳳池波自闊，魚水運難留。","亭古思宏棟，川長憶夜舟。","想公高世志，祗似冶城遊。"]', '["晚日臨寒渚，微风發櫂謳。","鳳池波自闊，鱼水運难留。","亭古思宏棟，川长憶夜舟。","想公高世志，祗似冶城游。"]', '诗', 'shi', '', NULL, '重題 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82225630-b128-444f-a56e-021b35ba050b', '房公舊竹亭聞琴緬慕風流神期如在因重題此作', '房公旧竹亭闻琴緬慕风流神期如在因重題此作', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["流水音長在，青霞意不傳。","獨悲形解後，誰聽廣陵絃。"]', '["流水音长在，青霞意不傳。","独悲形解後，誰听廣陵絃。"]', '诗', 'shi', '', NULL, '房公舊竹亭聞琴緬慕風流神期如在因重題此作 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd93e8a-ad8d-43d9-8d71-72e69c5ba79f', '憶金門舊遊奉寄江西沈大夫', '憶金门旧游奉寄江西沈大夫', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["東望滄溟路幾重，無因白首更相逢。","已悲泉下雙琪樹，又惜天邊一臥龍。","人事升沉纔十載，宦遊漂泊過千峰。","思君遠寄西山藥，歲暮相期向赤松。"]', '["东望滄溟路幾重，無因白首更相逢。","已悲泉下雙琪樹，又惜天邊一臥龙。","人事升沉纔十載，宦游漂泊過千峰。","思君远寄西山藥，歲暮相期向赤松。"]', '诗', 'shi', '', NULL, '憶金門舊遊奉寄江西沈大夫 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd1eeef-5e4d-4e80-ba8b-06786ca97c70', '早入中書行公主冊禮事畢登集賢閣成詠', '早入中书行公主冊禮事畢登集賢閣成詠', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["明星入東陌，燦燦光層宙。","皎月映高梧，輕風發涼候。","金門列葆吹，鐘室傳清漏。","簡冊自中來，貂黃忝宣授。","更登天祿閣，極眺終南岫。","遙羨商山翁，閑歌紫芝秀。","晨興念始辱，夕惕思致寇。","傾奪非我心，悽然感田竇。"]', '["明星入东陌，燦燦光層宙。","皎月映高梧，轻风發涼候。","金门列葆吹，鐘室傳清漏。","簡冊自中来，貂黄忝宣授。","更登天祿閣，極眺終南岫。","遙羨商山翁，闲歌紫芝秀。","晨兴念始辱，夕惕思致寇。","傾奪非我心，悽然感田竇。"]', '诗', 'shi', '', NULL, '早入中書行公主冊禮事畢登集賢閣成詠 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013c9243-bd61-42c8-afd4-9261db7c74e2', '題羅浮石', '題羅浮石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["清景持芳菊，涼天倚茂松。","名山何必去，此地有羣峰。"]', '["清景持芳菊，涼天倚茂松。","名山何必去，此地有羣峰。"]', '诗', 'shi', '', NULL, '題羅浮石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('affd9d6b-278c-485c-9181-02c1e7501a3f', '重過列子廟追感頃年自淮服與居守王僕射同題名於廟壁僕射已爲御史余尚布衣自後俱列紫垣繼遊內署兩爲夏官之代復聯左揆之榮荷寵多同感涕何極因書四韻奉寄', '重過列子廟追感頃年自淮服與居守王僕射同題名於廟壁僕射已爲御史余尚布衣自後俱列紫垣繼游內署兩爲夏官之代复聯左揆之榮荷寵多同感涕何極因书四韻奉寄', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["白首過遺廟，朱輪入故城。","已慚聯左揆，猶喜抗前旌。","曳履忘年舊，彈冠久要情。","重看題壁處，豈羨棄繻生。"]', '["白首過遺廟，朱輪入故城。","已慚聯左揆，猶喜抗前旌。","曳履忘年旧，彈冠久要情。","重看題壁处，豈羨棄繻生。"]', '诗', 'shi', '', NULL, '重過列子廟追感頃年自淮服與居守王僕射同題名於廟壁僕射已爲御史余尚布衣自後俱列紫垣繼遊內署兩爲夏官之代復聯左揆之榮荷寵多同感涕何極因書四韻奉寄 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fd2e15e-24c5-47bd-83a4-4e3fe7384ddd', '遙傷茅山縣孫尊師三首 一', '遙傷茅山縣孫尊師三首 一', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["蟬蛻遺虛白，蜺飛入上清。","同人悲劒解，舊友覺衣輕。","黃鵠遙將舉，斑麟儼未行。","惟應鮑靚室，中夜識琴聲。"]', '["蟬蛻遺虛白，蜺飞入上清。","同人悲劒解，旧友覺衣轻。","黄鵠遙將舉，斑麟儼未行。","惟應鲍靚室，中夜識琴声。"]', '诗', 'shi', '', NULL, '遙傷茅山縣孫尊師三首 一 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63261ea-2130-4663-b206-8c52c3915222', '遙傷茅山縣孫尊師三首 二', '遙傷茅山縣孫尊師三首 二', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["金格期初至，飆輪去不停。","山摧武擔石，天隕少微星。","弟子悲徐甲，門人泣蔡經。","空聞留玉舃，猶在阜鄉亭。"]', '["金格期初至，飆輪去不停。","山摧武擔石，天隕少微星。","弟子悲徐甲，门人泣蔡經。","空闻留玉舃，猶在阜乡亭。"]', '诗', 'shi', '', NULL, '遙傷茅山縣孫尊師三首 二 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f38d5e-78f2-42cb-aaff-a5146e980d4d', '遙傷茅山縣孫尊師三首 三', '遙傷茅山縣孫尊師三首 三', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["空宇留丹竈，層霞被羽衣。","舊山聞鹿化，遺舃尚鳧飛。","數日奇香在，何年白鶴歸。","想君旋下淚，方欵里閭扉。"]', '["空宇留丹竈，層霞被羽衣。","旧山闻鹿化，遺舃尚鳧飞。","數日奇香在，何年白鹤归。","想君旋下泪，方欵里閭扉。"]', '诗', 'shi', '', NULL, '遙傷茅山縣孫尊師三首 三 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e283ac05-0ee6-4342-b972-af263c1e2405', '尊師是桃源黃先生傳法弟子常見尊師稱先師靈迹今重賦此詩兼寄題黃先生舊館', '尊師是桃源黄先生傳法弟子常见尊師稱先師靈迹今重賦此诗兼寄題黄先生旧館', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["後學方成市，吾師又上賓。","洞天應不夜，源樹秪如春。","棋客留童子，山精避直神。","無因握石髓，及與養生人。"]', '["後学方成市，吾師又上賓。","洞天應不夜，源樹秪如春。","棋客留童子，山精避直神。","無因握石髓，及與養生人。"]', '诗', 'shi', '', NULL, '尊師是桃源黃先生傳法弟子常見尊師稱先師靈迹今重賦此詩兼寄題黃先生舊館 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b2a053-dbd5-4e21-9e46-91ab7f11d0e8', '僕射相公偶話於故集賢張學士廳寫得德裕與僕射舊唱和詩其時和者五人惟僕射與德裕皆列高位淒然懷舊輒獻此詩', '僕射相公偶話於故集賢張学士廳寫得德裕與僕射旧唱和诗其时和者五人惟僕射與德裕皆列高位淒然懷旧輒獻此诗', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["賦感鄰人篴，詩留夫子牆。","延年如有作，應不用山王。"]', '["賦感鄰人篴，诗留夫子牆。","延年如有作，應不用山王。"]', '诗', 'shi', '', NULL, '僕射相公偶話於故集賢張學士廳寫得德裕與僕射舊唱和詩其時和者五人惟僕射與德裕皆列高位淒然懷舊輒獻此詩 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd4807e-f20d-46e4-ab5b-530de8760a99', '惠泉', '惠泉', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["茲泉由太潔，終不畜纖鱗。","到底清何益，含虛勢自貧。","明璣難秘彩，美玉詎潛珍。","未及黃陂量，滔滔豈有津。"]', '["茲泉由太潔，終不畜纖鱗。","到底清何益，含虛勢自貧。","明璣难秘彩，美玉詎潛珍。","未及黄陂量，滔滔豈有津。"]', '诗', 'shi', '', NULL, '惠泉 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a77994-ce2d-485a-a66d-03e8ff1a1465', '無題', '無題', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["松倚蒼崖老，蘭臨碧洞衰。","不勞鄰舍篴，吹起舊時悲。"]', '["松倚蒼崖老，蘭臨碧洞衰。","不勞鄰舍篴，吹起旧时悲。"]', '诗', 'shi', '', NULL, '無題 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08640c71-cf9b-4dc3-a65a-12b770c40af6', '題冠蓋里', '題冠蓋里', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["偶來冠蓋里，媿是舊三公。","自喜無兵術，輕裘上閟宮。"]', '["偶来冠蓋里，媿是旧三公。","自喜無兵術，轻裘上閟宮。"]', '诗', 'shi', '', NULL, '題冠蓋里 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf043f37-cf30-4c39-969c-69b84fcca334', '離平泉馬上作', '離平泉马上作', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["十年紫殿掌洪鈞，出入三朝一品身。","文帝寵深陪雉尾，武皇恩厚宴龍津。","黑山永破和親虜，烏嶺全阬跋扈臣。","自是功高臨盡處，禍來[名]滅不由人。"]', '["十年紫殿掌洪鈞，出入三朝一品身。","文帝寵深陪雉尾，武皇恩厚宴龙津。","黑山永破和親虜，烏嶺全阬跋扈臣。","自是功高臨尽处，禍来[名]滅不由人。"]', '诗', 'shi', '', NULL, '離平泉馬上作 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('190158b4-8500-4485-97c7-52d6a3cc7cc8', '謫嶺南道中作', '謫嶺南道中作', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["嶺水爭分路轉迷，桄榔椰葉暗蠻溪。","愁衝毒霧逢虵草，畏落沙蟲避燕泥。","五月畬田收火米，三更津吏報潮雞。","不堪腸斷思鄉處，紅槿花中越鳥啼。"]', '["嶺水爭分路轉迷，桄榔椰葉暗蠻溪。","愁衝毒霧逢虵草，畏落沙蟲避燕泥。","五月畬田收火米，三更津吏報潮雞。","不堪腸斷思乡处，紅槿花中越鸟啼。"]', '诗', 'shi', '', NULL, '謫嶺南道中作 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec61eac1-97b1-4c60-b17b-62334b8ac6d2', '到惡溪夜泊蘆島', '到惡溪夜泊蘆島', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["甘露花香不再持，遠公應怪負前期。","青蠅豈獨悲虞氏，黃犬應聞笑李斯。","風雨瘴昏蠻日月，煙波魂斷惡溪時。","嶺頭無限相思淚，泣向寒梅近北枝。"]', '["甘露花香不再持，远公應怪負前期。","青蠅豈独悲虞氏，黄犬應闻笑李斯。","风雨瘴昏蠻日月，煙波魂斷惡溪时。","嶺头無限相思泪，泣向寒梅近北枝。"]', '诗', 'shi', '', NULL, '到惡溪夜泊蘆島 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e574a4-9739-4ace-9433-89631cba5a25', '登崖州城作', '登崖州城作', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["獨上高樓望帝京，鳥飛猶是半年程。","青山似欲留人住，百匝千遭遶郡城。"]', '["独上高楼望帝京，鸟飞猶是半年程。","青山似欲留人住，百匝千遭遶郡城。"]', '诗', 'shi', '', NULL, '登崖州城作 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('388be58f-85a2-452f-8b15-30d3a04ad2e9', '鴛鴦篇', '鴛鴦篇', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["君不見昔時同心人，化作鴛鴦鳥。","和鳴一夕不暫離，交頸千年尚爲少。","二月草菲菲，山櫻花未稀。","金塘風日好，何處不相依？","既逢解佩游女，更值凌波宓妃。","精光搖翠蓋，麗色映珠璣。","雙影相伴，雙心莫違。","淹留碧沙上，蕩漾洗紅衣。","春光兮宛轉，嬉遊兮未反。","宿莫近天泉池，飛莫近長洲苑。","爾願歡愛不相忘，須去人間羅網遠。","南有瀟湘洲，且爲千里遊。","洞庭無苦寒，沅江多碧流。","昔爲薄命妾，無日不含愁。","今爲水中鳥，頡頏自相求。","洛陽女兒在青閣，二月羅衣輕更薄。","金泥文彩未足珍，畫作鴛鴦始堪著。","亦有少婦破瓜年，春閨無伴獨嬋娟。","夜夜學織連枝錦，織作鴛鴦人共憐。","悠悠湘水濱，清淺漾初蘋。","菖花發豔無人識，江柳逶迤空自春。","唯憐獨鶴依琴曲，更念孤鸞隱鏡塵。","願作鴛鴦被，長覆有情人。"]', '["君不见昔时同心人，化作鴛鴦鸟。","和鳴一夕不暫離，交頸千年尚爲少。","二月草菲菲，山櫻花未稀。","金塘风日好，何处不相依？","既逢解佩游女，更值凌波宓妃。","精光搖翠蓋，丽色映珠璣。","雙影相伴，雙心莫違。","淹留碧沙上，蕩漾洗紅衣。","春光兮宛轉，嬉游兮未反。","宿莫近天泉池，飞莫近长洲苑。","爾願歡愛不相忘，須去人间羅網远。","南有瀟湘洲，且爲千里游。","洞庭無苦寒，沅江多碧流。","昔爲薄命妾，無日不含愁。","今爲水中鸟，頡頏自相求。","洛陽女兒在青閣，二月羅衣轻更薄。","金泥文彩未足珍，畫作鴛鴦始堪著。","亦有少婦破瓜年，春閨無伴独嬋娟。","夜夜学织連枝錦，织作鴛鴦人共怜。","悠悠湘水濱，清淺漾初蘋。","菖花發豔無人識，江柳逶迤空自春。","唯怜独鹤依琴曲，更念孤鸾隐镜塵。","願作鴛鴦被，长覆有情人。"]', '诗', 'shi', '', NULL, '鴛鴦篇 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c8bb35d-2170-44e1-9fb7-2a1170a96775', '南梁行', '南梁行', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["江南鬱鬱春草長，悠悠漢水浮清光。","雜英飛盡空和景，綠楊陰重官舍靜。","此時醉客縱橫書，公言可薦承明廬。","青天詔下寵光至，頒籍金閨徵石渠。","重歸山路煙嵐隔，巫山未深晚花折。","澗底紅光奪目燃，搖風有毒愁行客。","杜鵑啼咽花亦殷，聲悲絕豔連空山。","斜陽瞥映淺深樹，雲雨翻迷崖谷間。","山雞錦質矜毛羽，透竹穿蘿命儔侶。","喬木幽谷上下同，雄雌不異飛棲處。","望秦峰迥過商顏，浪疊雲堆萬簇山。","行盡杳冥青嶂外，九重鐘漏紫雲間。","元和列侍明光殿，諫草初焚市朝變。","北闕趨臣半隟塵，南梁笑客皆飛霰。","追思感歎却昏迷，霜鬢愁吟到曉雞。","故園歲深開斷簡，秋堂月曉掩遺袿。","嗚嗚曉角霞輝粲，撫劒當楹一長歎。","芻狗無由學聖賢，空持感激終昏旦。"]', '["江南鬱鬱春草长，悠悠漢水浮清光。","杂英飞尽空和景，綠楊陰重官舍静。","此时醉客縱橫书，公言可薦承明廬。","青天詔下寵光至，頒籍金閨徵石渠。","重归山路煙嵐隔，巫山未深晚花折。","澗底紅光奪目燃，搖风有毒愁行客。","杜鵑啼咽花亦殷，声悲絕豔連空山。","斜陽瞥映淺深樹，云雨翻迷崖谷间。","山雞錦質矜毛羽，透竹穿蘿命儔侶。","喬木幽谷上下同，雄雌不異飞棲处。","望秦峰迥過商顏，浪叠云堆万簇山。","行尽杳冥青嶂外，九重鐘漏紫云间。","元和列侍明光殿，諫草初焚市朝变。","北闕趨臣半隟塵，南梁笑客皆飞霰。","追思感歎却昏迷，霜鬢愁吟到晓雞。","故园歲深开斷簡，秋堂月晓掩遺袿。","嗚嗚晓角霞輝粲，撫劒當楹一长歎。","芻狗無由学聖賢，空持感激終昏旦。"]', '诗', 'shi', '', NULL, '南梁行 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb83db3-099a-401f-88d8-93019abd77b1', '近於伊川卜山居將命者畫圖而至欣然有感聊賦此詩兼寄上浙東元相公大夫使求青田胎化鶴', '近於伊川卜山居將命者畫圖而至欣然有感聊賦此诗兼寄上浙东元相公大夫使求青田胎化鹤', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["弱歲弄詞翰，遂叨明主恩。","懷章過越邸，建斾守吳門。","西圮陰難駐，東臯意尚存。","慙逾六百石，愧負五千言。","寄世知嬰繳，辭榮類觸藩。","欲追綿上隱，況近子平村。","邑有桐鄉愛，山餘黍谷暄。","既非逃相地，乃是故侯園。","野竹多微逕，巖泉豈一源。","映池方樹密，傍澗古藤繁。","邛杖堪扶老，黃牛已服轅。","只應將唳鶴，幽谷共翩翻。"]', '["弱歲弄词翰，遂叨明主恩。","懷章過越邸，建斾守吳门。","西圮陰难駐，东臯意尚存。","慙逾六百石，愧負五千言。","寄世知嬰繳，辞榮類觸藩。","欲追綿上隐，況近子平村。","邑有桐乡愛，山餘黍谷暄。","既非逃相地，乃是故侯园。","野竹多微逕，巖泉豈一源。","映池方樹密，傍澗古藤繁。","邛杖堪扶老，黄牛已服轅。","只應將唳鹤，幽谷共翩翻。"]', '诗', 'shi', '', NULL, '近於伊川卜山居將命者畫圖而至欣然有感聊賦此詩兼寄上浙東元相公大夫使求青田胎化鶴 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870e7110-a9f4-4845-aa89-2dbd3ba7cdb3', '憶平泉山居贈沈吏部一首', '憶平泉山居贈沈吏部一首', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔聞羊叔子，茅屋在東渠。","豈不念歸路，徘徊畏簡書。","乃知軒冕客，自與田園疎。","歿世有遺恨，精誠何所如。","嗟予寡時用，夙志在林閭。","雖抱山水癖，敢希仁智居。","清泉繞舍下，修竹蔭庭除。","幽徑松蓋密，小池蓮葉初。","從來有好鳥，近復躍鯈魚。","少室映川陸，鳴臯對蓬廬。","張何舊寮寀，相勉在懸輿。","常恐似伯玉，瞻前慙魏舒。"]', '["昔闻羊叔子，茅屋在东渠。","豈不念归路，徘徊畏簡书。","乃知軒冕客，自與田园疎。","歿世有遺恨，精誠何所如。","嗟予寡时用，夙志在林閭。","雖抱山水癖，敢希仁智居。","清泉繞舍下，修竹蔭庭除。","幽徑松蓋密，小池蓮葉初。","從来有好鸟，近复躍鯈鱼。","少室映川陸，鳴臯对蓬廬。","張何旧寮寀，相勉在懸輿。","常恐似伯玉，瞻前慙魏舒。"]', '诗', 'shi', '', NULL, '憶平泉山居贈沈吏部一首 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7172aa-a31c-402d-a451-e22bbb517df3', '夏晚有懷平泉林居', '夏晚有懷平泉林居', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["孟夏守畏途，捨舟在徂暑。","愀然何所念，念我龍門塢。","密竹無蹊徑，高松有四五。","飛泉鳴樹間，颯颯如度雨。","菌桂秀層嶺，芳蓀媚幽渚。","稚子候我歸，衡門獨延佇。","誰言聖與哲，曾是不懷土。","公旦既思周，宣尼亦念魯。","矧余竄炎裔，日夕誰晤語。","眷闕悲子牟，班荆感椒舉。","悽悽視環玦，惻惻步庭廡。","豈待莊舃吟，方知倦羈旅。"]', '["孟夏守畏途，捨舟在徂暑。","愀然何所念，念我龙门塢。","密竹無蹊徑，高松有四五。","飞泉鳴樹间，颯颯如度雨。","菌桂秀層嶺，芳蓀媚幽渚。","稚子候我归，衡门独延佇。","誰言聖與哲，曾是不懷土。","公旦既思周，宣尼亦念魯。","矧余竄炎裔，日夕誰晤語。","眷闕悲子牟，班荆感椒舉。","悽悽視环玦，惻惻步庭廡。","豈待莊舃吟，方知倦羈旅。"]', '诗', 'shi', '', NULL, '夏晚有懷平泉林居 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1398a0a7-dfec-4645-8bdf-69b6edec5672', '早秋龍興寺江亭閑眺憶龍門山居寄崔張舊從事', '早秋龙兴寺江亭闲眺憶龙门山居寄崔張旧從事', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["江亭感秋至，蘭徑悲露泫。","秔稻秀晚川，杉松鬱晴巘。","嗟予有林壑，茲夕念原衍。","綠篠連嶺多，青莎近溪淺。","淵明菊猶在，仲蔚蒿莫翦。","喬木粲凌苕，陰崖積幽蘚。","遙思伊川水，北渡龍門峴。","蒼翠雙闕間，逶迤清灘轉。","故人在鄉國，歲晏路悠緬。","惆悵此生涯，無由共登踐。"]', '["江亭感秋至，蘭徑悲露泫。","秔稻秀晚川，杉松鬱晴巘。","嗟予有林壑，茲夕念原衍。","綠篠連嶺多，青莎近溪淺。","淵明菊猶在，仲蔚蒿莫翦。","喬木粲凌苕，陰崖積幽蘚。","遙思伊川水，北渡龙门峴。","蒼翠雙闕间，逶迤清灘轉。","故人在乡国，歲晏路悠緬。","惆悵此生涯，無由共登踐。"]', '诗', 'shi', '', NULL, '早秋龍興寺江亭閑眺憶龍門山居寄崔張舊從事 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e747423f-c1f7-418b-9b94-0596086c53f9', '比聞龍門敬善寺有紅桂樹獨秀伊川嘗於江南諸山訪之莫致陳侍御知予所好因訪剡溪樵客偶得數株移植郊園衆芳色沮乃知敬善所有是蜀道菵草徒得嘉名因賦是詩兼贈陳侍御', '比闻龙门敬善寺有紅桂樹独秀伊川嘗於江南諸山訪之莫致陳侍御知予所好因訪剡溪樵客偶得數株移植郊园衆芳色沮乃知敬善所有是蜀道菵草徒得嘉名因賦是诗兼贈陳侍御', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔聞紅桂枝，獨秀龍門側。","越叟遺數株，周人未嘗識。","平生愛此樹，攀翫無由得。","君子知我心，因之爲羽翼。","豈煩嘉客譽，且就清陰息。","來自天姥岑，長疑翠嵐色。","芬芳世所絕，偃蹇枝漸直。","瓊葉潤不凋，珠英粲如織。","猶疑翡翠宿，想待鵷雛食。","寧止暫淹留，終當更封植。"]', '["昔闻紅桂枝，独秀龙门側。","越叟遺數株，周人未嘗識。","平生愛此樹，攀翫無由得。","君子知我心，因之爲羽翼。","豈煩嘉客譽，且就清陰息。","来自天姥岑，长疑翠嵐色。","芬芳世所絕，偃蹇枝漸直。","瓊葉潤不凋，珠英粲如织。","猶疑翡翠宿，想待鵷雛食。","寧止暫淹留，終當更封植。"]', '诗', 'shi', '', NULL, '比聞龍門敬善寺有紅桂樹獨秀伊川嘗於江南諸山訪之莫致陳侍御知予所好因訪剡溪樵客偶得數株移植郊園衆芳色沮乃知敬善所有是蜀道菵草徒得嘉名因賦是詩兼贈陳侍御 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a98b425a-5ba1-4fed-9161-362584634bfd', '懷山居邀松陽子同作', '懷山居邀松陽子同作', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["我有愛山心，如飢復如渴。","出谷一年餘，常疑十年別。","春思巖花爛，夏憶寒泉冽。","秋憶泛蘭巵，冬思玩松雪。","晨思小山桂，暝憶深潭月。","醉憶剖紅梨，飯思食紫蕨。","坐思藤蘿密，步憶莓苔滑。","晝夜百刻中，愁腸幾回絕。","每念羊叔子，言之豈常輟。","人生不如意，十乃居七八。","我未及懸輿，今猶佩朝紱。","焉能逐麋鹿，便得遊林樾。","范恣滄波舟，張懷赤松列。","惟應詎身恤，豈敢忘臣節。","器滿自當欹，物盈終有缺。","從茲返樵徑，庶可希前哲。"]', '["我有愛山心，如飢复如渴。","出谷一年餘，常疑十年別。","春思巖花爛，夏憶寒泉冽。","秋憶泛蘭巵，冬思玩松雪。","晨思小山桂，暝憶深潭月。","醉憶剖紅梨，飯思食紫蕨。","坐思藤蘿密，步憶莓苔滑。","晝夜百刻中，愁腸幾回絕。","每念羊叔子，言之豈常輟。","人生不如意，十乃居七八。","我未及懸輿，今猶佩朝紱。","焉能逐麋鹿，便得游林樾。","范恣滄波舟，張懷赤松列。","惟應詎身恤，豈敢忘臣節。","器满自當欹，物盈終有缺。","從茲返樵徑，庶可希前哲。"]', '诗', 'shi', '', NULL, '懷山居邀松陽子同作 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7824e5f-40ca-4492-8899-8f42452a2372', '思歸赤松村呈松陽子', '思归赤松村呈松陽子', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔人思避世，惟恐不深幽。","禽慶潛名岳，鴟夷漾釣舟。","顧余知止足，所樂在歸休。","不似尋山者，忘家恣遠遊。"]', '["昔人思避世，惟恐不深幽。","禽慶潛名岳，鴟夷漾釣舟。","顧余知止足，所乐在归休。","不似尋山者，忘家恣远游。"]', '诗', 'shi', '', NULL, '思歸赤松村呈松陽子 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c9734d-d165-47d8-8528-e80dccfba3d9', '近臘對雪有懷林居', '近臘对雪有懷林居', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["蓬門常晝掩，竹徑寂無人。","鳥起飄松霰，麕行動谷榛。","應知禽魚侶，合與薜蘿親。","遙憶平臯望，溪煙已發春。"]', '["蓬门常晝掩，竹徑寂無人。","鸟起飄松霰，麕行动谷榛。","應知禽鱼侶，合與薜蘿親。","遙憶平臯望，溪煙已發春。"]', '诗', 'shi', '', NULL, '近臘對雪有懷林居 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c05ba0-1740-48fc-9e3f-11936702d76d', '思山居一十首 清明後憶山中', '思山居一十首 清明後憶山中', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["遙思寒食後，野老林下醉。","月照一山明，風吹百花氣。","飛泉與萬籟，髣髴疑簫吹。","不待曙華分，已應喧鳥至。"]', '["遙思寒食後，野老林下醉。","月照一山明，风吹百花氣。","飞泉與万籟，髣髴疑簫吹。","不待曙华分，已應喧鸟至。"]', '诗', 'shi', '', NULL, '思山居一十首 清明後憶山中 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24253550-2f45-45be-815e-997e872d38a8', '思山居一十首 題寄商山石', '思山居一十首 題寄商山石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["綺皓巖中石，嘗經伴隱淪。","紫芝呈幾曲，紅蘚閟千春。","聊用支琴尾，寧惟倚病身。","自知來處所，何暇問嚴遵。"]', '["綺皓巖中石，嘗經伴隐淪。","紫芝呈幾曲，紅蘚閟千春。","聊用支琴尾，寧惟倚病身。","自知来处所，何暇问嚴遵。"]', '诗', 'shi', '', NULL, '思山居一十首 題寄商山石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d8f2552-eed0-4ece-9701-dd3126dd89c2', '思山居一十首 憶鐘苽時', '思山居一十首 憶鐘苽时', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["尚平方畢娶，疎廣念歸期。","澗底松成蓋，簷前桂長枝。","徑閑芳草合，山靜落花遲。","雖有苽園在，無因及種時。"]', '["尚平方畢娶，疎廣念归期。","澗底松成蓋，簷前桂长枝。","徑闲芳草合，山静落花遲。","雖有苽园在，無因及種时。"]', '诗', 'shi', '', NULL, '思山居一十首 憶鐘苽時 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('920a0be7-5088-4a6a-b724-bc765c5684fa', '思山居一十首 春日獨坐思歸', '思山居一十首 春日独坐思归', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["壯齡心已盡，孤賞意猶存。","豈望圖麟閣，惟思臥鹿門。","無謀堪適野，何力可拘原。","只有容身去，幽山自灌園。"]', '["壯齡心已尽，孤賞意猶存。","豈望圖麟閣，惟思臥鹿门。","無謀堪適野，何力可拘原。","只有容身去，幽山自灌园。"]', '诗', 'shi', '', NULL, '思山居一十首 春日獨坐思歸 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d37048b-90e3-4fdf-bd9e-f2f6e272c9f3', '思山居一十首 思登家山林嶺', '思山居一十首 思登家山林嶺', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["自知無世用，只是愛山遊。","舊有嵇康嬾，今慙趙武偷。","登巒未覺疾，泛水便忘憂。","最惜殘筋力，捫蘿遍一丘。"]', '["自知無世用，只是愛山游。","旧有嵇康嬾，今慙趙武偷。","登巒未覺疾，泛水便忘憂。","最惜殘筋力，捫蘿遍一丘。"]', '诗', 'shi', '', NULL, '思山居一十首 思登家山林嶺 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a32612-fac8-4a8b-b311-52a396fe23e5', '思山居一十首 思鄉園老人', '思山居一十首 思乡园老人', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["常羨蓽門翁，所思惟歲稔。","遙知松月曙，尚在山窗寢。","蘭氣入幽簾，禽言傍孤枕。","晨興步巖徑，更酌寒泉飲。"]', '["常羨蓽门翁，所思惟歲稔。","遙知松月曙，尚在山窗寢。","蘭氣入幽簾，禽言傍孤枕。","晨兴步巖徑，更酌寒泉饮。"]', '诗', 'shi', '', NULL, '思山居一十首 思鄉園老人 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09154b8e-daf6-4da6-a951-2596efb2a3af', '思山居一十首 寄龍門僧', '思山居一十首 寄龙门僧', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["龍門有開士，愛我春潭碧。","清景出東山，閑來玩松石。","應憐林壑主，遠作滄溟客。","爲我謝此僧，終當理歸策。"]', '["龙门有开士，愛我春潭碧。","清景出东山，闲来玩松石。","應怜林壑主，远作滄溟客。","爲我謝此僧，終當理归策。"]', '诗', 'shi', '', NULL, '思山居一十首 寄龍門僧 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffbd7136-ae59-4a8f-81c2-b4e71b5d81f1', '思山居一十首 憶藥苗', '思山居一十首 憶藥苗', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["溪上藥苗齊，丰茸正堪掇。","皆能扶我壽，豈止堅肌骨。","味掩商山芝，英逾首陽蕨。","豈如甘谷士，只得香泉啜。"]', '["溪上藥苗齊，丰茸正堪掇。","皆能扶我壽，豈止堅肌骨。","味掩商山芝，英逾首陽蕨。","豈如甘谷士，只得香泉啜。"]', '诗', 'shi', '', NULL, '思山居一十首 憶藥苗 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2fd112f-3850-4bdd-987a-9b1c444c3dc0', '思山居一十首 憶村中老人春酒', '思山居一十首 憶村中老人春酒', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["二叟茅茨下，清晨飲濁醪。","雨殘紅芍藥，風落紫櫻桃。","巢燕銜泥疾，簷蟲挂網高。","閑思春谷事，轉覺宦途勞。"]', '["二叟茅茨下，清晨饮濁醪。","雨殘紅芍藥，风落紫櫻桃。","巢燕銜泥疾，簷蟲挂網高。","闲思春谷事，轉覺宦途勞。"]', '诗', 'shi', '', NULL, '思山居一十首 憶村中老人春酒 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c08c0804-5f75-499d-b89d-2e7fc922876e', '思山居一十首 憶葛勝木禪床', '思山居一十首 憶葛勝木禪床', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["憶我齋中榻，寒宵幾獨眠。","管寧穿亦坐，徐孺去常懸。","蟲網垂應遍，苔痕染更鮮。","何人及身在，歸對老僧禪。"]', '["憶我斋中榻，寒宵幾独眠。","管寧穿亦坐，徐孺去常懸。","蟲網垂應遍，苔痕染更鲜。","何人及身在，归对老僧禪。"]', '诗', 'shi', '', NULL, '思山居一十首 憶葛勝木禪床 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d38f001-75cd-44c4-91a4-ece9b6030134', '初夏有懷山居', '初夏有懷山居', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["山中有所憶，夏景始清幽。","野竹陰無日，巖泉冷似秋。","翠岑當累榭，皓月入輕舟。","只有思歸夕，空簾且夢遊。"]', '["山中有所憶，夏景始清幽。","野竹陰無日，巖泉冷似秋。","翠岑當累榭，皓月入轻舟。","只有思归夕，空簾且梦游。"]', '诗', 'shi', '', NULL, '初夏有懷山居 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0eff5a-f089-4ffc-875f-49d7a41ec8a4', '張公超谷中石', '張公超谷中石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["鼓篋依綠槐，橫經起秋霧。","有時連岳客，尚辦絃歌處。","自予去幽谷，誰人襲芳杜。","空留古苔石，對我巖中樹。"]', '["鼓篋依綠槐，橫經起秋霧。","有时連岳客，尚辦絃歌处。","自予去幽谷，誰人襲芳杜。","空留古苔石，对我巖中樹。"]', '诗', 'shi', '', NULL, '張公超谷中石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38853f70-8e7a-4af2-a182-f2eae2619119', '初歸平泉過龍門南嶺遙望山居即事', '初归平泉過龙门南嶺遙望山居即事', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["初歸故鄉陌，極望且徐輪。","近野樵蒸至，平泉煙火新。","農夫饋雞黍，漁子薦霜鱗。","惆悵懷楊僕，慚爲關外人。"]', '["初归故乡陌，極望且徐輪。","近野樵蒸至，平泉煙火新。","農夫饋雞黍，漁子薦霜鱗。","惆悵懷楊僕，慚爲关外人。"]', '诗', 'shi', '', NULL, '初歸平泉過龍門南嶺遙望山居即事 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('383eda54-11ce-47da-be4a-c79a1dce423a', '伊川晚眺', '伊川晚眺', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["桑葉初黃梨葉紅，伊川落日盡無風。","漢儲何假終南客，甪里先生在谷中。"]', '["桑葉初黄梨葉紅，伊川落日尽無风。","漢儲何假終南客，甪里先生在谷中。"]', '诗', 'shi', '', NULL, '伊川晚眺 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67aa90b3-9634-49b3-b0c4-14b9f17c5432', '潭上喜見新月', '潭上喜见新月', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["簪組十年夢，園廬今夕情。","誰憐故鄉月，復映碧潭生。","皓彩松上見，寒光波際輕。","還將孤賞意，暫寄玉琴聲。"]', '["簪組十年梦，园廬今夕情。","誰怜故乡月，复映碧潭生。","皓彩松上见，寒光波際轻。","還將孤賞意，暫寄玉琴声。"]', '诗', 'shi', '', NULL, '潭上喜見新月 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9e9cd2-522f-4809-a26f-648afdbd2afa', '郊外即事寄侍郎大尹', '郊外即事寄侍郎大尹', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["高秋慙非隱，閑林喜退居。","老農爭席坐，稚子帶經鋤。","竹徑難迴騎，仙舟但跂予。","豈知陶靖節，秪自愛吾廬。"]', '["高秋慙非隐，闲林喜退居。","老農爭席坐，稚子带經鋤。","竹徑难迴騎，仙舟但跂予。","豈知陶靖節，秪自愛吾廬。"]', '诗', 'shi', '', NULL, '郊外即事寄侍郎大尹 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('297fbc2e-c789-41df-b4a3-5aebe3b55cb9', '山居遇雪喜道者相訪', '山居遇雪喜道者相訪', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["幽居近谷西，喬木與山齊。","野竹連池合，巖松映雪低。","喜君來白社，值我在青谿。","應笑於陵子，遺榮自灌畦。"]', '["幽居近谷西，喬木與山齊。","野竹連池合，巖松映雪低。","喜君来白社，值我在青谿。","應笑於陵子，遺榮自灌畦。"]', '诗', 'shi', '', NULL, '山居遇雪喜道者相訪 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('275423ed-cfdb-4b5b-830e-cc40137333ee', '雪霽晨起', '雪霽晨起', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["雪覆寒溪竹，風卷野田蓬。","四望無竹跡，誰憐孤老翁。"]', '["雪覆寒溪竹，风卷野田蓬。","四望無竹跡，誰怜孤老翁。"]', '诗', 'shi', '', NULL, '雪霽晨起 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3282311c-bea6-4f03-83ba-e4e0dd5457ca', '洛中士君子多以平泉見呼愧獲方外之名因以此詩爲報奉寄劉賓客', '洛中士君子多以平泉见呼愧獲方外之名因以此诗爲報奉寄劉賓客', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["非高柳下逸，自愛竹林閑。","才異居東里，愚因在北山。","徑荒寒未掃，門設晝長關。","不及鴟夷子，悠悠煙水間。"]', '["非高柳下逸，自愛竹林闲。","才異居东里，愚因在北山。","徑荒寒未掃，门設晝长关。","不及鴟夷子，悠悠煙水间。"]', '诗', 'shi', '', NULL, '洛中士君子多以平泉見呼愧獲方外之名因以此詩爲報奉寄劉賓客 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e747758a-5fe6-4ee8-b2d2-e462ca32f42c', '早春至言禪公法堂憶平泉別業', '早春至言禪公法堂憶平泉別業', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔我伊原上，孤遊竹樹間。","人依紅桂靜，鳥傍碧潭閑。","松蓋低春雪，藤輪倚暮山。","永懷桑梓邑，衰老若爲還。"]', '["昔我伊原上，孤游竹樹间。","人依紅桂静，鸟傍碧潭闲。","松蓋低春雪，藤輪倚暮山。","永懷桑梓邑，衰老若爲還。"]', '诗', 'shi', '', NULL, '早春至言禪公法堂憶平泉別業 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22179021-1fac-45c0-9764-8f1f76da456d', '峽山亭月夜獨宿對櫻桃花有懷伊川別墅', '峽山亭月夜独宿对櫻桃花有懷伊川別墅', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["皎月照芳樹，鮮葩含素輝。","愁人惜春夜，達曙想巖扉。","風靜陰滿砌，露濃香入衣。","恨無金谷妓，爲我奏思歸。"]', '["皎月照芳樹，鲜葩含素輝。","愁人惜春夜，達曙想巖扉。","风静陰满砌，露濃香入衣。","恨無金谷妓，爲我奏思归。"]', '诗', 'shi', '', NULL, '峽山亭月夜獨宿對櫻桃花有懷伊川別墅 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ca78c96-d703-4bc1-839c-3bc02f55bdf9', '春暮思平泉雜詠二十首 望伊川', '春暮思平泉杂詠二十首 望伊川', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["遠村寒食後，細雨度川來。","芳草連谿合，梨花映墅開。","槿籬懸落照，松徑長新苔。","向夕亭臯望，遊禽幾處回。"]', '["远村寒食後，細雨度川来。","芳草連谿合，梨花映墅开。","槿籬懸落照，松徑长新苔。","向夕亭臯望，游禽幾处回。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 望伊川 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfdce32c-1438-4ccc-8e1d-e951a06c059e', '春暮思平泉雜詠二十首 潭上紫藤', '春暮思平泉杂詠二十首 潭上紫藤', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["故鄉春欲盡，一歲芳難再。","巖樹已青葱，吾廬日堪愛。","幽溪人未去，芳草行應礙。","遙憶紫藤垂，繁英照潭黛。"]', '["故乡春欲尽，一歲芳难再。","巖樹已青葱，吾廬日堪愛。","幽溪人未去，芳草行應礙。","遙憶紫藤垂，繁英照潭黛。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 潭上紫藤 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97a8d41f-bcd2-4fc4-809b-bd6f8df79441', '春暮思平泉雜詠二十首 書樓晴望', '春暮思平泉杂詠二十首 书楼晴望', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["幽居人世外，久厭市朝喧。","蒼翠連雙闕，微茫認九原。","殘紅映鞏樹，斜日照轘轅。","薄暮柴扉掩，誰知仲蔚園。"]', '["幽居人世外，久厭市朝喧。","蒼翠連雙闕，微茫認九原。","殘紅映鞏樹，斜日照轘轅。","薄暮柴扉掩，誰知仲蔚园。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 書樓晴望 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3006dfc-e98b-4e18-9c70-9dfaf1cb215a', '春暮思平泉雜詠二十首 西嶺望鳴臯山', '春暮思平泉杂詠二十首 西嶺望鳴臯山', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["高秋對涼野，四望何蕭瑟。","遠見鳴臯山，青峰原上出。","晨興採薇蕨，向暮歸蓬蓽。","詎假數揮金，餐和養餘日。"]', '["高秋对涼野，四望何蕭瑟。","远见鳴臯山，青峰原上出。","晨兴採薇蕨，向暮归蓬蓽。","詎假數揮金，餐和養餘日。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 西嶺望鳴臯山 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ef031d-f029-4b5b-8708-837db6c42462', '春暮思平泉雜詠二十首 瀑泉亭', '春暮思平泉杂詠二十首 瀑泉亭', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["向老多悲恨，悽然念一丘。","巖泉終古在，風月幾年遊。","菌閣饒佳樹，菱潭有釣舟。","不如羊叔子，名與峴山留。"]', '["向老多悲恨，悽然念一丘。","巖泉終古在，风月幾年游。","菌閣饒佳樹，菱潭有釣舟。","不如羊叔子，名與峴山留。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 瀑泉亭 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab72ba3a-5a6b-4923-bdff-ca04b8dc658a', '春暮思平泉雜詠二十首 紅桂樹', '春暮思平泉杂詠二十首 紅桂樹', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["欲求塵外物，此樹是瑤林。","後素合餘絢，如丹見本心。","妍姿無點辱，芳意託幽深。","願以鮮葩色，凌霜照碧潯。"]', '["欲求塵外物，此樹是瑤林。","後素合餘絢，如丹见本心。","妍姿無点辱，芳意託幽深。","願以鲜葩色，凌霜照碧潯。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 紅桂樹 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5fc7e08-e26d-4d96-a0a8-d6fa3aabbcba', '春暮思平泉雜詠二十首 金松', '春暮思平泉杂詠二十首 金松', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["台嶺生奇樹，佳名世未知。","纖纖疑大菊，落落是松枝。","照日含金晰，籠煙淡翠滋。","勿言人去晚，猶有歲寒期。"]', '["台嶺生奇樹，佳名世未知。","纖纖疑大菊，落落是松枝。","照日含金晰，籠煙淡翠滋。","勿言人去晚，猶有歲寒期。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 金松 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805f3344-6463-490d-9751-736ceb7b0d35', '春暮思平泉雜詠二十首 月桂', '春暮思平泉杂詠二十首 月桂', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["何年霜夜月，桂子落寒山。","翠幹生巖下，金英在世間。","幽崖空自老，清漢未知還。","惟有涼秋夜，嫦娥來暫攀。"]', '["何年霜夜月，桂子落寒山。","翠幹生巖下，金英在世间。","幽崖空自老，清漢未知還。","惟有涼秋夜，嫦娥来暫攀。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 月桂 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29163583-e6fa-467c-9708-f659ee45f355', '春暮思平泉雜詠二十首 山桂', '春暮思平泉杂詠二十首 山桂', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["吾愛山中樹，繁英滿目鮮。","臨風飄碎錦，映日亂非煙。","影入春潭底，香凝月榭前。","豈知幽獨客，賴此當朱絃。"]', '["吾愛山中樹，繁英满目鲜。","臨风飄碎錦，映日亂非煙。","影入春潭底，香凝月榭前。","豈知幽独客，賴此當朱絃。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 山桂 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db06ced-43bb-40c0-8f6c-cd85147c43d1', '春暮思平泉雜詠二十首 栢', '春暮思平泉杂詠二十首 栢', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["聞有三株樹，惟應秘閬風。","珊瑚不生葉，朱草又無叢。","未若凌雲栢，常能終歲紅。","晨霞與落日，相照在巖中。"]', '["闻有三株樹，惟應秘閬风。","珊瑚不生葉，朱草又無叢。","未若凌云栢，常能終歲紅。","晨霞與落日，相照在巖中。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 栢 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82207ddc-db30-477d-8563-91bec1321707', '春暮思平泉雜詠二十首 芳蓀', '春暮思平泉杂詠二十首 芳蓀', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["楚客重蘭蓀，遺芳今未歇。","葉抽清淺水，花照暄妍節。","紫豔映渠鮮，輕香含露潔。","離居若有贈，暫與幽人折。"]', '["楚客重蘭蓀，遺芳今未歇。","葉抽清淺水，花照暄妍節。","紫豔映渠鲜，轻香含露潔。","離居若有贈，暫與幽人折。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 芳蓀 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c07e2f8-507b-43e2-866e-f5197d14e262', '春暮思平泉雜詠二十首 流盃亭', '春暮思平泉杂詠二十首 流盃亭', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["激水自山椒，析波分淺瀨。","回環疑古篆，詰曲如縈帶。","寧愬羽觴遲，惟歡親友會。","欲知中聖處，皓月臨松蓋。"]', '["激水自山椒，析波分淺瀨。","回环疑古篆，詰曲如縈带。","寧愬羽觴遲，惟歡親友會。","欲知中聖处，皓月臨松蓋。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 流盃亭 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79ae1555-e2eb-4b93-a799-cc90fe9944f9', '春暮思平泉雜詠二十首 東谿', '春暮思平泉杂詠二十首 东谿', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["近蓄東谿水，悠悠起淥波。","綵鴛留不去，芳草日應多。","夾岸生奇篠，緣巖覆女蘿。","蘭橈思無限，爲感濯纓歌。"]', '["近蓄东谿水，悠悠起淥波。","綵鴛留不去，芳草日應多。","夾岸生奇篠，緣巖覆女蘿。","蘭橈思無限，爲感濯纓歌。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 東谿 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b420e8b-6da9-492e-947d-f34c439e9806', '春暮思平泉雜詠二十首 鸂鶒', '春暮思平泉杂詠二十首 鸂鶒', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["清沚雙鸂鶒，前年海上雛。","今年戀洲嶼，思若在江湖。","欲起搖荷蓋，閑飛濺水珠。","不能常泛泛，惟作逐波鳧。"]', '["清沚雙鸂鶒，前年海上雛。","今年戀洲嶼，思若在江湖。","欲起搖荷蓋，闲飞濺水珠。","不能常泛泛，惟作逐波鳧。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 鸂鶒 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26fd6c50-4a0d-4358-ba54-5ff59e9d4d27', '春暮思平泉雜詠二十首 西園', '春暮思平泉杂詠二十首 西园', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["西園最多趣，永日自忘歸。","石瀨流清淺，風岑澹翠微。","曉翻紅藥豔，晴裊碧潭輝。","獨望娟娟月，宵分半掩扉。"]', '["西园最多趣，永日自忘归。","石瀨流清淺，风岑澹翠微。","晓翻紅藥豔，晴裊碧潭輝。","独望娟娟月，宵分半掩扉。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 西園 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9629804a-398d-4262-90b8-4e245123e7a6', '春暮思平泉雜詠二十首 海石楠', '春暮思平泉杂詠二十首 海石楠', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔見歷陽山，雞籠已孤秀。","今看海嶠樹，翠蓋何幽茂。","霰雪詎能侵，煙嵐自相揉。","攀條獨臨憩，況值清陰晝。"]', '["昔见歷陽山，雞籠已孤秀。","今看海嶠樹，翠蓋何幽茂。","霰雪詎能侵，煙嵐自相揉。","攀條独臨憩，況值清陰晝。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 海石楠 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff533005-4c8c-4a7f-81ef-9e60ec961ba4', '春暮思平泉雜詠二十首 雙碧潭', '春暮思平泉杂詠二十首 雙碧潭', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["清剡與嚴湍，潺湲皆可憶。","適來玩山水，無此秋潭色。","莫辨幽蘭叢，難分翠禽翼。","遲遲洲渚步，臨眺忘餐食。"]', '["清剡與嚴湍，潺湲皆可憶。","適来玩山水，無此秋潭色。","莫辨幽蘭叢，难分翠禽翼。","遲遲洲渚步，臨眺忘餐食。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 雙碧潭 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29a9d34b-cc0d-4926-a979-7f6eee920ee6', '春暮思平泉雜詠二十首 竹徑', '春暮思平泉杂詠二十首 竹徑', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["野竹自成徑，繞溪三里餘。","檀欒被層阜，蕭瑟蔭清渠。","日落見林靜，風行知谷虛。","田家故人少，誰肯共焚魚。"]', '["野竹自成徑，繞溪三里餘。","檀欒被層阜，蕭瑟蔭清渠。","日落见林静，风行知谷虛。","田家故人少，誰肯共焚鱼。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 竹徑 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5310b4ae-6d3e-46c5-974b-c0613f854e9c', '春暮思平泉雜詠二十首 花藥欄', '春暮思平泉杂詠二十首 花藥欄', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["蕙草春已碧，蘭花秋更紅。","四時發英豔，三徑滿芳叢。","秀色濯清露，鮮輝搖惠風。","王孫未知返，幽賞竟誰同。"]', '["蕙草春已碧，蘭花秋更紅。","四时發英豔，三徑满芳叢。","秀色濯清露，鲜輝搖惠风。","王孫未知返，幽賞竟誰同。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 花藥欄 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994c6256-3246-4a44-8bb7-f01950782e72', '春暮思平泉雜詠二十首 自敘', '春暮思平泉杂詠二十首 自敘', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["五嶽徑雖深，遍遊心已蕩。","苟能知止足，所遇皆清曠。","七十難可期，一丘乃微尚。","遙懷少室山，常恐非吾望。"]', '["五嶽徑雖深，遍游心已蕩。","苟能知止足，所遇皆清曠。","七十难可期，一丘乃微尚。","遙懷少室山，常恐非吾望。"]', '诗', 'shi', '', NULL, '春暮思平泉雜詠二十首 自敘 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b852ff25-d358-4939-bf05-03b9ec76c667', '首夏清景想望山居', '首夏清景想望山居', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["嘉樹陰初合，山中賞更新。","禽言未知夏，蘭徑尚餘春。","散滿蘿垂帶，扶疎桂長輪。","丹青寫不盡，宵夢歎非真。","累榭空留月，虛舟若待人。","何時倚蘭棹，相與掇汀蘋。"]', '["嘉樹陰初合，山中賞更新。","禽言未知夏，蘭徑尚餘春。","散满蘿垂带，扶疎桂长輪。","丹青寫不尽，宵梦歎非真。","累榭空留月，虛舟若待人。","何时倚蘭棹，相與掇汀蘋。"]', '诗', 'shi', '', NULL, '首夏清景想望山居 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5385ff2d-f7c3-47b2-8333-8f0ba58081e4', '思平泉樹石雜詠一十首 釣臺', '思平泉樹石杂詠一十首 釣台', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["我有嚴湍思，懷人訪故臺。","客星依釣隱，仙石逐槎回。","倒影含清沚，凝陰長碧苔。","飛泉信可挹，幽客未歸來。"]', '["我有嚴湍思，懷人訪故台。","客星依釣隐，仙石逐槎回。","倒影含清沚，凝陰长碧苔。","飞泉信可挹，幽客未归来。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 釣臺 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13dc5e49-a70c-4cc0-bb86-c8b70f62f22b', '思平泉樹石雜詠一十首 似鹿石', '思平泉樹石杂詠一十首 似鹿石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["林中有奇石，髣髴獸潛行。","乍似依巖桂，還疑食野苹。","茸長綠蘚映，斑細紫苔生。","不是見羇者，何勞如頓纓。"]', '["林中有奇石，髣髴獸潛行。","乍似依巖桂，還疑食野苹。","茸长綠蘚映，斑細紫苔生。","不是见羇者，何勞如頓纓。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 似鹿石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a49c386-19d4-4855-ab4d-d357ae71cd38', '思平泉樹石雜詠一十首 海上石笋', '思平泉樹石杂詠一十首 海上石笋', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["常愛仙都山，奇峰千仞懸。","迢迢一何迥，不與衆山連。","忽逢海嶠石，稍慰平生憶。","何以慰我心，亭亭孤且直。"]', '["常愛仙都山，奇峰千仞懸。","迢迢一何迥，不與衆山連。","忽逢海嶠石，稍慰平生憶。","何以慰我心，亭亭孤且直。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 海上石笋 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6809ea4-b1f5-40f0-9387-7da3a2d02451', '思平泉樹石雜詠一十首 疊石', '思平泉樹石杂詠一十首 叠石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["潺湲桂水湍，漱石多奇狀。","鱗次冠煙霞，蟬聯疊波浪。","今來碧梧下，迥出秋潭上。","歲晚苔蘚滋，懷賢益惆悵。"]', '["潺湲桂水湍，漱石多奇狀。","鱗次冠煙霞，蟬聯叠波浪。","今来碧梧下，迥出秋潭上。","歲晚苔蘚滋，懷賢益惆悵。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 疊石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf1ca36-a813-4a01-958b-9bce9ce5ae83', '思平泉樹石雜詠一十首 重臺芙蓉', '思平泉樹石杂詠一十首 重台芙蓉', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["芙蓉含露時，秀色波中溢。","玉女襲朱裳，重重映皓質。","晨霞耀丹景，片片明秋日。","蘭澤多衆芳，妍姿不相匹。"]', '["芙蓉含露时，秀色波中溢。","玉女襲朱裳，重重映皓質。","晨霞耀丹景，片片明秋日。","蘭澤多衆芳，妍姿不相匹。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 重臺芙蓉 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fef0203b-eed3-4cf6-aeeb-62707ac855e8', '思平泉樹石雜詠一十首 白鷺鶿', '思平泉樹石杂詠一十首 白鷺鶿', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["余心憐白鷺，潭上日相依。","拂石疑星落，凌風似雪飛。","碧沙常獨立，清景自忘歸。","所樂惟煙水，徘徊戀釣磯。"]', '["余心怜白鷺，潭上日相依。","拂石疑星落，凌风似雪飞。","碧沙常独立，清景自忘归。","所乐惟煙水，徘徊戀釣磯。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 白鷺鶿 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2afed80-f205-46c2-9c85-70ed40845509', '思平泉樹石雜詠一十首 海魚骨', '思平泉樹石杂詠一十首 海鱼骨', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔日任公子，期年釣此魚。","無由見成岳，聊喜識專車。","皎皎連霜月，高高映碧渠。","陶潛雖好事，觀海只披圖。"]', '["昔日任公子，期年釣此鱼。","無由见成岳，聊喜識專车。","皎皎連霜月，高高映碧渠。","陶潛雖好事，观海只披圖。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 海魚骨 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727bbbc2-f83b-4c44-a0a3-ba34176b9ab2', '思平泉樹石雜詠一十首 泛池舟', '思平泉樹石杂詠一十首 泛池舟', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["桂舟蘭作枻，芬芳皆絕世。","只可弄潺湲，焉能濟大川。","樹懸涼夜月，風散碧潭煙。","未得同魚子，菱歌共扣舷。"]', '["桂舟蘭作枻，芬芳皆絕世。","只可弄潺湲，焉能濟大川。","樹懸涼夜月，风散碧潭煙。","未得同鱼子，菱歌共扣舷。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 泛池舟 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18862695-afad-4b39-9e30-13595c947f99', '思平泉樹石雜詠一十首 舴艋舟', '思平泉樹石杂詠一十首 舴艋舟', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["無輕舴艋舟，始自鴟夷子。","雙闕挂朝衣，五湖極煙水。","時遊杏壇下，乍入湘川裏。","永日歌濯纓，超然謝塵滓。"]', '["無轻舴艋舟，始自鴟夷子。","雙闕挂朝衣，五湖極煙水。","时游杏壇下，乍入湘川裏。","永日歌濯纓，超然謝塵滓。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 舴艋舟 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edcec266-bb0e-463e-a84c-849192e218a9', '思平泉樹石雜詠一十首 二猿', '思平泉樹石杂詠一十首 二猿', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["釣瀨水漣漪，富春山合沓。","松上夜猿鳴，谷中清響合。","衝網忽見羈，故山從此辭。","無由碧潭飲，爭接綠蘿枝。"]', '["釣瀨水漣漪，富春山合沓。","松上夜猿鳴，谷中清响合。","衝網忽见羈，故山從此辞。","無由碧潭饮，爭接綠蘿枝。"]', '诗', 'shi', '', NULL, '思平泉樹石雜詠一十首 二猿 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9201b478-aece-4771-af96-3e860d0c4ad5', '思在山居日偶成此詠邀松陽子同作', '思在山居日偶成此詠邀松陽子同作', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["閑思昔歲事，忽忽念伊川。","乘月步秋坂，滿山聞石泉。","回塘碧潭映，高樹綠蘿懸。","露下呌田鶴，風來嘶晚蟬。","懷茲長在夢，歸去且無緣。","幽谷人未至，蘭苕應更鮮。"]', '["闲思昔歲事，忽忽念伊川。","乘月步秋坂，满山闻石泉。","回塘碧潭映，高樹綠蘿懸。","露下呌田鹤，风来嘶晚蟬。","懷茲长在梦，归去且無緣。","幽谷人未至，蘭苕應更鲜。"]', '诗', 'shi', '', NULL, '思在山居日偶成此詠邀松陽子同作 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12496f02-3efa-4bf7-8368-9b23850fa5a3', '重憶山居六首 平泉源', '重憶山居六首 平泉源', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["出谷纔浮芥，中園已濫觴。","逶迤過竹塢，浩淼走蘭塘。","夜靜聞魚躍，風微見鴈翔。","從茲東向海，可泛濟川航。"]', '["出谷纔浮芥，中园已濫觴。","逶迤過竹塢，浩淼走蘭塘。","夜静闻鱼躍，风微见鴈翔。","從茲东向海，可泛濟川航。"]', '诗', 'shi', '', NULL, '重憶山居六首 平泉源 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faaf019b-5e60-4094-a7a6-754762ed30df', '重憶山居六首 泰山石', '重憶山居六首 泰山石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["雞鳴日觀望，遠與扶桑對。","滄海似鎔金，衆山如點黛。","遙知碧峰首，獨立煙嵐內。","此石依五松，蒼蒼幾千載。"]', '["雞鳴日观望，远與扶桑对。","滄海似鎔金，衆山如点黛。","遙知碧峰首，独立煙嵐內。","此石依五松，蒼蒼幾千載。"]', '诗', 'shi', '', NULL, '重憶山居六首 泰山石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be29ee26-6ba1-471d-b9d3-948cc2fa4055', '重憶山居六首 巫山石', '重憶山居六首 巫山石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["十二峰前月，三聲猿夜愁。","此中多怪石，日夕漱寒流。","必是歸星渚，先求歷斗牛。","還疑煙雨霽，髣髴是嵩丘。"]', '["十二峰前月，三声猿夜愁。","此中多怪石，日夕漱寒流。","必是归星渚，先求歷斗牛。","還疑煙雨霽，髣髴是嵩丘。"]', '诗', 'shi', '', NULL, '重憶山居六首 巫山石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ccc575-b4f1-4027-b442-811fc39a451d', '重憶山居六首 羅浮山', '重憶山居六首 羅浮山', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["龍伯釣鼇時，蓬萊一峰坼。","飛來碧海畔，遂與三山隔。","其下多長溪，潺湲淙亂石。","知君分如此，贈逾荆山璧。"]', '["龙伯釣鼇时，蓬萊一峰坼。","飞来碧海畔，遂與三山隔。","其下多长溪，潺湲淙亂石。","知君分如此，贈逾荆山璧。"]', '诗', 'shi', '', NULL, '重憶山居六首 羅浮山 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805feea3-9669-4ea8-a097-d50534875e13', '重憶山居六首 漏潭石', '重憶山居六首 漏潭石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["常疑六合外，未信漆園書。","及此聞溪漏，方欣驗尾閭。","大哉天地氣，呼吸有盈虛。","美石勞相贈，瓊瑰自不如。"]', '["常疑六合外，未信漆园书。","及此闻溪漏，方欣驗尾閭。","大哉天地氣，呼吸有盈虛。","美石勞相贈，瓊瑰自不如。"]', '诗', 'shi', '', NULL, '重憶山居六首 漏潭石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('261752fa-18b4-40f4-8014-c470041ba395', '重憶山居六首 釣石', '重憶山居六首 釣石', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["嚴光隱富春，山色谿又碧。","所釣不在魚，揮綸以自適。","余懷慕君子，且欲坐潭石。","持此返伊川，悠然慰衰疾。"]', '["嚴光隐富春，山色谿又碧。","所釣不在鱼，揮綸以自適。","余懷慕君子，且欲坐潭石。","持此返伊川，悠然慰衰疾。"]', '诗', 'shi', '', NULL, '重憶山居六首 釣石 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a084f7d-f42e-4381-a3ba-208cd7b0e0cc', '懷伊川郊居', '懷伊川郊居', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["衰疾常懷土，郊園欲掩扉。","雖知明目地，不及有身歸。","鞏樹秋陰遍，伊原霽色微。","此生看白首，良願已應違。"]', '["衰疾常懷土，郊园欲掩扉。","雖知明目地，不及有身归。","鞏樹秋陰遍，伊原霽色微。","此生看白首，良願已應違。"]', '诗', 'shi', '', NULL, '懷伊川郊居 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a66e68-70db-4b33-b62e-b2828037323e', '晨起見雪憶山居', '晨起见雪憶山居', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["忽憶巖中雪，誰人拂薜蘿。","竹梢低未舉，松蓋偃應多。","山溜隨冰落，林麕帶霰過。","不勞聞鶴語，方奏苦寒歌。"]', '["忽憶巖中雪，誰人拂薜蘿。","竹梢低未舉，松蓋偃應多。","山溜隨冰落，林麕带霰過。","不勞闻鹤語，方奏苦寒歌。"]', '诗', 'shi', '', NULL, '晨起見雪憶山居 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('691e9ad8-895a-4613-95f9-a006846938e6', '憶平泉雜詠 憶初暖', '憶平泉杂詠 憶初暖', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["今日初春暖，山中事若何。","雪開喧鳥至，澌散躍魚多。","幽翠生松栝，輕煙起薜蘿。","柴扉常晝掩，惟有野人過。"]', '["今日初春暖，山中事若何。","雪开喧鸟至，澌散躍鱼多。","幽翠生松栝，轻煙起薜蘿。","柴扉常晝掩，惟有野人過。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶初暖 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16051d12-58a3-4822-9206-4f6697994051', '憶平泉雜詠 憶辛夷', '憶平泉杂詠 憶辛夷', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["昔年將出谷，幾日對辛夷。","倚樹憐芳意，攀條惜歲滋。","清陰須暫憩，秀色正堪思。","只待揮金日，慇懃泛羽巵。"]', '["昔年將出谷，幾日对辛夷。","倚樹怜芳意，攀條惜歲滋。","清陰須暫憩，秀色正堪思。","只待揮金日，慇懃泛羽巵。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶辛夷 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12029f03-2eaa-44eb-9944-e95e1f178cd8', '憶平泉雜詠 憶寒梅', '憶平泉杂詠 憶寒梅', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["寒塘數樹梅，常近臘前開。","雪映緣巖竹，香侵泛水苔。","遙思清景暮，還有野禽來。","誰是攀枝客，茲辰醉始迴。"]', '["寒塘數樹梅，常近臘前开。","雪映緣巖竹，香侵泛水苔。","遙思清景暮，還有野禽来。","誰是攀枝客，茲辰醉始迴。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶寒梅 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb8af5d-a5b4-442e-a9c1-e3f42a2d154f', '憶平泉雜詠 憶藥欄', '憶平泉杂詠 憶藥欄', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["野人清旦起，掃雪見蘭芽。","始畎春泉入，惟愁暮景斜。","未抽萱草葉，纔發欵冬花。","誰念江潭老，中宵旅夢賒。"]', '["野人清旦起，掃雪见蘭芽。","始畎春泉入，惟愁暮景斜。","未抽萱草葉，纔發欵冬花。","誰念江潭老，中宵旅梦賒。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶藥欄 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b70daa4-ed82-4ba5-8dc0-6345d6542862', '憶平泉雜詠 憶茗芽', '憶平泉杂詠 憶茗芽', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["谷中春日暖，漸憶掇茶英。","欲及清明火，能銷醉客酲。","松花飄鼎泛，蘭氣入甌輕。","飲罷閑無事，捫蘿溪上行。"]', '["谷中春日暖，漸憶掇茶英。","欲及清明火，能銷醉客酲。","松花飄鼎泛，蘭氣入甌轻。","饮罷闲無事，捫蘿溪上行。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶茗芽 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50586423-6e02-4ebe-a4a9-1897f6ebdb80', '憶平泉雜詠 憶野花', '憶平泉杂詠 憶野花', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["雖遊洛陽道，未識故園花。","曉憶東谿雪，晴思冠嶺霞。","谷深蘭色秀，村迥柳陰斜。","悵望龍門晚，誰知小隱家。"]', '["雖游洛陽道，未識故园花。","晓憶东谿雪，晴思冠嶺霞。","谷深蘭色秀，村迥柳陰斜。","悵望龙门晚，誰知小隐家。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶野花 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db47599-0db5-4a4f-90f4-9f76b8d1036e', '憶平泉雜詠 憶春雨', '憶平泉杂詠 憶春雨', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["春鳩鳴野樹，細雨入池塘。","潭上花微落，溪邊草更長。","梳風白鷺起，拂水綵鴛翔。","最羨歸飛燕，年年在故鄉。"]', '["春鳩鳴野樹，細雨入池塘。","潭上花微落，溪邊草更长。","梳风白鷺起，拂水綵鴛翔。","最羨归飞燕，年年在故乡。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶春雨 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd98fea1-e19b-4351-9146-f8dbbe56484c', '憶平泉雜詠 憶晚眺', '憶平泉杂詠 憶晚眺', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["伊川新雨霽，原上見春山。","緱嶺晴虹斷，龍門宿鳥還。","牛羊平野外，桑柘夕煙間。","不及鄉園叟，悠悠盡日閑。"]', '["伊川新雨霽，原上见春山。","緱嶺晴虹斷，龙门宿鸟還。","牛羊平野外，桑柘夕煙间。","不及乡园叟，悠悠尽日闲。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶晚眺 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59deff5a-0aef-479c-831b-b08119cc2119', '憶平泉雜詠 憶新藤', '憶平泉杂詠 憶新藤', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["遙聞碧潭上，春晚紫藤開。","水似晨霞照，林疑綵鳳來。","清香凝島嶼，繁豔映莓苔。","金谷如相並，應將錦帳回。"]', '["遙闻碧潭上，春晚紫藤开。","水似晨霞照，林疑綵鳳来。","清香凝島嶼，繁豔映莓苔。","金谷如相並，應將錦帳回。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶新藤 李德裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c58fe99-845d-485b-aac7-c69b1c22aed4', '憶平泉雜詠 憶春耕', '憶平泉杂詠 憶春耕', '2679f91e-92e0-4c38-9a7a-77500b6bd09c', '唐', '["郊外杏花坼，林間布穀鳴。","原田春雨後，谿水夕流平。","野老荷蓑至，和風吹草輕。","無因共沮溺，相與事巖耕。"]', '["郊外杏花坼，林间布穀鳴。","原田春雨後，谿水夕流平。","野老荷蓑至，和风吹草轻。","無因共沮溺，相與事巖耕。"]', '诗', 'shi', '', NULL, '憶平泉雜詠 憶春耕 李德裕 shi');
